function getSiaVolumeAssignedFrequencies(item) {
    if (!isSiaFlightInformationSector(item)) return [];
    const code = String(item?.c || '').trim().toUpperCase();
    const values = SIA_SIV_VOLUME_FREQUENCIES[code];
    return Array.isArray(values) ? values : [];
}

function getSiaEffectiveFilterKey(item) {
    if (isSiaFlightInformationSector(item)) return 'ase:SIV';
    return String(item?.k || '').trim();
}

function migrateSiaSivFilterPreference() {
    const prefs = loadSiaFilterPrefs();
    if (prefs['ase:SIV'] !== undefined) return;

    /*
     * Avant v15.65, les SIV dépendaient du bouton RAS. On reprend son état
     * lors de la première ouverture afin de ne pas faire disparaître un calque
     * qui était déjà affiché.
     */
    if (prefs['ase:RAS'] !== undefined) {
        prefs['ase:SIV'] = prefs['ase:RAS'] === true;
        saveSiaFilterPrefs();
    }
}

function isSiaHideAboveFl115Enabled() {
    return loadSiaFilterPrefs()[SIA_HIDE_ABOVE_FL115_PREF_KEY] === true;
}

function setSiaHideAboveFl115Enabled(enabled) {
    loadSiaFilterPrefs()[SIA_HIDE_ABOVE_FL115_PREF_KEY] = !!enabled;
    saveSiaFilterPrefs();
}

function getSiaAirspaceLowerLimitFeetForFilter(item) {
    const raw = item?.lo;
    if (!Array.isArray(raw)) return null;

    const ref = String(raw?.[0] || '').trim().toUpperCase();
    const value = Number(raw?.[1]);
    const unit = String(raw?.[2] || '').trim().toUpperCase();
    if (!Number.isFinite(value)) return null;

    if (ref === 'STD' && unit === 'FL') return value * 100;
    if ((ref === 'ALT' || ref === 'HEI') && unit === 'FT') return value;
    return null;
}

function shouldHideSiaAirspaceAboveFl115(item) {
    if (!isSiaHideAboveFl115Enabled()) return false;
    const lowerFeet = getSiaAirspaceLowerLimitFeetForFilter(item);
    // Une limite non interprétable reste visible par sécurité.
    return Number.isFinite(lowerFeet) && lowerFeet >= SIA_HIDE_ABOVE_FL115_FEET;
}

function ensureSiaMapPanes() {
    if (!map || !map.createPane) return;

    if (!map.getPane('siaAirspacePane')) {
        map.createPane('siaAirspacePane');
        const pane = map.getPane('siaAirspacePane');
        if (pane) pane.style.zIndex = '440';
    }

    if (!map.getPane('siaCtrTouchPane')) {
        map.createPane('siaCtrTouchPane');
        const pane = map.getPane('siaCtrTouchPane');
        if (pane) pane.style.zIndex = '445';
    }

    if (!map.getPane('siaSelectionPane')) {
        map.createPane('siaSelectionPane');
        const pane = map.getPane('siaSelectionPane');
        if (pane) {
            pane.style.zIndex = '448';
            pane.style.pointerEvents = 'none';
        }
    }

    if (!map.getPane('siaPointPane')) {
        map.createPane('siaPointPane');
        const pane = map.getPane('siaPointPane');
        if (pane) pane.style.zIndex = '555';
    }

    if (!map.getPane('siaPointTouchPane')) {
        map.createPane('siaPointTouchPane');
        const pane = map.getPane('siaPointTouchPane');
        if (pane) {
            pane.style.zIndex = '660';
            pane.style.pointerEvents = 'auto';
        }
    }

    if (!map.getPane('npfTouchPane')) {
        map.createPane('npfTouchPane');
        const pane = map.getPane('npfTouchPane');
        if (pane) {
            pane.style.zIndex = '665';
            pane.style.pointerEvents = 'auto';
        }
    }

    // v15.50 — les hitboxes utilisent SVG plutôt qu'un DIV vide :
    // c'est beaucoup plus fiable pour le hit-testing tactile Safari/iPad.
    if (!siaPointTouchRenderer && L.svg) {
        siaPointTouchRenderer = L.svg({ padding: 0.35, pane: 'siaPointTouchPane' });
    }
    if (!npfTouchRenderer && L.svg) {
        npfTouchRenderer = L.svg({ padding: 0.35, pane: 'npfTouchPane' });
    }

    if (!siaAirspaceRenderer && L.canvas) {
        siaAirspaceRenderer = L.canvas({ padding: 0.35, pane: 'siaAirspacePane' });
    }
    if (!siaCtrTouchRenderer && L.svg) {
        siaCtrTouchRenderer = L.svg({ padding: 0.35, pane: 'siaCtrTouchPane' });
    }
    if (!siaSelectionRenderer && L.svg) {
        siaSelectionRenderer = L.svg({ padding: 0.35, pane: 'siaSelectionPane' });
    }
    if (!siaPointRenderer && L.canvas) {
        siaPointRenderer = L.canvas({ padding: 0.35, pane: 'siaPointPane' });
    }
}

function clearSiaRenderedLayers() {
    siaRenderedCoverageBounds = null;
    siaRenderedZoom = null;
    siaRenderedSignature = '';
    siaRenderedAirspaceFeatures = [];
    siaZoomDependentLayers = [];
    siaRenderedShowDesignatedPoints = null;
    siaRenderedPointLabelsEnabled = null;
    clearSiaSelectionHighlight();
    siaSelectedCtrTouchLayer = null;
    siaSelectedCtrKey = null;
    siaSelectedAirspaceItem = null;
    siaSelectedAirspaceGeometry = null;
    siaAirspaceTouchEntries = [];
    if (siaLayerGroup) {
        try { siaLayerGroup.clearLayers(); } catch (_) {}
    }
}

function normalizeSiaFilterCounts(dataset) {
    const counts = new Map();
    const add = (key) => counts.set(key, (counts.get(key) || 0) + 1);
    (dataset?.terrain || []).forEach(item => add(item.k));
    (dataset?.points || []).forEach(item => add(item.k));
    (dataset?.airspaces || []).forEach(item => {
        if (isSiaTechnicalSivParent(item, dataset)) return;
        add(getSiaEffectiveFilterKey(item));
    });
    return counts;
}

function getSiaFilterSections(dataset) {
    migrateSiaSivFilterPreference();
    const counts = normalizeSiaFilterCounts(dataset);
    const count = (key) => counts.get(key) || 0;

    const orderedAseTypes = [
        'CTR', 'TMA', 'CTA', 'SIV', 'FIR', 'UIR', 'UIR-P', 'UTA', 'OCA',
        'SECTOR', 'SECTOR-C', 'RAS', 'TRA', 'P', 'R', 'D'
    ];
    const aseLabels = {
        CTR: 'CTR',
        TMA: 'TMA',
        CTA: 'CTA',
        SIV: 'SIV — Secteurs d’information de vol',
        FIR: 'FIR',
        UIR: 'UIR',
        'UIR-P': 'UIR-P',
        UTA: 'UTA',
        OCA: 'OCA',
        SECTOR: 'SECTOR',
        'SECTOR-C': 'SECTOR-C',
        RAS: 'RAS — Autres espaces réglementés',
        TRA: 'TRA — Zone temporairement réservée',
        P: 'Zones P',
        R: 'Zones R',
        D: 'Zones D'
    };

    const dOtherOrder = [
        'AER', 'VOL', 'SUR', 'PJE', 'PRN', 'TRVL', 'TRPLA',
        'AP', 'LTA', 'BAL', 'UAC', 'ACC', 'TRPVL'
    ];
    const dOtherLabels = {
        AER: 'AER — Aéromodélisme',
        VOL: 'VOL — Voltige',
        SUR: 'SUR — Restriction de survol',
        PJE: 'PJE — Parachutage',
        PRN: 'PRN — Parcs / réserves naturelles',
        TRVL: 'TRVL — Treuillage vol libre',
        TRPLA: 'TRPLA — Treuillage planeurs',
        AP: 'AP — Activité particulière / UAS',
        LTA: 'LTA — Lower Traffic Area',
        BAL: 'BAL — Ballons',
        UAC: 'UAC — Contrôle supérieur',
        ACC: 'ACC — Contrôle régional',
        TRPVL: 'TRPVL — Treuillage planeurs / vol libre'
    };

    const sections = [
        {
            title: 'Terrains',
            items: [
                { key: 'ahp:AD', label: 'Aérodromes AD', count: count('ahp:AD') },
                { key: 'ahp:HP', label: 'Hélistations HP', count: count('ahp:HP') },
                { key: 'ahp:LS', label: 'Landing sites LS', count: count('ahp:LS') }
            ]
        },
        {
            title: 'Points non-IFR',
            items: [
                { key: 'dpn:VRP', label: 'Points VFR / VRP', count: count('dpn:VRP') },
                { key: 'dpn:OTHER', label: 'Autres points OTHER', count: count('dpn:OTHER') },
                { key: 'dpn:ADHP', label: 'Points ADHP', count: count('dpn:ADHP') }
            ]
        },
        {
            title: 'Espaces aériens / zones',
            items: orderedAseTypes
                .map(type => ({
                    key: `ase:${type}`,
                    label: aseLabels[type] || type,
                    count: count(`ase:${type}`)
                }))
                .filter(item => item.count > 0)
        },
        {
            title: 'D-OTHER — sous-types SIA',
            items: dOtherOrder
                .map(type => ({
                    key: `ase:D-OTHER:${type}`,
                    label: dOtherLabels[type] || type,
                    count: count(`ase:D-OTHER:${type}`)
                }))
                .filter(item => item.count > 0)
        }
    ];

    return sections;
}

function ensureSiaFilterModal() {
    let modal = document.getElementById('sia-filter-modal');
    if (modal) return modal;

    modal = document.createElement('div');
    modal.id = 'sia-filter-modal';
    modal.className = 'sia-filter-modal';
    modal.setAttribute('aria-hidden', 'true');
    modal.innerHTML = `
        <div class="sia-filter-card" role="dialog" aria-modal="true" aria-labelledby="sia-filter-title">
            <button type="button" class="sia-filter-close" id="sia-filter-close" aria-label="Fermer">&times;</button>
            <h2 id="sia-filter-title">CALQUES AÉRONAUTIQUES SIA</h2>
            <div class="sia-filter-subtitle">
                AIRAC <strong>${SIA_EMBEDDED_META.airac}</strong> — effet ${SIA_EMBEDDED_META.effectiveDate.split('-').reverse().join('/')}
                — points IFR ICAO exclus
            </div>
            <div class="sia-filter-global-actions">
                <button type="button" id="sia-filter-show-all">Tout afficher</button>
                <button type="button" id="sia-filter-hide-all">Tout masquer</button>
                <button type="button"
                        id="sia-profile-button"
                        aria-pressed="false"
                        title="Afficher ou masquer la coupe verticale des espaces devant l'avion">
                    PROFIL ESPACES
                </button>
                <label class="sia-filter-altitude-option"
                       title="Masquer les zones dont le plancher est au FL115 / 11 500 ft ou au-dessus">
                    <input type="checkbox" id="sia-filter-hide-above-fl115">
                    <span>Masquer zones &gt; FL115</span>
                </label>
            </div>
            <div id="sia-filter-sections" class="sia-filter-sections">
                <div class="sia-filter-loading">Chargement des données SIA…</div>
            </div>
            <div class="sia-filter-footer">
                <span id="sia-filter-footer-status">Les choix sont mémorisés sur cet appareil.</span>
                <button type="button" id="sia-filter-done">Fermer</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);

    // v15.61 — le bouton PROFIL vit désormais dans ce menu dynamique.
    initializeSiaAirspaceProfileUi();

    const close = () => {
        modal.classList.remove('open');
        modal.setAttribute('aria-hidden', 'true');
    };

    modal.querySelector('#sia-filter-close')?.addEventListener('click', close);
    modal.querySelector('#sia-filter-done')?.addEventListener('click', close);
    modal.addEventListener('click', event => {
        if (event.target === modal) close();
    });

    modal.querySelector('#sia-filter-show-all')?.addEventListener('click', () => {
        modal.querySelectorAll('input[data-sia-filter-key]').forEach(input => {
            input.checked = true;
            setSiaFilterEnabled(input.dataset.siaFilterKey, true);
        });
        scheduleSiaLayerRefresh('filters-all');
    });

    modal.querySelector('#sia-filter-hide-all')?.addEventListener('click', () => {
        modal.querySelectorAll('input[data-sia-filter-key]').forEach(input => {
            input.checked = false;
            setSiaFilterEnabled(input.dataset.siaFilterKey, false);
        });
        scheduleSiaLayerRefresh('filters-none');
    });

    const altitudeFilterInput = modal.querySelector('#sia-filter-hide-above-fl115');
    if (altitudeFilterInput) {
        altitudeFilterInput.checked = isSiaHideAboveFl115Enabled();
        altitudeFilterInput.addEventListener('change', () => {
            setSiaHideAboveFl115Enabled(altitudeFilterInput.checked);
            scheduleSiaLayerRefresh('altitude-filter-change');
            scheduleSiaProfileRefresh('altitude-filter-change');
        });
    }

    modal.querySelector('#sia-filter-sections')?.addEventListener('change', event => {
        const input = event.target?.closest?.('input[data-sia-filter-key]');
        if (!input) return;
        setSiaFilterEnabled(input.dataset.siaFilterKey, input.checked);
        scheduleSiaLayerRefresh('filter-change');
    });

    return modal;
}

function renderSiaFilterModal(dataset) {
    const modal = ensureSiaFilterModal();
    const container = modal.querySelector('#sia-filter-sections');
    if (!container) return;

    const sections = getSiaFilterSections(dataset);
    const prefs = loadSiaFilterPrefs();
    const altitudeFilterInput = modal.querySelector('#sia-filter-hide-above-fl115');
    if (altitudeFilterInput) altitudeFilterInput.checked = isSiaHideAboveFl115Enabled();

    container.innerHTML = sections.map(section => `
        <section class="sia-filter-section">
            <h3>${escapeHtml(section.title)}</h3>
            <div class="sia-filter-grid">
                ${section.items.map(item => `
                    <label class="sia-filter-item">
                        <input type="checkbox"
                               data-sia-filter-key="${escapeHtml(item.key)}"
                               ${prefs[item.key] === true ? 'checked' : ''}>
                        <span class="sia-filter-item-label">${escapeHtml(item.label)}</span>
                        <span class="sia-filter-item-count">${item.count}</span>
                    </label>
                `).join('')}
            </div>
        </section>
    `).join('');
}

async function openSiaFilterDialog() {
    const modal = ensureSiaFilterModal();
    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');

    const container = modal.querySelector('#sia-filter-sections');
    if (container) container.innerHTML = '<div class="sia-filter-loading">Chargement des données SIA…</div>';

    try {
        const dataset = await ensureSiaDatasetLoaded();
        renderSiaFilterModal(dataset);
        await refreshSiaManagementStatus();
        scheduleSiaLayerRefresh('filter-open');
    } catch (error) {
        console.error('[SIA] Ouverture filtres impossible:', error);
        if (container) {
            container.innerHTML = `<div class="sia-filter-error">Impossible de charger les données SIA : ${escapeHtml(error.message || String(error))}</div>`;
        }
    }
}

function installQuickOfflineMapButtonInteractions(button) {
    if (!button || button.dataset.siaLongPressBound === '1') return;
    button.dataset.siaLongPressBound = '1';

    try {
        button.setAttribute('draggable', 'false');
        button.querySelectorAll('*').forEach(child => child.setAttribute('draggable', 'false'));
    } catch (_) {}

    let longPressTimer = null;
    let longPressTriggered = false;

    const clearLongPress = () => {
        if (longPressTimer) {
            clearTimeout(longPressTimer);
            longPressTimer = null;
        }
    };

    const startLongPress = event => {
        if (event && event.button !== undefined && event.button !== 0) return;
        if (event && typeof event.preventDefault === 'function') event.preventDefault();
        clearLongPress();
        longPressTriggered = false;
        longPressTimer = setTimeout(() => {
            longPressTriggered = true;
            openSiaFilterDialog();
        }, 650);
    };

    button.addEventListener('selectstart', event => event.preventDefault());
    button.addEventListener('dragstart', event => event.preventDefault());
    button.addEventListener('pointerdown', startLongPress);
    button.addEventListener('pointerup', clearLongPress);
    button.addEventListener('pointerleave', clearLongPress);
    button.addEventListener('pointercancel', clearLongPress);
    button.addEventListener('contextmenu', event => {
        event.preventDefault();
        clearLongPress();
        longPressTriggered = true;
        openSiaFilterDialog();
    });
    button.addEventListener('click', event => {
        if (longPressTriggered) {
            event.preventDefault();
            event.stopPropagation();
            longPressTriggered = false;
            return;
        }
        openQuickOfflineMapSelector();
    });
}

function siaCompactGeometryToGeoJson(compact) {
    if (!Array.isArray(compact) || compact.length < 2) return null;
    const typeMap = {
        P: 'Point',
        G: 'Polygon',
        M: 'MultiPolygon',
        L: 'LineString',
        N: 'MultiLineString'
    };
    const type = typeMap[compact[0]] || compact[0];
    return { type, coordinates: compact[1] };
}

function siaBoundsIntersects(featureBounds, leafletBounds) {
    if (!Array.isArray(featureBounds) || featureBounds.length !== 4 || !leafletBounds) return true;
    const minLon = featureBounds[0];
    const minLat = featureBounds[1];
    const maxLon = featureBounds[2];
    const maxLat = featureBounds[3];

    if (maxLat < leafletBounds.getSouth() || minLat > leafletBounds.getNorth()) return false;

    const west = leafletBounds.getWest();
    const east = leafletBounds.getEast();
    if (west <= east) {
        return !(maxLon < west || minLon > east);
    }
    return maxLon >= west || minLon <= east;
}

function formatSiaVertical(raw) {
    if (!Array.isArray(raw)) return '—';
    const ref = String(raw[0] || '');
    const value = String(raw[1] || '');
    const unit = String(raw[2] || '');
    if (!value) return '—';

    const numeric = Number(value);
    if (ref === 'HEI' && Number.isFinite(numeric) && numeric === 0) return 'SFC';
    if (ref === 'STD' && unit === 'FL') return `FL${value}`;
    if (unit === 'FT') return `${value} ft${ref === 'ALT' ? ' AMSL' : ref === 'HEI' ? ' AGL' : ''}`;
    if (unit) return `${value} ${unit}`;
    return value;
}

function isCurrentOfflineOaciMap() {
    if (mapSourceMode !== 'offline') return false;
    const activeGroup = String(getQuickOfflineActiveGroupName() || '').trim();
    if (/\bOACI\b/i.test(activeGroup)) return true;

    return (Array.isArray(activeOfflinePacks) ? activeOfflinePacks : []).some(pack => {
        const group = String(getOfflinePackGroupName(pack) || '');
        return /\bOACI\b/i.test(group) || /\bOACI\b/i.test(String(pack || ''));
    });
}

function getSiaAirspaceStyle(item) {
    const type = String(item?.t || '');
    const local = String(item?.l || '');

    let color = '#3559e0';
    let dashArray = null;
    let fillOpacity = 0;

    if (type === 'P') color = '#d50000';
    else if (type === 'R') color = '#ff6d00';
    else if (type === 'D') color = '#e91e63';
    else if (type === 'TRA') { color = '#ff6d00'; dashArray = '7 5'; }
    else if (type === 'CTR') color = '#0066ff';
    else if (type === 'TMA') color = '#673ab7';
    else if (type === 'CTA') color = '#3f51b5';
    else if (type === 'FIR' || type === 'UIR' || type === 'UIR-P' || type === 'UTA' || type === 'OCA') {
        color = '#455a64';
        dashArray = '9 6';
        fillOpacity = 0;
    } else if (type === 'SECTOR' || type === 'SECTOR-C' || type === 'RAS') {
        color = '#607d8b';
        dashArray = '6 5';
        fillOpacity = 0;
    } else if (type === 'D-OTHER') {
        color = '#8e24aa';
        dashArray = '5 4';
        if (local === 'PJE') color = '#d81b60';
        else if (local === 'AER') color = '#00897b';
        else if (local === 'VOL') color = '#3949ab';
        else if (local === 'SUR') color = '#6d4c41';
        else if (local === 'PRN') color = '#f4511e';
        else if (local === 'BAL') color = '#7b1fa2';
    }

    return {
        color,
        weight: 2.2,
        opacity: 0.95,
        fillColor: color,
        fillOpacity,
        dashArray,
        lineCap: 'round',
        lineJoin: 'round'
    };
}

function buildSiaAirspacePopup(item) {
    const typeLabel = item.t === 'D-OTHER' && item.l
        ? `${item.t} / ${item.l}`
        : item.t;
    const name = [item.c, item.n].filter(Boolean).join(' — ');
    const remark = String(item.r || '').trim();

    return `
        <div class="sia-popup">
            <div class="sia-popup-title">${escapeHtml(name || typeLabel || 'Espace SIA')}</div>
            <div><strong>Type :</strong> ${escapeHtml(typeLabel || '—')}</div>
            ${item.cl ? `<div><strong>Classe :</strong> ${escapeHtml(item.cl)}</div>` : ''}
            <div><strong>Plancher :</strong> ${escapeHtml(formatSiaVertical(item.lo))}</div>
            <div><strong>Plafond :</strong> ${escapeHtml(formatSiaVertical(item.up))}</div>
            ${item.a ? `<div><strong>Activité :</strong> ${escapeHtml(item.a)}</div>` : ''}
            ${remark ? `<div class="sia-popup-remark">${escapeHtml(remark).replace(/#|\n/g, '<br>')}</div>` : ''}
        </div>
    `;
}

function getSiaTerrainMarkerStyle(item) {
    if (item.t === 'HP') {
        return { radius: 5, color: '#0b6e4f', weight: 2, fillColor: '#48d597', fillOpacity: 0.95 };
    }
    if (item.t === 'LS') {
        return { radius: 4, color: '#37474f', weight: 2, fillColor: '#cfd8dc', fillOpacity: 0.95 };
    }
    return { radius: 5, color: '#0d47a1', weight: 2, fillColor: '#42a5f5', fillOpacity: 0.95 };
}

function buildSiaTerrainPopup(item) {
    const typeLabel = item.t === 'AD' ? 'Aérodrome' : item.t === 'HP' ? 'Hélistation' : 'Landing site';
    const elevation = item.e ? `${item.e} ${item.u || 'FT'}` : '—';
    return `
        <div class="sia-popup">
            <div class="sia-popup-title">${escapeHtml([item.c, item.n].filter(Boolean).join(' — '))}</div>
            <div><strong>Type :</strong> ${escapeHtml(typeLabel)}</div>
            <div><strong>Altitude :</strong> ${escapeHtml(elevation)}</div>
            ${item.city ? `<div><strong>Ville :</strong> ${escapeHtml(item.city)}</div>` : ''}
            <div><strong>Coordonnées :</strong> ${Number(item.x).toFixed(5)}, ${Number(item.y).toFixed(5)}</div>
            ${item.s ? `<div class="sia-popup-remark">${escapeHtml(item.s).replace(/#|\n/g, '<br>')}</div>` : ''}
        </div>
    `;
}

const SIA_VRP_AIRPORT_COLOR_PALETTE = Object.freeze([
    '#ff00ff', // magenta
    '#ffff00', // jaune
    '#00e5ff', // cyan
    '#39ff14', // vert fluorescent
    '#ff7a00', // orange
    '#ff1744', // rouge vif
    '#7c4dff', // violet électrique
    '#00ff95', // turquoise fluorescent
    '#2979ff'  // bleu électrique
]);
const SIA_VRP_AIRPORT_COLOR_OVERRIDES = Object.freeze({
    LFTW: '#ff00ff', // Nîmes-Garons
    LFMT: '#ffff00'  // Montpellier-Méditerranée
});
/*
 * v15.79 — « voisin » signifie ici terrain suffisamment proche pour que ses
 * VRP puissent être visibles dans la même zone opérationnelle. À 55 NM, le
 * dataset AIRAC 08/26 est coloriable avec la palette limitée de 9 couleurs,
 * sans conflit entre voisins (notamment LFTW / LFMI).
 */
const SIA_VRP_NEIGHBOUR_DISTANCE_NM = 55;
let siaVrpAirportColorMap = null;
let siaVrpAirportColorDataset = null;

/*
 * v15.90 — certains VRP SIA sont publiés sans AhpUidAssoc alors que leur
 * appartenance est évidente dans le groupe local. On ne modifie pas sia.js :
 * un rattachement de secours est calculé uniquement lorsque le voisinage est
 * suffisamment dominant. Les cas ambigus restent volontairement non rattachés.
 */
const SIA_VRP_INFERENCE_RADIUS_NM = 25;
const SIA_VRP_INFERENCE_MIN_SHARE = 0.52;
const SIA_VRP_INFERENCE_MIN_MARGIN = 0.18;
const SIA_VRP_INFERENCE_MIN_SUPPORT = 3;
const SIA_VRP_INFERENCE_MAX_NEAREST_NM = 10;
const SIA_VRP_INFERRED_AIRPORT_OVERRIDES = Object.freeze({
    MMND: 'LFMC',
    MMSR: 'LFML'
});
let siaVrpInferredAirportMap = null;
let siaVrpInferredAirportDataset = null;

function getSiaVrpInferenceKey(item) {
    return [
        String(item?.c || '').trim().toUpperCase(),
        Number(item?.x).toFixed(6),
        Number(item?.y).toFixed(6)
    ].join('|');
}

function buildSiaVrpInferredAirportMap(dataset) {
    const inferred = new Map();
    if (!dataset) return inferred;

    const vrps = (dataset.points || []).filter(item => item?.k === 'dpn:VRP');
    const assigned = vrps.filter(item => String(item?.a || '').trim());
    const airportSet = new Set(
        assigned.map(item => String(item.a || '').trim().toUpperCase()).filter(Boolean)
    );

    for (const item of vrps) {
        if (String(item?.a || '').trim()) continue;

        const key = getSiaVrpInferenceKey(item);
        const codeId = String(item?.c || '').trim().toUpperCase();
        const forcedAirport = SIA_VRP_INFERRED_AIRPORT_OVERRIDES[codeId];
        if (forcedAirport && airportSet.has(forcedAirport)) {
            inferred.set(key, forcedAirport);
            continue;
        }

        const lat = Number(item?.x);
        const lon = Number(item?.y);
        if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

        const stats = new Map();
        for (const candidate of assigned) {
            const candidateLat = Number(candidate?.x);
            const candidateLon = Number(candidate?.y);
            if (!Number.isFinite(candidateLat) || !Number.isFinite(candidateLon)) continue;

            const distance = calculateDistanceInNm(lat, lon, candidateLat, candidateLon);
            if (!Number.isFinite(distance) || distance > SIA_VRP_INFERENCE_RADIUS_NM) continue;

            const airport = String(candidate?.a || '').trim().toUpperCase();
            if (!airport) continue;

            const current = stats.get(airport) || { weight: 0, count: 0, nearest: Infinity };
            current.weight += 1 / Math.pow(Math.max(distance, 1), 1.5);
            current.count += 1;
            current.nearest = Math.min(current.nearest, distance);
            stats.set(airport, current);
        }

        if (!stats.size) continue;
        const ranked = Array.from(stats.entries()).sort((a, b) => b[1].weight - a[1].weight);
        const totalWeight = ranked.reduce((sum, entry) => sum + entry[1].weight, 0);
        if (!(totalWeight > 0)) continue;

        const [topAirport, topStats] = ranked[0];
        const secondWeight = ranked.length > 1 ? ranked[1][1].weight : 0;
        const topShare = topStats.weight / totalWeight;
        const secondShare = secondWeight / totalWeight;

        if (
            topStats.count >= SIA_VRP_INFERENCE_MIN_SUPPORT
            && topStats.nearest <= SIA_VRP_INFERENCE_MAX_NEAREST_NM
            && topShare >= SIA_VRP_INFERENCE_MIN_SHARE
            && (topShare - secondShare) >= SIA_VRP_INFERENCE_MIN_MARGIN
        ) {
            inferred.set(key, topAirport);
        }
    }

    return inferred;
}

function ensureSiaVrpInferredAirportMap(dataset = siaDataset) {
    if (siaVrpInferredAirportMap && siaVrpInferredAirportDataset === dataset) {
        return siaVrpInferredAirportMap;
    }
    siaVrpInferredAirportDataset = dataset || null;
    siaVrpInferredAirportMap = buildSiaVrpInferredAirportMap(dataset);
    return siaVrpInferredAirportMap;
}

function getSiaVrpAirportCode(item) {
    const officialAirport = String(item?.a || '').trim().toUpperCase();
    if (officialAirport) return officialAirport;
    if (item?.k !== 'dpn:VRP') return '';
    return ensureSiaVrpInferredAirportMap().get(getSiaVrpInferenceKey(item)) || '';
}

function getSiaVrpReadableTextColor(background) {
    const hex = String(background || '').replace('#', '');
    if (!/^[0-9a-f]{6}$/i.test(hex)) return '#ffffff';
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    const luminance = (0.299 * r) + (0.587 * g) + (0.114 * b);
    return luminance >= 150 ? '#000000' : '#ffffff';
}

function buildSiaVrpAirportColorMap(dataset) {
    const mapByAirport = new Map();
    if (!dataset) return mapByAirport;

    const airports = Array.from(new Set(
        (dataset.points || [])
            .filter(item => item?.k === 'dpn:VRP')
            .map(item => String(item?.a || '').trim().toUpperCase())
            .filter(Boolean)
    ));

    const airportSet = new Set(airports);
    const coordsByAirport = new Map();
    for (const terrain of dataset.terrain || []) {
        const code = String(terrain?.c || '').trim().toUpperCase();
        if (!airportSet.has(code) || coordsByAirport.has(code)) continue;
        const lat = Number(terrain?.x);
        const lon = Number(terrain?.y);
        if (Number.isFinite(lat) && Number.isFinite(lon)) {
            coordsByAirport.set(code, { lat, lon });
        }
    }

    const neighbours = new Map(airports.map(code => [code, new Set()]));
    for (let i = 0; i < airports.length; i += 1) {
        const aCode = airports[i];
        const a = coordsByAirport.get(aCode);
        if (!a) continue;
        for (let j = i + 1; j < airports.length; j += 1) {
            const bCode = airports[j];
            const b = coordsByAirport.get(bCode);
            if (!b) continue;
            const distance = calculateDistanceInNm(a.lat, a.lon, b.lat, b.lon);
            if (Number.isFinite(distance) && distance <= SIA_VRP_NEIGHBOUR_DISTANCE_NM) {
                neighbours.get(aCode).add(bCode);
                neighbours.get(bCode).add(aCode);
            }
        }
    }

    const paletteIndexByColor = new Map(
        SIA_VRP_AIRPORT_COLOR_PALETTE.map((color, index) => [color.toLowerCase(), index])
    );
    const assignedIndex = new Map();
    const usage = new Array(SIA_VRP_AIRPORT_COLOR_PALETTE.length).fill(0);

    Object.entries(SIA_VRP_AIRPORT_COLOR_OVERRIDES).forEach(([code, color]) => {
        const index = paletteIndexByColor.get(String(color).toLowerCase());
        if (Number.isInteger(index) && airportSet.has(code)) {
            assignedIndex.set(code, index);
            usage[index] += 1;
        }
    });

    const stableSeed = code => Array.from(code).reduce(
        (sum, char) => ((sum * 33) + char.charCodeAt(0)) >>> 0,
        5381
    );

    /*
     * DSATUR : on traite d'abord le terrain dont les voisins déjà colorés
     * utilisent le plus de couleurs différentes. Contrairement à v15.78, une
     * couleur déjà utilisée par un voisin n'est PAS candidate tant qu'une
     * couleur libre existe.
     */
    while (assignedIndex.size < airports.length) {
        const unassigned = airports.filter(code => !assignedIndex.has(code));
        if (!unassigned.length) break;

        unassigned.sort((a, b) => {
            const saturationA = new Set(
                Array.from(neighbours.get(a) || [])
                    .map(code => assignedIndex.get(code))
                    .filter(Number.isInteger)
            ).size;
            const saturationB = new Set(
                Array.from(neighbours.get(b) || [])
                    .map(code => assignedIndex.get(code))
                    .filter(Number.isInteger)
            ).size;
            if (saturationA !== saturationB) return saturationB - saturationA;
            const degreeA = neighbours.get(a)?.size || 0;
            const degreeB = neighbours.get(b)?.size || 0;
            if (degreeA !== degreeB) return degreeB - degreeA;
            return a.localeCompare(b);
        });

        const code = unassigned[0];
        const usedByNeighbours = new Set(
            Array.from(neighbours.get(code) || [])
                .map(neighbourCode => assignedIndex.get(neighbourCode))
                .filter(Number.isInteger)
        );

        let candidates = SIA_VRP_AIRPORT_COLOR_PALETTE
            .map((_color, index) => index)
            .filter(index => !usedByNeighbours.has(index));

        /*
         * Garde-fou pour un futur AIRAC plus dense : sur le dataset actuel ce
         * repli n'est jamais utilisé. S'il devenait nécessaire, on minimise
         * alors le nombre de conflits au lieu d'échouer complètement.
         */
        if (!candidates.length) {
            let minimumConflicts = Infinity;
            candidates = [];
            SIA_VRP_AIRPORT_COLOR_PALETTE.forEach((_color, index) => {
                const conflicts = Array.from(neighbours.get(code) || [])
                    .reduce((count, neighbourCode) => (
                        count + (assignedIndex.get(neighbourCode) === index ? 1 : 0)
                    ), 0);
                if (conflicts < minimumConflicts) {
                    minimumConflicts = conflicts;
                    candidates = [index];
                } else if (conflicts === minimumConflicts) {
                    candidates.push(index);
                }
            });
        }

        const seed = stableSeed(code) % SIA_VRP_AIRPORT_COLOR_PALETTE.length;
        candidates.sort((a, b) => (
            usage[a] - usage[b]
            || ((a - seed + SIA_VRP_AIRPORT_COLOR_PALETTE.length) % SIA_VRP_AIRPORT_COLOR_PALETTE.length)
                - ((b - seed + SIA_VRP_AIRPORT_COLOR_PALETTE.length) % SIA_VRP_AIRPORT_COLOR_PALETTE.length)
        ));

        const chosenIndex = candidates[0] ?? 0;
        assignedIndex.set(code, chosenIndex);
        usage[chosenIndex] += 1;
    }

    airports.forEach(code => {
        const forced = SIA_VRP_AIRPORT_COLOR_OVERRIDES[code];
        const index = assignedIndex.get(code);
        const background = forced
            || SIA_VRP_AIRPORT_COLOR_PALETTE[Number.isInteger(index) ? index : 0];
        mapByAirport.set(code, {
            background,
            foreground: getSiaVrpReadableTextColor(background)
        });
    });

    return mapByAirport;
}

function ensureSiaVrpAirportColorMap(dataset = siaDataset) {
    if (siaVrpAirportColorMap && siaVrpAirportColorDataset === dataset) return siaVrpAirportColorMap;
    siaVrpAirportColorDataset = dataset || null;
    siaVrpAirportColorMap = buildSiaVrpAirportColorMap(dataset);
    return siaVrpAirportColorMap;
}

function getSiaVrpAirportVisual(item) {
    const airport = getSiaVrpAirportCode(item);
    if (!airport) {
        return { background: '#ff00ff', foreground: '#ffffff' };
    }
    const mapByAirport = ensureSiaVrpAirportColorMap();
    return mapByAirport.get(airport) || { background: '#ff00ff', foreground: '#ffffff' };
}

function getSiaPointMarkerStyle(item) {
    if (item.k === 'dpn:VRP') {
        const visual = getSiaVrpAirportVisual(item);
        return { radius: 4.5, color: '#111111', weight: 1.5, fillColor: visual.background, fillOpacity: 1 };
    }
    if (item.k === 'dpn:ADHP') {
        return { radius: 3.5, color: '#263238', weight: 1.5, fillColor: '#90a4ae', fillOpacity: 0.9 };
    }
    return { radius: 4, color: '#4a148c', weight: 1.5, fillColor: '#e040fb', fillOpacity: 0.95 };
}

function buildSiaPointPopup(item) {
    /*
     * v15.49 — VRP : titre compact (ex. AS-LFMA), sans répétition des
     * informations déjà présentes dans le titre et sans coordonnées.
     */
    if (item.k === 'dpn:VRP') {
        const code = String(item.d || getSiaVrpSymbolText(item) || item.c || '').trim();
        const airport = getSiaVrpAirportCode(item);
        const title = airport ? `${code}-${airport}` : code;
        const remark = String(item.r || '').trim().replace(/^VRP\s*[-:]?\s*/i, '');

        const encodedWpName = encodeURIComponent(title || code || 'Point VFR');
        const wpLat = Number(item.x);
        const wpLon = Number(item.y);
        const existingWp = getNpfWaypointForVfr(title || code || 'Point VFR', wpLat, wpLon);
        const waypointActions = existingWp
            ? `<div class="npf-waypoint-popup-actions npf-source-waypoint-actions sia-vrp-existing-wp-actions">${buildNpfWaypointActionsHtml(existingWp)}</div>`
            : `<div class="sia-vrp-popup-actions"><button type="button" class="sia-vrp-add-wp-btn" onclick="window.addNpfWaypointFromVfr('${encodedWpName}', ${wpLat}, ${wpLon})">Ajout WP</button></div>`;
        return `
            <div class="sia-popup sia-vrp-popup">
                <div class="sia-popup-title">${escapeHtml(title || 'Point VFR')}</div>
                ${remark ? `<div class="sia-popup-remark">${escapeHtml(remark).replace(/#|\n/g, '<br>')}</div>` : ''}
                ${waypointActions}
            </div>
        `;
    }

    const title = [item.d || item.c, item.a].filter(Boolean).join(' — ');
    const remark = String(item.r || '').trim();
    return `
        <div class="sia-popup">
            <div class="sia-popup-title">${escapeHtml(title || item.c || 'Point SIA')}</div>
            ${item.n && item.n !== item.d ? `<div><strong>Nom SIA :</strong> ${escapeHtml(item.n)}</div>` : ''}
            ${item.a ? `<div><strong>Aérodrome associé :</strong> ${escapeHtml(item.a)}</div>` : ''}
            <div><strong>Coordonnées :</strong> ${Number(item.x).toFixed(5)}, ${Number(item.y).toFixed(5)}</div>
            ${remark ? `<div class="sia-popup-remark">${escapeHtml(remark).replace(/#|\n/g, '<br>')}</div>` : ''}
        </div>
    `;
}

function getVisibleBaseTileLoadStateForSia() {
    if (!map || !baseTileLayer) return { total: 0, loaded: 0, tileZoomReady: true };

    try {
        const layerContainer = baseTileLayer.getContainer?.();
        const mapContainer = map.getContainer?.();
        if (!layerContainer || !mapContainer) {
            return { total: 0, loaded: countVisibleLoadedBaseTiles(), tileZoomReady: true };
        }

        const mapRect = mapContainer.getBoundingClientRect();
        const tiles = layerContainer.querySelectorAll('img.leaflet-tile');
        let total = 0;
        let loaded = 0;

        tiles.forEach(tile => {
            if (!tile || tile.style.display === 'none') return;
            const rect = tile.getBoundingClientRect();
            if (
                rect.width <= 1
                || rect.height <= 1
                || rect.right <= mapRect.left
                || rect.left >= mapRect.right
                || rect.bottom <= mapRect.top
                || rect.top >= mapRect.bottom
            ) {
                return;
            }

            total += 1;
            if (
                tile.classList.contains('leaflet-tile-loaded')
                || (tile.complete && Number(tile.naturalWidth) > 0)
            ) {
                loaded += 1;
            }
        });

        const layerZoom = Number(baseTileLayer._tileZoom);
        const mapZoom = Number(map.getZoom?.());
        const tileZoomReady = !Number.isFinite(layerZoom)
            || !Number.isFinite(mapZoom)
            || Math.abs(layerZoom - mapZoom) < 0.001;

        return { total, loaded, tileZoomReady };
    } catch (_) {
        return { total: 0, loaded: countVisibleLoadedBaseTiles(), tileZoomReady: true };
    }
}

function shouldSiaWaitForBaseMap(reason) {
    return reason === 'moveend'
        || reason === 'zoomend'
        || reason === 'startup-prefs'
        || reason === 'profile-show-map-zones'
        || reason === 'filters-all'
        || reason === 'filter-change'
        || reason === 'altitude-filter-change'
        || reason === 'filter-open'
        || reason === 'management-check';
}

async function waitForBaseMapBeforeSiaRefresh(reason, refreshGeneration) {
    if (!shouldSiaWaitForBaseMap(reason) || !map || !baseTileLayer) return;

    const isFilterActivation = reason === 'profile-show-map-zones'
        || reason === 'filters-all'
        || reason === 'filter-change'
        || reason === 'altitude-filter-change'
        || reason === 'filter-open'
        || reason === 'management-check';

    if (isFilterActivation) {
        const ready = await waitForNpfLayerActivationTileWindow(`SIA:${reason}`, {
            maxWaitMs: 12000,
            isCancelled: () => {
                try {
                    throwIfSiaRefreshObsolete(refreshGeneration);
                    return false;
                } catch (_) {
                    return true;
                }
            }
        });
        throwIfSiaRefreshObsolete(refreshGeneration);
        if (!ready) {
            const error = new Error('Priorité tuiles SIA');
            error.name = SIA_REFRESH_ABORT_ERROR_NAME;
            throw error;
        }
        return;
    }

    const directNpfOffline = !!(
        offlineTilesMode
        && typeof isNpfOfflinePackSelection === 'function'
        && isNpfOfflinePackSelection()
    );
    const maxWaitMs = directNpfOffline ? 6500 : 1000;
    const pollMs = directNpfOffline ? 90 : 70;
    const startedAt = NPF_STARTUP_DIAGNOSTIC.now();
    let stablePasses = 0;

    while (true) {
        throwIfSiaRefreshObsolete(refreshGeneration);

        const state = getVisibleBaseTileLoadStateForSia();
        const readsIdle = !directNpfOffline || (
            Number(directOfflineNpfActiveReads || 0) === 0
            && Number(directOfflineNpfReadQueue?.length || 0) === 0
        );
        const allVisibleTilesReady = state.total > 0
            && state.loaded >= state.total
            && state.tileZoomReady
            && readsIdle;

        if (allVisibleTilesReady) {
            stablePasses += 1;
            if (stablePasses >= 2) {
                await yieldSiaRefreshToMap(refreshGeneration);
                return;
            }
        } else {
            stablePasses = 0;
        }

        if (NPF_STARTUP_DIAGNOSTIC.now() - startedAt >= maxWaitMs) {
            await yieldSiaRefreshToMap(refreshGeneration);
            return;
        }

        await new Promise(resolve => setTimeout(resolve, pollMs));
    }
}

function scheduleSiaLayerRefresh(reason = 'unspecified') {
    clearTimeout(siaRefreshTimer);
    siaRefreshScheduledReason = String(reason || 'unspecified');

    /*
     * v15.83 — après un geste carte, le SIA ne repart plus sur un chronomètre
     * arbitraire. Il attend l'état visuel réel des tuiles de fond.
     */
    const delay = shouldSiaWaitForBaseMap(reason) ? 40 : 120;
    const scheduledGeneration = getSiaRefreshGeneration();

    siaRefreshTimer = setTimeout(async () => {
        siaRefreshTimer = null;
        siaRefreshScheduledReason = null;
        try {
            await waitForBaseMapBeforeSiaRefresh(reason, scheduledGeneration);
            throwIfSiaRefreshObsolete(scheduledGeneration);
            await refreshSiaLayers(reason);
        } catch (error) {
            if (error?.name === SIA_REFRESH_ABORT_ERROR_NAME) return;
            console.warn('[SIA] Rafraîchissement impossible:', reason, error);
        }
    }, delay);
}

async function refreshSiaLayers(reason = 'manual') {
    if (!map) return;
    ensureSiaMapPanes();

    if (!hasAnyEnabledSiaFilter()) {
        clearSiaRenderedLayers();
        return;
    }

    const dataset = await ensureSiaDatasetLoaded();
    if (!siaLayerGroup) {
        siaLayerGroup = L.layerGroup().addTo(map);
    }
    siaLayerGroup.clearLayers();

    const bounds = map.getBounds();
    const zoom = map.getZoom();
    let rendered = 0;

    const visibleAirspaceFeatures = [];
    for (const item of dataset.airspaces || []) {
        if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
        if (shouldHideSiaAirspaceAboveFl115(item)) continue;

        // v15.57 — les parents techniques TMA issus d'un Adg/UNION ne sont ni
        // dessinés ni proposés à la sélection. Les vrais secteurs restent.
        if (isSiaTechnicalTmaUnionParent(item)) continue;
        if (isSiaTechnicalSivParent(item, dataset)) continue;

        if (!item.g) continue;
        if (!siaBoundsIntersects(item.b, bounds)) continue;

        const geometry = siaCompactGeometryToGeoJson(item.g);
        if (!geometry) continue;

        visibleAirspaceFeatures.push({
            type: 'Feature',
            properties: { siaItem: item },
            geometry
        });
    }

    if (visibleAirspaceFeatures.length) {
        const airspaceLayer = L.geoJSON(
            { type: 'FeatureCollection', features: visibleAirspaceFeatures },
            {
                pane: 'siaAirspacePane',
                renderer: siaAirspaceRenderer,
                style: feature => getSiaAirspaceStyle(feature.properties.siaItem),
                pointToLayer: (feature, latlng) => {
                    const style = getSiaAirspaceStyle(feature.properties.siaItem);
                    return L.circleMarker(latlng, {
                        pane: 'siaAirspacePane',
                        renderer: siaAirspaceRenderer,
                        radius: 5,
                        color: style.color,
                        weight: 2,
                        fillColor: style.color,
                        fillOpacity: 0.85
                    });
                },
                onEachFeature: (feature, layer) => {
                    layer.bindPopup(
                        buildSiaAirspacePopup(feature.properties.siaItem),
                        { maxWidth: 340 }
                    );
                }
            }
        );
        airspaceLayer.addTo(siaLayerGroup);
        rendered += visibleAirspaceFeatures.length;
    }

    const pointBounds = bounds.pad(0.04);

    for (const item of dataset.terrain || []) {
        if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
        const latlng = L.latLng(Number(item.x), Number(item.y));
        if (!pointBounds.contains(latlng)) continue;

        const marker = L.circleMarker(latlng, {
            ...getSiaTerrainMarkerStyle(item),
            pane: 'siaPointPane',
            renderer: siaPointRenderer
        });
        marker.bindPopup(buildSiaTerrainPopup(item), { maxWidth: 320 });
        if (zoom >= 8 && item.c) {
            marker.bindTooltip(escapeHtml(item.c), {
                permanent: true,
                direction: 'right',
                offset: [5, 0],
                className: 'sia-point-label sia-terrain-label'
            });
        }
        marker.addTo(siaLayerGroup);
        rendered += 1;
    }

    for (const item of dataset.points || []) {
        if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
        if (item.k === 'dpn:VRP' && !siaMapVrpVisible) continue;
        const latlng = L.latLng(Number(item.x), Number(item.y));
        if (!pointBounds.contains(latlng)) continue;

        const marker = L.circleMarker(latlng, {
            ...getSiaPointMarkerStyle(item),
            pane: 'siaPointPane',
            renderer: siaPointRenderer
        });
        marker.bindPopup(buildSiaPointPopup(item), { maxWidth: 320 });
        if (item.k === 'dpn:VRP') {
            marker.on('popupopen', () => marker.setPopupContent(buildSiaPointPopup(item)));
        }

        const label = item.k === 'dpn:VRP'
            ? String(item.d || '').trim()
            : String(item.d || item.c || '').trim();
        if (zoom >= 8 && label && item.k !== 'dpn:ADHP') {
            marker.bindTooltip(escapeHtml(label), {
                permanent: true,
                direction: 'right',
                offset: [5, 0],
                className: `sia-point-label ${item.k === 'dpn:VRP' ? 'sia-vrp-label' : ''}`
            });
        }
        marker.addTo(siaLayerGroup);
        rendered += 1;
    }

    const footer = document.getElementById('sia-filter-footer-status');
    if (footer) {
        footer.textContent = `${rendered} objet${rendered > 1 ? 's' : ''} SIA affiché${rendered > 1 ? 's' : ''} dans la zone visible.`;
    }
}

async function refreshSiaManagementStatus() {
    const status = document.getElementById('sia-installed-status');
    const deleteButton = document.getElementById('sia-delete-data-button');
    if (!status) return;

    try {
        const meta = await siaDbGet(SIA_META_KEY);
        if (siaMetaMatchesEmbedded(meta)) {
            status.textContent = `✓ À jour — AIRAC ${meta.airac} v${meta.datasetVersion}`;
            status.classList.add('is-ready');
            if (deleteButton) deleteButton.style.display = '';
        } else {
            status.textContent = `Non initialisé — AIRAC intégré ${SIA_EMBEDDED_META.airac} v${SIA_EMBEDDED_META.datasetVersion}`;
            status.classList.remove('is-ready');
            if (deleteButton) deleteButton.style.display = 'none';
        }
    } catch (error) {
        status.textContent = 'Stockage SIA indisponible';
        status.classList.remove('is-ready');
        if (deleteButton) deleteButton.style.display = 'none';
    }
}

function bindSiaManagementButtons() {
    const checkButton = document.getElementById('sia-check-update-button');
    const deleteButton = document.getElementById('sia-delete-data-button');

    if (checkButton && checkButton.dataset.bound !== '1') {
        checkButton.dataset.bound = '1';
        checkButton.addEventListener('click', async () => {
            const oldText = checkButton.textContent;
            checkButton.disabled = true;
            checkButton.textContent = 'Vérification…';
            try {
                const meta = await siaDbGet(SIA_META_KEY).catch(() => null);
                if (siaMetaMatchesEmbedded(meta)) {
                    await ensureSiaDatasetLoaded();
                    alert(`Données SIA à jour : AIRAC ${SIA_EMBEDDED_META.airac} v${SIA_EMBEDDED_META.datasetVersion}.`);
                } else {
                    await ensureSiaDatasetLoaded({ forceEmbedded: true });
                    alert(`Données SIA initialisées : AIRAC ${SIA_EMBEDDED_META.airac} v${SIA_EMBEDDED_META.datasetVersion}.`);
                }
                scheduleSiaLayerRefresh('management-check');
            } catch (error) {
                console.error('[SIA] Initialisation impossible:', error);
                alert(`Initialisation SIA impossible : ${error.message || error}`);
            } finally {
                checkButton.disabled = false;
                checkButton.textContent = oldText;
                refreshSiaManagementStatus();
            }
        });
    }

    if (deleteButton && deleteButton.dataset.bound !== '1') {
        deleteButton.dataset.bound = '1';
        deleteButton.addEventListener('click', async () => {
            if (!confirm('Supprimer les données aéronautiques SIA stockées sur cet appareil ? Les autres données NPF ne seront pas touchées.')) {
                return;
            }
            try {
                await siaDbDelete(SIA_DATASET_KEY);
                await siaDbDelete(SIA_META_KEY);
                siaDataset = null;
                siaDatasetLoadPromise = null;
                clearSiaRenderedLayers();
                await refreshSiaManagementStatus();
            } catch (error) {
                console.error('[SIA] Suppression impossible:', error);
                alert(`Suppression SIA impossible : ${error.message || error}`);
            }
        });
    }
}

function siaProfileVerticalToFeet(raw) {
    if (!Array.isArray(raw)) return null;

    const ref = String(raw?.[0] || '').toUpperCase();
    const value = Number(raw?.[1]);
    const unit = String(raw?.[2] || '').toUpperCase();

    if (!Number.isFinite(value)) return null;
    if (ref === 'STD' && unit === 'FL') return value * 100;
    if ((ref === 'ALT' || ref === 'HEI') && unit === 'FT') return value;
    return null;
}

function getSiaProfileCurrentPosition() {
    if (!lastPosition) return null;

    const lat = Number(lastPosition.latitude ?? lastPosition.lat);
    const lng = Number(lastPosition.longitude ?? lastPosition.lng);
    let heading = Number(lastPosition.heading);
    const altitudeFt = Number(lastPosition.altitudeFt ?? lastPosition.altitudeFeet);

    if (!Number.isFinite(heading) && isSimulationMode) {
        heading = Number(simulationRouteDeg);
    }

    if (![lat, lng, heading].every(Number.isFinite)) return null;

    const speedKtDirect = Number(lastPosition.speedKt);
    const speedMps = Number(lastPosition.speedMps);
    const speedKt = Number.isFinite(speedKtDirect)
        ? speedKtDirect
        : (Number.isFinite(speedMps) ? speedMps * 1.9438444924406 : null);

    return {
        lat,
        lng,
        heading: ((heading % 360) + 360) % 360,
        altitudeFt: Number.isFinite(altitudeFt) ? altitudeFt : null,
        speedKt: Number.isFinite(speedKt) ? Math.max(0, speedKt) : null
    };
}

function scheduleSiaProfileRefresh(reason = 'unspecified') {
    if (!siaProfileOpen) return;
    clearTimeout(siaProfileRefreshTimer);
    siaProfileRefreshTimer = setTimeout(() => {
        renderSiaAirspaceProfile(reason).catch(error => {
            console.warn('[SIA profil] Rendu impossible:', error);
        });
    }, 120);
}


/*
 * v15.69 — mouvement du profil :
 * les volumes déjà présents sont déplacés avec le même delta que l'avion
 * entre deux rafraîchissements lorsque la route reste stable. On évite ainsi
 * que l'échantillonnage 0,25 NM fasse varier séparément les deux bords d'une
 * zone et produise un effet « accordéon ».
 */
let siaProfilePreviousMotionPosition = null;
let siaProfilePreviousIntervals = new Map();

function normalizeSiaProfileHeadingDelta(a, b) {
    let delta = ((Number(a) || 0) - (Number(b) || 0)) % 360;
    if (delta > 180) delta -= 360;
    if (delta < -180) delta += 360;
    return Math.abs(delta);
}

function getSiaProfileForwardMovementNm(position) {
    const previous = siaProfilePreviousMotionPosition;
    const current = {
        lat: Number(position?.lat),
        lng: Number(position?.lng),
        heading: Number(position?.heading)
    };
    siaProfilePreviousMotionPosition = current;

    if (!previous || ![current.lat, current.lng, current.heading, previous.lat, previous.lng, previous.heading].every(Number.isFinite)) {
        return 0;
    }

    const distanceNm = calculateDistanceInNm(previous.lat, previous.lng, current.lat, current.lng);
    if (!Number.isFinite(distanceNm) || distanceNm <= 0 || distanceNm > 2) return 0;
    if (normalizeSiaProfileHeadingDelta(previous.heading, current.heading) > 5) return 0;

    const movementBearing = calculateBearing(previous.lat, previous.lng, current.lat, current.lng);
    if (!Number.isFinite(movementBearing)) return 0;
    const courseDelta = normalizeSiaProfileHeadingDelta(movementBearing, current.heading);
    if (courseDelta > 35) return 0;

    const alongTrackNm = distanceNm * Math.cos(courseDelta * Math.PI / 180);
    return Number.isFinite(alongTrackNm) && alongTrackNm > 0 ? alongTrackNm : 0;
}

function getSiaProfileVolumeMotionKey(item, intervalIndex) {
    return `${getSiaCtrSelectionKey(item)}|${Number(intervalIndex) || 0}`;
}

function stabilizeSiaProfileVolumeIntervals(volumes, forwardMovementNm) {
    const next = new Map();
    const toleranceNm = 0.75;

    volumes.forEach(volume => {
        const key = String(volume.profileKey || '');
        const previous = key ? siaProfilePreviousIntervals.get(key) : null;

        if (previous && Number.isFinite(forwardMovementNm) && forwardMovementNm > 0) {
            const predictedStart = Math.max(0, Number(previous.startNm) - forwardMovementNm);
            const predictedEnd = Math.max(0, Number(previous.endNm) - forwardMovementNm);

            if (
                predictedEnd > predictedStart
                && Math.abs(Number(volume.startNm) - predictedStart) <= toleranceNm
                && Math.abs(Number(volume.endNm) - predictedEnd) <= toleranceNm
            ) {
                volume.startNm = predictedStart;
                volume.endNm = Math.min(siaProfileDistanceNm, predictedEnd);
            }
        }

        if (key) {
            next.set(key, {
                startNm: Number(volume.startNm),
                endNm: Number(volume.endNm)
            });
        }
    });

    siaProfilePreviousIntervals = next;
    return volumes;
}

function buildSiaProfileSamples(position, distanceNm) {
    const stepNm = distanceNm <= 25 ? 0.25 : distanceNm <= 50 ? 0.4 : 0.5;
    const samples = [];

    for (let d = 0; d <= distanceNm + 1e-6; d += stepNm) {
        const dest = calculateDestinationLatLng(
            position.lat,
            position.lng,
            position.heading,
            d * 1852
        );
        samples.push({
            distanceNm: Math.min(distanceNm, d),
            latlng: L.latLng(Number(dest[0]), Number(dest[1]))
        });
    }

    if (!samples.length || samples[samples.length - 1].distanceNm < distanceNm - 0.01) {
        const dest = calculateDestinationLatLng(
            position.lat,
            position.lng,
            position.heading,
            distanceNm * 1852
        );
        samples.push({
            distanceNm,
            latlng: L.latLng(Number(dest[0]), Number(dest[1]))
        });
    }

    return { samples, stepNm };
}

function getSiaProfileRouteBounds(samples) {
    let minLat = Infinity, maxLat = -Infinity, minLng = Infinity, maxLng = -Infinity;

    samples.forEach(sample => {
        minLat = Math.min(minLat, sample.latlng.lat);
        maxLat = Math.max(maxLat, sample.latlng.lat);
        minLng = Math.min(minLng, sample.latlng.lng);
        maxLng = Math.max(maxLng, sample.latlng.lng);
    });

    return { minLat, maxLat, minLng, maxLng };
}

function siaProfileItemCouldMeetRoute(item, routeBounds) {
    if (!Array.isArray(item?.b) || item.b.length < 4) return true;

    const minLon = Number(item.b[0]);
    const minLat = Number(item.b[1]);
    const maxLon = Number(item.b[2]);
    const maxLat = Number(item.b[3]);
    if (![minLon, minLat, maxLon, maxLat].every(Number.isFinite)) return true;

    const pad = 0.08;
    return !(
        maxLat < routeBounds.minLat - pad
        || minLat > routeBounds.maxLat + pad
        || maxLon < routeBounds.minLng - pad
        || minLon > routeBounds.maxLng + pad
    );
}

function buildSiaProfileIntervals(item, geometry, samples, stepNm) {
    const intervals = [];
    let runStart = null;

    for (let i = 0; i < samples.length; i += 1) {
        const inside = siaGeometryContainsLatLng(geometry, samples[i].latlng);

        if (inside && runStart === null) {
            runStart = i;
        }

        const isLast = i === samples.length - 1;
        if (runStart !== null && (!inside || isLast)) {
            const lastInsideIndex = inside && isLast ? i : i - 1;
            const startNm = Math.max(0, samples[runStart].distanceNm - stepNm / 2);
            const endNm = Math.min(
                siaProfileDistanceNm,
                samples[lastInsideIndex].distanceNm + stepNm / 2
            );

            if (endNm > startNm + 0.05) {
                intervals.push({ startNm, endNm });
            }
            runStart = null;
        }
    }

    return intervals;
}

function getSiaProfileFilterLabel(key) {
    const labels = {
        'ase:CTR': 'CTR',
        'ase:TMA': 'TMA',
        'ase:CTA': 'CTA',
        'ase:FIR': 'FIR',
        'ase:UIR': 'UIR',
        'ase:UIR-P': 'UIR-P',
        'ase:UTA': 'UTA',
        'ase:OCA': 'OCA',
        'ase:SECTOR': 'SECTOR',
        'ase:SECTOR-C': 'SECTOR-C',
        'ase:RAS': 'RAS',
        'ase:TRA': 'TRA',
        'ase:P': 'P',
        'ase:R': 'R',
        'ase:D': 'D'
    };
    if (labels[key]) return labels[key];
    if (String(key || '').startsWith('ase:D-OTHER:')) {
        return String(key).slice('ase:D-OTHER:'.length);
    }
    return String(key || '').replace(/^ase:/, '') || 'Zone';
}

function getSiaProfileAvailableFilterKeys(dataset) {
    const operationalFamilies = buildSiaTmaOperationalFamilySet(dataset);
    const keys = new Set();

    (dataset?.airspaces || []).forEach(item => {
        const key = getSiaEffectiveFilterKey(item);
        if (!key || !isSiaFilterEnabled(key)) return;
        if (isSiaFlightInformationSector(item)) return; // SIV reste hors profil.
        if (isSiaTechnicalTmaUnionParent(item)) return;
        if (isSiaGenericTmaWithoutAltitude(item, operationalFamilies)) return;
        if (!item.g) return;
        const geometryType = String(item.g?.[0] || '');
        if (geometryType !== 'G' && geometryType !== 'M') return;
        keys.add(key);
    });

    const priority = [
        'ase:CTR', 'ase:R', 'ase:P', 'ase:D', 'ase:TRA',
        'ase:TMA', 'ase:CTA', 'ase:SECTOR', 'ase:SECTOR-C',
        'ase:RAS', 'ase:OCA', 'ase:UTA', 'ase:FIR', 'ase:UIR', 'ase:UIR-P'
    ];
    return [...keys].sort((a, b) => {
        const pa = priority.indexOf(a);
        const pb = priority.indexOf(b);
        if (pa !== -1 || pb !== -1) {
            if (pa === -1) return 1;
            if (pb === -1) return -1;
            if (pa !== pb) return pa - pb;
        }
        return a.localeCompare(b);
    });
}

function renderSiaProfileZoneFilterControls(dataset = siaDataset) {
    const container = document.getElementById('sia-profile-zone-filters');
    if (!container) return;

    const keys = getSiaProfileAvailableFilterKeys(dataset);
    if (!keys.length) {
        container.innerHTML = '<span class="sia-profile-zone-empty">Aucune zone activée dans le filtre SIA</span>';
        return;
    }

    container.innerHTML = keys.map(key => `
        <label class="sia-profile-zone-filter-item">
            <input type="checkbox"
                   data-sia-profile-filter-key="${escapeHtml(key)}"
                   ${isSiaProfileFilterEnabled(key) ? 'checked' : ''}>
            <span>${escapeHtml(getSiaProfileFilterLabel(key))}</span>
        </label>
    `).join('');
}

function getSiaProfileCandidateItems(dataset) {
    const operationalFamilies = buildSiaTmaOperationalFamilySet(dataset);
    return (dataset?.airspaces || []).filter(item => {
        const effectiveKey = getSiaEffectiveFilterKey(item);
        if (!isSiaFilterEnabled(effectiveKey)) return false;
        if (!isSiaProfileFilterEnabled(effectiveKey)) return false;
        // v15.67 — les SIV restent sur la carte mais ne font pas partie de la coupe verticale.
        if (isSiaFlightInformationSector(item)) return false;
        if (shouldHideSiaAirspaceAboveFl115(item)) return false;
        if (isSiaTechnicalTmaUnionParent(item)) return false;
        if (isSiaGenericTmaWithoutAltitude(item, operationalFamilies)) return false;
        if (!item.g) return false;

        const geometryType = String(item.g?.[0] || '');
        // Le profil représente des volumes traversés, donc uniquement les
        // zones surfaciques. Les D-OTHER ponctuels restent sur la carte.
        return geometryType === 'G' || geometryType === 'M';
    });
}

function getSiaProfileLabelParts(item) {
    const displayType = getSiaAirspaceDisplayType(item);
    const type = String(item?.t || '').trim().toUpperCase();
    const name = String(item?.n || '').trim();
    const code = String(item?.c || '').trim();
    const primaryName = name || code;
    const base = [displayType, primaryName].filter(Boolean).join(' ');

    if (type === 'R') {
        const restrictedInfo = getSiaRestrictedRemarkInfo(item);
        return {
            name: [
                base,
                String(restrictedInfo?.operationalName || '').trim()
            ].filter(Boolean).join(' / '),
            frequency: String(restrictedInfo?.frequency || '').trim()
        };
    }

    if (type === 'P') {
        return {
            name: [base, getSiaProhibitedOfficialName(item)].filter(Boolean).join(' / '),
            frequency: ''
        };
    }

    const firstFrequency = getSiaFirstAssignedFrequency(item);
    if (!firstFrequency) return { name: base, frequency: '' };

    const frequencyPrefix = firstFrequency.inferredFromRemark
        ? ''
        : String(firstFrequency.serviceType || '').trim();

    return {
        name: base,
        frequency: [frequencyPrefix, firstFrequency.value]
            .filter(Boolean)
            .join(' ') + (firstFrequency.supplementary ? ' (s)' : '')
    };
}

function getSiaProfileDisplayCeilingFeet(position) {
    const ownAlt = Number(position?.altitudeFt);
    let ceiling = Number.isFinite(ownAlt)
        ? Math.max(5000, ownAlt + 5000)
        : null;

    if (isSiaHideAboveFl115Enabled()) {
        ceiling = Number.isFinite(ceiling)
            ? Math.min(ceiling, SIA_HIDE_ABOVE_FL115_FEET)
            : SIA_HIDE_ABOVE_FL115_FEET;
    }

    return Number.isFinite(ceiling) ? ceiling : null;
}

function estimateSiaProfileLabelWidth(text, fontSize = 11) {
    const value = String(text || '');
    if (!value) return 0;
    // Estimation volontairement conservatrice pour éviter tout chevauchement.
    return value.length * fontSize * 0.59 + 8;
}

function siaProfileLabelRectsOverlap(a, b, padding = 4) {
    return !(
        a.x + a.width + padding <= b.x
        || b.x + b.width + padding <= a.x
        || a.y + a.height + padding <= b.y
        || b.y + b.height + padding <= a.y
    );
}

function findSiaProfileLabelPlacement({ x1, x2, yTop, yBottom, name, frequency }, occupied) {
    const rectWidth = Math.max(0, x2 - x1);
    const rectHeight = Math.max(0, yBottom - yTop);
    const labelWidth = Math.max(
        estimateSiaProfileLabelWidth(name, 11),
        estimateSiaProfileLabelWidth(frequency, 10)
    );
    const labelHeight = frequency ? 28 : 16;
    const inset = 5;

    if (!name || labelWidth > rectWidth - inset * 2 || labelHeight > rectHeight - 4) {
        return null;
    }

    const minCenterX = x1 + inset + labelWidth / 2;
    const maxCenterX = x2 - inset - labelWidth / 2;
    const minCenterY = yTop + 2 + labelHeight / 2;
    const maxCenterY = yBottom - 2 - labelHeight / 2;
    if (minCenterX > maxCenterX || minCenterY > maxCenterY) return null;

    const centersX = [
        (x1 + x2) / 2,
        minCenterX,
        maxCenterX,
        x1 + rectWidth * 0.35,
        x1 + rectWidth * 0.65
    ].map(x => Math.max(minCenterX, Math.min(maxCenterX, x)));

    const centersY = [
        (yTop + yBottom) / 2,
        minCenterY,
        maxCenterY
    ].map(y => Math.max(minCenterY, Math.min(maxCenterY, y)));

    const seen = new Set();
    for (const centerY of centersY) {
        for (const centerX of centersX) {
            const key = `${Math.round(centerX)}:${Math.round(centerY)}`;
            if (seen.has(key)) continue;
            seen.add(key);

            const candidate = {
                x: centerX - labelWidth / 2,
                y: centerY - labelHeight / 2,
                width: labelWidth,
                height: labelHeight,
                centerX,
                centerY
            };

            if (!occupied.some(other => siaProfileLabelRectsOverlap(candidate, other))) {
                occupied.push(candidate);
                return candidate;
            }
        }
    }
    return null;
}

function buildSiaProfileSvg(volumes, position, viewport = {}) {
    /*
     * v15.67 — coordonnées SVG calées sur les dimensions CSS réelles du graphe.
     * On n’utilise plus le redimensionnement SVG anisotrope : les textes
     * gardent donc leurs proportions normales sur iPad, même en pleine largeur.
     */
    const width = Math.max(640, Math.round(Number(viewport.width) || 1000));
    const height = Math.max(220, Math.round(Number(viewport.height) || 330));
    const margin = { left: 64, right: 16, top: 18, bottom: 38 };
    const plotW = Math.max(1, width - margin.left - margin.right);
    const plotH = Math.max(1, height - margin.top - margin.bottom);
    const motionShiftNm = Math.max(0, Number(viewport.motionShiftNm) || 0);
    const motionShiftPx = (motionShiftNm / Math.max(1, siaProfileDistanceNm)) * plotW;

    const ownAlt = Number(position.altitudeFt);
    const profileCeilingFt = getSiaProfileDisplayCeilingFeet(position);
    const upperValues = volumes
        .map(v => Number(v.upperFt))
        .filter(Number.isFinite);

    let maxAlt;
    if (Number.isFinite(profileCeilingFt)) {
        maxAlt = Math.max(1000, profileCeilingFt);
    } else {
        maxAlt = Math.max(
            10000,
            upperValues.length ? Math.max(...upperValues) : 0
        );
        maxAlt = Math.min(40000, Math.ceil(maxAlt / 5000) * 5000);
        if (maxAlt < 10000) maxAlt = 10000;
    }

    const xForDistance = nm =>
        margin.left + (Math.max(0, Math.min(siaProfileDistanceNm, nm)) / siaProfileDistanceNm) * plotW;

    const yForAltitude = feet =>
        margin.top + plotH - (Math.max(0, Math.min(maxAlt, feet)) / maxAlt) * plotH;

    const grid = [];
    const gridAltitudes = [];
    for (let alt = 0; alt <= maxAlt; alt += 5000) gridAltitudes.push(alt);
    if (!gridAltitudes.includes(maxAlt)) gridAltitudes.push(maxAlt);

    [...new Set(gridAltitudes.map(v => Math.round(v)))].sort((a, b) => a - b).forEach(alt => {
        const y = yForAltitude(alt);
        const isTop = Math.abs(alt - maxAlt) < 1;
        let label = alt === 0 ? 'SFC' : `${Math.round(alt / 1000)}k`;
        if (isTop && isSiaHideAboveFl115Enabled() && Math.abs(maxAlt - SIA_HIDE_ABOVE_FL115_FEET) < 1) {
            label = 'FL115';
        } else if (isTop && alt % 1000 !== 0) {
            label = `${Math.round(alt)} ft`;
        }
        grid.push(`<line x1="${margin.left}" y1="${y.toFixed(1)}" x2="${(width-margin.right).toFixed(1)}" y2="${y.toFixed(1)}" class="sia-profile-grid-line${isTop ? ' sia-profile-ceiling-line' : ''}"/>`);
        grid.push(`<text x="${margin.left-8}" y="${(y+4).toFixed(1)}" text-anchor="end" class="sia-profile-axis-label${isTop ? ' sia-profile-ceiling-label' : ''}">${escapeHtml(label)}</text>`);
    });

    const distanceStep = siaProfileDistanceNm <= 25 ? 5 : siaProfileDistanceNm <= 50 ? 10 : 20;
    for (let nm = 0; nm <= siaProfileDistanceNm; nm += distanceStep) {
        const x = xForDistance(nm);
        grid.push(`<line x1="${x.toFixed(1)}" y1="${margin.top}" x2="${x.toFixed(1)}" y2="${(height-margin.bottom).toFixed(1)}" class="sia-profile-grid-line sia-profile-grid-vertical"/>`);
        grid.push(`<text x="${x.toFixed(1)}" y="${height-12}" text-anchor="middle" class="sia-profile-axis-label">${nm} NM</text>`);
    }

    const shapes = [];
    const occupiedLabels = [];

    volumes.forEach((volume, index) => {
        const x1 = xForDistance(volume.startNm);
        const x2 = xForDistance(volume.endNm);
        const lower = Number.isFinite(volume.lowerFt) ? volume.lowerFt : 0;
        const upper = Number.isFinite(volume.upperFt) ? volume.upperFt : maxAlt;
        const visibleLower = Math.max(0, Math.min(maxAlt, lower));
        const visibleUpper = Math.max(0, Math.min(maxAlt, upper));
        if (visibleUpper <= visibleLower + 1) return;

        const yTop = yForAltitude(visibleUpper);
        const yBottom = yForAltitude(visibleLower);
        const rectHeight = Math.max(2, yBottom - yTop);
        const rectWidth = Math.max(2, x2 - x1);
        const style = getSiaAirspaceStyle(volume.item);
        const color = String(style?.color || '#3559e0');
        const labelParts = getSiaProfileLabelParts(volume.item);
        const placement = findSiaProfileLabelPlacement({
            x1,
            x2,
            yTop,
            yBottom,
            name: labelParts.name,
            frequency: labelParts.frequency
        }, occupiedLabels);

        let labelSvg = '';
        if (placement) {
            const nameY = labelParts.frequency
                ? placement.centerY - 3
                : placement.centerY + 4;
            const frequencyY = placement.centerY + 10;
            labelSvg = `
                <text x="${placement.centerX.toFixed(1)}" y="${nameY.toFixed(1)}"
                      text-anchor="middle" class="sia-profile-volume-label sia-profile-volume-label-name">${escapeHtml(labelParts.name)}</text>
                ${labelParts.frequency ? `<text x="${placement.centerX.toFixed(1)}" y="${frequencyY.toFixed(1)}"
                      text-anchor="middle" class="sia-profile-volume-label sia-profile-volume-label-frequency">${escapeHtml(labelParts.frequency)}</text>` : ''}`;
        }

        const motionAnimation = motionShiftPx >= 0.5
            ? `<animateTransform attributeName="transform" type="translate" from="${motionShiftPx.toFixed(1)} 0" to="0 0" dur="0.18s" fill="freeze"/>`
            : '';

        shapes.push(`
            <g class="sia-profile-volume-group" data-profile-index="${index}" data-profile-key="${escapeHtml(String(volume.profileKey || ''))}">
                ${motionAnimation}
                <rect x="${x1.toFixed(1)}" y="${yTop.toFixed(1)}"
                      width="${rectWidth.toFixed(1)}" height="${rectHeight.toFixed(1)}"
                      fill="${escapeHtml(color)}" fill-opacity="0.20"
                      stroke="${escapeHtml(color)}" stroke-width="2"
                      class="sia-profile-volume"/>
                ${labelSvg}
            </g>
        `);
    });

    const ownAltitudeLine = [];
    const timeVectorMarks = [];
    if (Number.isFinite(ownAlt) && ownAlt >= 0 && ownAlt <= maxAlt) {
        const y = yForAltitude(ownAlt);
        ownAltitudeLine.push(`<line x1="${margin.left}" y1="${y.toFixed(1)}" x2="${width-margin.right}" y2="${y.toFixed(1)}" class="sia-profile-own-alt-line"/>`);
        ownAltitudeLine.push(`<text x="${width-margin.right-4}" y="${(y-5).toFixed(1)}" text-anchor="end" class="sia-profile-own-alt-label">${Math.round(ownAlt)} ft</text>`);

        /*
         * v15.69 — les repères 2'/5'/10' du vecteur temps sont reportés sur
         * cette ligne d'altitude. Leur abscisse est calculée avec la vitesse sol.
         */
        const speedKt = Number(position?.speedKt);
        if (Number.isFinite(speedKt) && speedKt >= 1) {
            [2, 5, 10].forEach(minutes => {
                const distanceNm = speedKt * minutes / 60;
                if (distanceNm < 0 || distanceNm > siaProfileDistanceNm + 0.001) return;
                const x = xForDistance(distanceNm);
                timeVectorMarks.push(`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="6.5" class="sia-profile-time-dot"/>`);
                timeVectorMarks.push(`<text x="${x.toFixed(1)}" y="${(y-10).toFixed(1)}" text-anchor="middle" class="sia-profile-time-dot-label">${minutes}'</text>`);
            });
        }
    }

    return `
        <svg class="sia-profile-svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Coupe verticale des espaces aéronautiques devant l'avion">
            <rect x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" class="sia-profile-plot-bg"/>
            ${grid.join('')}
            ${shapes.join('')}
            ${ownAltitudeLine.join('')}
            ${timeVectorMarks.join('')}
            <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height-margin.bottom}" class="sia-profile-axis"/>
            <line x1="${margin.left}" y1="${height-margin.bottom}" x2="${width-margin.right}" y2="${height-margin.bottom}" class="sia-profile-axis"/>
            <text x="${margin.left+5}" y="${margin.top+14}" class="sia-profile-axis-title">Altitude ft</text>
        </svg>
    `;
}

async function renderSiaAirspaceProfile(reason = 'manual') {
    if (!siaProfileOpen) return;

    const panel = document.getElementById('sia-profile-panel');
    const chart = document.getElementById('sia-profile-chart');
    const subtitle = document.getElementById('sia-profile-subtitle');
    if (!panel || !chart) return;

    const position = getSiaProfileCurrentPosition();
    if (!position) {
        chart.innerHTML = '<div class="sia-profile-empty">Position / route GPS indisponible.</div>';
        if (subtitle) subtitle.textContent = 'Route GPS nécessaire';
        return;
    }

    const dataset = await ensureSiaDatasetLoaded();
    const { samples, stepNm } = buildSiaProfileSamples(position, siaProfileDistanceNm);
    const routeBounds = getSiaProfileRouteBounds(samples);
    const items = getSiaProfileCandidateItems(dataset);

    const volumes = [];
    const profileCeilingFt = getSiaProfileDisplayCeilingFeet(position);
    const forwardMovementNm = getSiaProfileForwardMovementNm(position);

    items.forEach(item => {
        if (!siaProfileItemCouldMeetRoute(item, routeBounds)) return;

        const geometry = getSiaCachedGeometry(item);
        if (!geometry) return;

        const intervals = buildSiaProfileIntervals(item, geometry, samples, stepNm);
        if (!intervals.length) return;

        const lowerFt = siaProfileVerticalToFeet(item.lo);
        const upperFt = siaProfileVerticalToFeet(item.up);

        /*
         * v15.67 — le profil est une vue opérationnelle autour de l'avion :
         * on ne conserve pas une zone dont le plancher commence au-dessus du
         * plafond affiché (altitude avion + 5000 ft, limité au FL115 si demandé).
         * Les plafonds plus hauts sont tronqués graphiquement, jamais dans la
         * donnée SIA ni dans la fiche de la zone.
         */
        if (
            Number.isFinite(profileCeilingFt)
            && Number.isFinite(lowerFt)
            && lowerFt >= profileCeilingFt
        ) return;

        const profileUpperFt = Number.isFinite(profileCeilingFt)
            ? (Number.isFinite(upperFt) ? Math.min(upperFt, profileCeilingFt) : profileCeilingFt)
            : upperFt;

        intervals.forEach((interval, intervalIndex) => {
            volumes.push({
                item,
                geometry,
                lowerFt,
                upperFt: profileUpperFt,
                startNm: interval.startNm,
                endNm: interval.endNm,
                profileKey: getSiaProfileVolumeMotionKey(item, intervalIndex)
            });
        });
    });

    stabilizeSiaProfileVolumeIntervals(volumes, forwardMovementNm);

    // Ordre stable : zones les plus proches puis les plus basses.
    volumes.sort((a, b) =>
        a.startNm - b.startNm
        || (Number(a.lowerFt) || 0) - (Number(b.lowerFt) || 0)
    );

    // Garde-fou graphique sur iPad.
    siaProfileSegments = volumes.slice(0, 80);

    if (subtitle) {
        const profileCeilingFt = getSiaProfileDisplayCeilingFeet(position);
        const ceilingText = Number.isFinite(profileCeilingFt)
            ? ` · plafond ${Math.round(profileCeilingFt)} ft`
            : '';
        subtitle.textContent = `Route ${String(Math.round(position.heading)).padStart(3, '0')}° · 0–${siaProfileDistanceNm} NM${ceilingText} · ${siaProfileSegments.length} volume${siaProfileSegments.length > 1 ? 's' : ''}`;
    }

    if (!siaProfileSegments.length) {
        chart.innerHTML = '<div class="sia-profile-empty">Aucun espace SIA actif rencontré dans l’axe.</div>';
        return;
    }

    chart.innerHTML = buildSiaProfileSvg(siaProfileSegments, position, {
        width: chart.clientWidth || chart.getBoundingClientRect?.().width || 1000,
        height: chart.clientHeight || chart.getBoundingClientRect?.().height || 330,
        motionShiftNm: forwardMovementNm
    });

    chart.querySelectorAll('[data-profile-index]').forEach(group => {
        group.addEventListener('click', event => {
            const index = Number(event.currentTarget?.dataset?.profileIndex);
            const segment = siaProfileSegments[index];
            if (!segment) return;

            const middleNm = (segment.startNm + segment.endNm) / 2;
            const point = calculateDestinationLatLng(
                position.lat,
                position.lng,
                position.heading,
                middleNm * 1852
            );
            const latlng = L.latLng(Number(point[0]), Number(point[1]));

            selectSiaCtrTouchLayer(
                null,
                segment.item,
                latlng,
                segment.geometry
            );
        });
    });
}

function syncSiaProfilePanelToViewport() {
    const panel = document.getElementById('sia-profile-panel');
    if (!panel || !siaProfileOpen || panel.hidden) return;

    const visualViewport = window.visualViewport || null;
    const viewportTop = visualViewport
        ? Math.max(0, Number(visualViewport.offsetTop) || 0)
        : 0;
    const fallbackViewportHeight = Math.max(
        1,
        window.innerHeight || 0,
        document.documentElement?.clientHeight || 0
    );
    const viewportHeight = Math.max(
        1,
        visualViewport
            ? Number(visualViewport.height) || fallbackViewportHeight
            : fallbackViewportHeight
    );

    const topGap = 8;
    const maxAvailableHeight = Math.max(160, viewportHeight - topGap);
    const desiredHeight = Math.min(
        430,
        maxAvailableHeight,
        Math.max(250, viewportHeight * 0.43)
    );
    const top = Math.max(
        viewportTop + topGap,
        viewportTop + viewportHeight - desiredHeight
    );

    panel.style.top = `${Math.round(top)}px`;
    panel.style.bottom = 'auto';
    panel.style.height = `${Math.round(desiredHeight)}px`;
    panel.style.maxHeight = `${Math.round(maxAvailableHeight)}px`;
}

function scheduleSiaProfileViewportSync() {
    if (!siaProfileOpen) return;
    requestAnimationFrame(() => syncSiaProfilePanelToViewport());
    setTimeout(() => syncSiaProfilePanelToViewport(), 120);
}

function setSiaProfileOpen(open) {
    siaProfileOpen = !!open;

    const panel = document.getElementById('sia-profile-panel');
    const button = document.getElementById('sia-profile-button');
    const swipeHandle = document.getElementById('sia-profile-swipe-handle');

    if (panel) {
        panel.hidden = !siaProfileOpen;
        panel.setAttribute('aria-hidden', siaProfileOpen ? 'false' : 'true');
    }
    if (button) {
        button.classList.toggle('active', siaProfileOpen);
        button.setAttribute('aria-pressed', siaProfileOpen ? 'true' : 'false');
    }
    if (swipeHandle) {
        swipeHandle.hidden = siaProfileOpen;
        swipeHandle.setAttribute('aria-hidden', siaProfileOpen ? 'true' : 'false');
    }

    if (siaProfileOpen) {
        syncSiaProfilePanelToViewport();
        updateSiaProfileMapZonesToggleButton();
        if (siaDataset) {
            renderSiaProfileZoneFilterControls(siaDataset);
        } else {
            ensureSiaDatasetLoaded()
                .then(dataset => renderSiaProfileZoneFilterControls(dataset))
                .catch(() => {});
        }
        scheduleSiaProfileRefresh('open');
    } else {
        clearTimeout(siaProfileRefreshTimer);
        siaProfileRefreshTimer = null;
        siaProfilePreviousMotionPosition = null;
        siaProfilePreviousIntervals = new Map();
    }
}

function initializeSiaAirspaceProfileUi() {
    const button = document.getElementById('sia-profile-button');
    const panel = document.getElementById('sia-profile-panel');
    const closeButton = document.getElementById('sia-profile-close');
    const swipeHandle = document.getElementById('sia-profile-swipe-handle');
    const zoneFilters = document.getElementById('sia-profile-zone-filters');
    const mapZonesToggle = document.getElementById('sia-profile-map-zones-toggle');

    /*
     * v15.61 — le panneau existe dès index.html, tandis que le bouton PROFIL
     * est créé à l'ouverture du menu des filtres. Les deux sont donc liés
     * indépendamment et de façon idempotente.
     */
    if (panel && panel.dataset.profileBound !== '1') {
        panel.dataset.profileBound = '1';

        zoneFilters?.addEventListener('change', event => {
            const input = event.target?.closest?.('input[data-sia-profile-filter-key]');
            if (!input) return;
            setSiaProfileFilterEnabled(input.dataset.siaProfileFilterKey, input.checked);
            scheduleSiaProfileRefresh('profile-zone-filter');
        });

        mapZonesToggle?.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            setSiaMapAirspacesVisible(!siaMapAirspacesVisible);
        });
        updateSiaProfileMapZonesToggleButton();

        closeButton?.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            setSiaProfileOpen(false);
        });

        panel.querySelectorAll('[data-profile-range]').forEach(rangeButton => {
            rangeButton.addEventListener('click', event => {
                event.preventDefault();
                event.stopPropagation();

                const distance = Number(rangeButton.dataset.profileRange);
                if (![25, 50, 100].includes(distance)) return;

                siaProfileDistanceNm = distance;
                // Un changement d'échelle invalide les intervalles mémorisés
                // pour l'animation de glissement du profil.
                siaProfilePreviousMotionPosition = null;
                siaProfilePreviousIntervals = new Map();
                panel.querySelectorAll('[data-profile-range]').forEach(other =>
                    other.classList.toggle('active', other === rangeButton)
                );
                scheduleSiaProfileRefresh('range');
            });
        });
    }

    /*
     * v15.65 — geste iPad depuis une poignée située à l'intérieur du viewport.
     * Le vrai bord système iPadOS reste réservé au système ; cette poignée est
     * volontairement placée juste au-dessus de la safe-area.
     */
    if (swipeHandle && swipeHandle.dataset.profileSwipeBound !== '1') {
        swipeHandle.dataset.profileSwipeBound = '1';
        swipeHandle.hidden = siaProfileOpen;

        let startY = null;
        let lastY = null;

        const resetSwipe = () => {
            startY = null;
            lastY = null;
        };

        swipeHandle.addEventListener('touchstart', event => {
            if (event.touches?.length !== 1) return;
            startY = Number(event.touches[0].clientY);
            lastY = startY;
            event.preventDefault();
        }, { passive: false });

        swipeHandle.addEventListener('touchmove', event => {
            if (startY === null || event.touches?.length !== 1) return;
            lastY = Number(event.touches[0].clientY);
            event.preventDefault();
        }, { passive: false });

        swipeHandle.addEventListener('touchend', event => {
            const endY = lastY;
            if (startY !== null && Number.isFinite(endY) && endY - startY <= -35) {
                setSiaProfileOpen(true);
            }
            resetSwipe();
            event.preventDefault();
        }, { passive: false });

        swipeHandle.addEventListener('touchcancel', resetSwipe, { passive: true });
        swipeHandle.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            setSiaProfileOpen(true);
        });
    }

    if (panel && panel.dataset.profileSwipeCloseBound !== '1') {
        panel.dataset.profileSwipeCloseBound = '1';
        const header = panel.querySelector('.sia-profile-header');
        if (header) {
            let headerStartY = null;
            let headerLastY = null;

            header.addEventListener('touchstart', event => {
                if (event.target?.closest?.('button')) return;
                if (event.touches?.length !== 1) return;
                headerStartY = Number(event.touches[0].clientY);
                headerLastY = headerStartY;
            }, { passive: true });

            header.addEventListener('touchmove', event => {
                if (headerStartY === null || event.touches?.length !== 1) return;
                headerLastY = Number(event.touches[0].clientY);
            }, { passive: true });

            header.addEventListener('touchend', () => {
                if (
                    headerStartY !== null
                    && Number.isFinite(headerLastY)
                    && headerLastY - headerStartY >= 45
                ) {
                    setSiaProfileOpen(false);
                }
                headerStartY = null;
                headerLastY = null;
            }, { passive: true });
        }
    }

    if (button && button.dataset.profileBound !== '1') {
        button.dataset.profileBound = '1';
        button.classList.toggle('active', siaProfileOpen);
        button.setAttribute('aria-pressed', siaProfileOpen ? 'true' : 'false');

        button.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();

            setSiaProfileOpen(!siaProfileOpen);

            // Le menu filtres ne reste pas posé au-dessus du profil.
            const modal = button.closest('.sia-filter-modal');
            if (modal) {
                modal.classList.remove('open');
                modal.setAttribute('aria-hidden', 'true');
            }
        });
    }

    if (!window.__npfSiaProfileViewportEventsBound) {
        window.__npfSiaProfileViewportEventsBound = true;

        window.addEventListener('resize', scheduleSiaProfileViewportSync, { passive: true });
        window.addEventListener(
            'orientationchange',
            () => setTimeout(scheduleSiaProfileViewportSync, 180),
            { passive: true }
        );

        if (window.visualViewport) {
            window.visualViewport.addEventListener(
                'resize',
                scheduleSiaProfileViewportSync,
                { passive: true }
            );
            window.visualViewport.addEventListener(
                'scroll',
                scheduleSiaProfileViewportSync,
                { passive: true }
            );
        }
    }
}

function initializeSiaSystem() {
    if (window.__npfSiaSystemReady) return;
    window.__npfSiaSystemReady = true;

    ensureSiaMapPanes();
    loadSiaFilterPrefs();
    migrateSiaSivFilterPreference();
    bindSiaManagementButtons();
    initializeSiaAirspaceProfileUi();
    updateSiaProfileMapZonesToggleButton();
    refreshSiaManagementStatus();

    if (map && !map.__npfSiaEventsBound) {
        map.__npfSiaEventsBound = true;
        /*
         * v15.91 — précharger avant de sortir du tampon pendant le déplacement,
         * puis repositionner/recharger proprement à la fin du geste.
         */
        let npfDiagMoveSample = null;
        let npfDiagZoomStartedAt = 0;

        map.on('movestart', () => {
            const gpsFollowPan = isNpfGpsFollowProgrammaticPan();
            if (!gpsFollowPan) {
                clearTimeout(siaMoveDecorationRefreshTimer);
                siaMoveDecorationRefreshTimer = null;
                siaDecorationProgressiveRun += 1;
            }
            const now = NPF_STARTUP_DIAGNOSTIC.now();
            npfDiagMoveSample = {
                startedAt: now,
                lastAt: now,
                events: 0,
                gapTotal: 0,
                maxGap: 0,
                source: gpsFollowPan
                    ? 'gps-follow'
                    : (centerGpsFollowUserGestureActive ? 'manual' : 'autre')
            };
        });
        map.on('move', () => {
            if (!npfDiagMoveSample) return;
            const now = NPF_STARTUP_DIAGNOSTIC.now();
            const gap = Math.max(0, now - npfDiagMoveSample.lastAt);
            npfDiagMoveSample.lastAt = now;
            npfDiagMoveSample.events += 1;
            npfDiagMoveSample.gapTotal += gap;
            npfDiagMoveSample.maxGap = Math.max(npfDiagMoveSample.maxGap, gap);
        });
        map.on('moveend', () => {
            const sample = npfDiagMoveSample;
            npfDiagMoveSample = null;
            if (sample) {
                const now = NPF_STARTUP_DIAGNOSTIC.now();
                const avgGap = sample.events > 0 ? sample.gapTotal / sample.events : 0;
                npfDiagMapMotion(sample.source || 'autre', {
                    dureeMs: Math.round(now - sample.startedAt),
                    moveEvents: sample.events,
                    gapMoyMs: Math.round(avgGap),
                    gapMaxMs: Math.round(sample.maxGap),
                    zoom: map.getZoom(),
                    zonesVisibles: Array.isArray(siaRenderedAirspaceFeatures) ? siaRenderedAirspaceFeatures.length : 0
                });
            } else if (consumeSiaStartupPassiveMoveendGuard()) {
                npfDiagSiaInteraction(
                    'SIA RAFRAÎCHISSEMENT',
                    `raison=moveend-passif-post-startup · ignoré · zoom=${map.getZoom()} · zones=${Array.isArray(siaRenderedAirspaceFeatures) ? siaRenderedAirspaceFeatures.length : 0}`,
                    { totalMs: 0 }
                );
                return;
            }
            const gpsFollowMoveend = sample?.source === 'gps-follow' || isNpfGpsFollowProgrammaticPan();
            /* v16.58 — Leaflet peut émettre moveend au milieu d'un pinch/zoom.
             * Aucun rendu SIA intermédiaire : seul zoomend reconstruira la vue. */
            if (siaZoomGestureActive) {
                npfDiagSiaInteraction(
                    'SIA RAFRAÎCHISSEMENT',
                    `raison=moveend-pendant-zoom · ignoré · zoom=${map.getZoom()}`,
                    { totalMs: 0 }
                );
                return;
            }
            if (siaHeavyZoomFinalRefreshPending) {
                npfDiagSiaInteraction(
                    'SIA RAFRAÎCHISSEMENT',
                    `raison=moveend-attente-fin-routes-ht · ignoré · zoom=${map.getZoom()}`,
                    { totalMs: 0 }
                );
                return;
            }
            if (siaStartupInitialRefreshPending && !siaRenderedCoverageBounds) {
                npfDiagSiaInteraction(
                    'SIA RAFRAÎCHISSEMENT',
                    `raison=moveend-démarrage · différé vers startup-prefs · zoom=${map.getZoom()}`,
                    { totalMs: 0 }
                );
            } else {
                scheduleSiaCoverageRefresh(gpsFollowMoveend ? 'gps-follow' : 'moveend');
            }
        });
        map.on('zoomstart', () => {
            npfDiagZoomStartedAt = NPF_STARTUP_DIAGNOSTIC.now();
            siaZoomGestureActive = true;
            /* v16.62 — une transaction Routes/HT différée peut couvrir plusieurs
             * zoomend intermédiaires. Garder le verrou SIA tant que son Promise
             * commun n'est pas résolu. */
            siaHeavyZoomFinalRefreshPending = Boolean(npfHeavyOverlayZoomOutPromise);
            /* v16.58 — tout travail de l'ancien zoom est obsolète, quel que soit son motif. */
            cancelAllSiaWorkForZoomStart();
        });
        map.on('zoomend', () => {
            const now = NPF_STARTUP_DIAGNOSTIC.now();
            siaZoomGestureActive = false;
            if (npfDiagZoomStartedAt > 0) {
                npfDiagZoom({
                    dureeMs: Math.round(now - npfDiagZoomStartedAt),
                    zoom: map.getZoom(),
                    zonesVisibles: Array.isArray(siaRenderedAirspaceFeatures) ? siaRenderedAirspaceFeatures.length : 0
                });
                npfDiagZoomStartedAt = 0;
            }
            const heavyZoomPromise = npfHeavyOverlayZoomOutPromise;
            if (heavyZoomPromise) {
                /* v16.62 — tous les zoomend intermédiaires observent le même
                 * Promise débouncé. N'enregistrer qu'un seul finally afin de ne
                 * lancer qu'un unique SIA sur la vue finale stabilisée. */
                siaHeavyZoomFinalRefreshPending = true;
                if (siaHeavyZoomObservedPromise !== heavyZoomPromise) {
                    siaHeavyZoomObservedPromise = heavyZoomPromise;
                    heavyZoomPromise.finally(() => {
                        if (siaHeavyZoomObservedPromise !== heavyZoomPromise) return;
                        siaHeavyZoomObservedPromise = null;
                        if (!siaZoomGestureActive) {
                            scheduleSiaLayerRefresh('zoomend-after-routes-ht');
                        } else {
                            siaHeavyZoomFinalRefreshPending = false;
                        }
                    });
                }
            } else {
                scheduleSiaLayerRefresh('zoomend');
            }
        });
    }

    if (hasAnyEnabledSiaFilter()) {
        siaStartupInitialRefreshPending = true;
        setTimeout(() => {
            // v16.57 — un seul rendu initial, sur la vue réellement courante.
            siaStartupInitialRefreshPending = false;
            scheduleSiaLayerRefresh('startup-prefs');
        }, 900);
    }
}


// =========================================================================
// v15.48 — CORRECTIONS TACTILES / VRP / CTR / APPUI LONG
// =========================================================================

function installQuickOfflineMapButtonInteractions(button) {
    if (!button || button.dataset.siaLongPressBound === '1') return;
    button.dataset.siaLongPressBound = '1';

    protectNpfLongPressControlFromIosSelection(button);

    let longPressTimer = null;
    let longPressTriggered = false;
    let pointerStartX = null;
    let pointerStartY = null;

    const clearLongPress = () => {
        if (longPressTimer) {
            clearTimeout(longPressTimer);
            longPressTimer = null;
        }
        pointerStartX = null;
        pointerStartY = null;
    };

    const startLongPress = event => {
        if (event && event.button !== undefined && event.button !== 0) return;
        if (event && typeof event.preventDefault === 'function' && event.cancelable) event.preventDefault();
        clearLongPress();
        longPressTriggered = false;
        pointerStartX = Number(event?.clientX);
        pointerStartY = Number(event?.clientY);
        longPressTimer = setTimeout(() => {
            longPressTimer = null;
            longPressTriggered = true;
            try { window.getSelection?.()?.removeAllRanges?.(); } catch (_) {}
            openSiaFilterDialog();
        }, 650);
    };

    const trackPointer = event => {
        if (!longPressTimer || pointerStartX === null || pointerStartY === null) return;
        const dx = Number(event?.clientX) - pointerStartX;
        const dy = Number(event?.clientY) - pointerStartY;
        if (Number.isFinite(dx) && Number.isFinite(dy) && Math.hypot(dx, dy) > 12) {
            clearLongPress();
        }
    };

    button.addEventListener('selectstart', event => event.preventDefault());
    button.addEventListener('dragstart', event => event.preventDefault());
    button.addEventListener('pointerdown', startLongPress, { passive: false });
    button.addEventListener('pointermove', trackPointer, { passive: true });
    button.addEventListener('pointerup', clearLongPress);
    button.addEventListener('pointerleave', clearLongPress);
    button.addEventListener('pointercancel', clearLongPress);
    button.addEventListener('contextmenu', event => {
        event.preventDefault();
        clearLongPress();
        longPressTriggered = true;
        try { window.getSelection?.()?.removeAllRanges?.(); } catch (_) {}
        openSiaFilterDialog();
    });
    button.addEventListener('click', event => {
        if (longPressTriggered) {
            event.preventDefault();
            event.stopPropagation();
            longPressTriggered = false;
            return;
        }
        openQuickOfflineMapSelector();
    });
}

function getSiaVrpSymbolText(item) {
    const codeId = String(item?.c || '').trim().toUpperCase();
    const published = String(item?.d || '').trim().toUpperCase();

    /*
     * Les codes SIA VRP sont très souvent construits avec un préfixe terrain
     * de 2 caractères (MTNE -> NE, LBAL -> AL, TBMAT -> MAT). On utilise
     * cette forme courte lorsqu'elle tient en 1 à 3 caractères, sinon on
     * conserve le libellé publié.
     */
    if (codeId.length > 2) {
        const shortCode = codeId.slice(2);
        if (/^[A-Z0-9]{1,3}$/.test(shortCode)) return shortCode;
    }
    return published || codeId || '?';
}

/* v15.87 — VRP légèrement plus compacts ; hitbox tactile inchangée. */
function getSiaVrpVisualSize(label) {
    // v15.88 — diamètre visuel homogène ; seule la taille du texte varie.
    void label;
    return 24;
}

function addSiaTouchHitbox(latlng, popupHtml, popupFactory = null) {
    if (!siaLayerGroup || !latlng || !popupHtml) return null;

    /*
     * v15.50 — même correction que pour les terrains NPF : surface SVG
     * quasi invisible plutôt qu'un DIV vide. Diamètre tactile 56 px.
     */
    ensureSiaMapPanes();
    const hitbox = L.circleMarker(latlng, {
        pane: 'siaPointTouchPane',
        renderer: siaPointTouchRenderer || undefined,
        radius: 28,
        stroke: false,
        color: '#000000',
        opacity: 0,
        fill: true,
        fillColor: '#000000',
        fillOpacity: 0.002,
        interactive: true,
        bubblingMouseEvents: false,
        keyboard: false
    });
    hitbox.bindPopup(popupHtml, { maxWidth: 340 });
    hitbox.on('click', event => {
        try {
            if (event?.originalEvent) {
                L.DomEvent.stopPropagation(event.originalEvent);
            }
        } catch (_) {}

        /*
         * v16.12 — même arbitrage pour les VRP/SIA : si le doigt est réellement
         * sur le losange WP, ouvrir le WP ; sinon la fiche SIA reste accessible.
         */
        if (window.__npfWaypointRouteReady === true
            && openNpfWaypointPopupNearLatLng(
                event?.latlng || hitbox.getLatLng(),
                NPF_WAYPOINT_SELECT_TOLERANCE_PX
            )) {
            return;
        }

        try {
            if (typeof popupFactory === 'function') {
                hitbox.setPopupContent(popupFactory());
            }
            hitbox.openPopup();
        } catch (_) {}
    });
    hitbox.addTo(siaLayerGroup);
    try { if (hitbox.bringToFront) hitbox.bringToFront(); } catch (_) {}
    return hitbox;
}

function formatSiaCtrServices(item) {
    const services = Array.isArray(item?.sv) ? item.sv : [];
    if (!services.length) return '';

    const rows = services.map(service => {
        const type = String(service?.[0] || '').trim();
        const unitRaw = String(service?.[1] || '').trim();
        const unit = unitRaw.replace(/^[A-Z]{4}\s+/, '').trim();
        const frequencies = Array.isArray(service?.[2]) ? service[2] : [];

        const freqText = frequencies
            .map(freq => {
                const value = String(freq?.[0] || '').trim();
                const uom = String(freq?.[1] || '').trim();
                return value ? `${escapeHtml(value)}${uom ? ` ${escapeHtml(uom)}` : ''}` : '';
            })
            .filter(Boolean)
            .join(' / ');

        if (!freqText) return '';

        const hours = [...new Set(
            frequencies
                .map(freq => String(freq?.[2] || '').trim())
                .filter(Boolean)
        )].join(' / ');

        const callSign = frequencies
            .map(freq => String(freq?.[3] || '').trim())
            .find(Boolean) || '';

        return `
            <div class="sia-ctr-service-row">
                <strong>${escapeHtml(type || 'Service')} :</strong> ${freqText}
                ${unit ? `<span class="sia-ctr-service-unit">${escapeHtml(unit)}</span>` : ''}
                ${callSign ? `<span class="sia-ctr-service-call">${escapeHtml(callSign)}</span>` : ''}
                ${hours ? `<span class="sia-ctr-service-hours">${escapeHtml(hours)}</span>` : ''}
            </div>
        `;
    }).filter(Boolean).join('');

    if (!rows) return '';
    return `<div class="sia-ctr-services"><div class="sia-ctr-services-title">Fréquences associées SIA</div>${rows}</div>`;
}

function formatSiaCtrFrequencyValue(value, unit = '') {
    const raw = String(value || '').trim();
    if (!raw) return '';
    const numeric = Number(raw.replace(',', '.'));
    if (Number.isFinite(numeric) && String(unit || '').toUpperCase() === 'MHZ') {
        return numeric.toFixed(3);
    }
    return raw;
}

function normalizeSiaFrequencyServiceLabel(value) {
    const raw = String(value || '').trim().toUpperCase();
    if (!raw) return 'FREQ';
    if (raw === 'GND' || raw === 'GROUND') return 'SOL';
    return raw;
}


/*
 * v15.62 — enrichissement opérationnel des zones R.
 *
 * Ordre de priorité demandé :
 * 1) instruction explicite d'entrée/clairance/contact/autorisation ;
 * 2) gestionnaire publié (Administrator / Managing authority) ;
 * 3) service ATS explicite dans les premières lignes, hors listes "activity known".
 *
 * Une liste "Activity known on" ne sert JAMAIS à nommer la zone. Elle peut
 * uniquement fournir une fréquence de repli si le service retenu est clairement
 * cité sur la même ligne. Aucun rapprochement géographique n'est utilisé.
 */
const siaRestrictedRemarkInfoCache = new WeakMap();

function normalizeSiaAirspaceRemarkLines(item) {
    return String(item?.r || '')
        .replace(/#/g, '\n')
        .replace(/\r/g, '\n')
        .split('\n')
        .map(line => line.replace(/\s+/g, ' ').trim())
        .filter(Boolean);
}

function extractSiaOperationalServiceFromChunk(value) {
    let text = String(value || '')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/^[\s\-–—:;,.]+/, '');

    // v15.64 — une condition météo/visibilité n'est pas un indicatif de service.
    if (/^(?:VISI|VISIBILITY|METEO|WEATHER)\b/i.test(text)) return null;

    text = text
        .replace(/^(?:ACTUAL\s+)?ACTIVITY\s+KNOWN\s+ON\s*:?\s*/i, '')
        .replace(/^RADIO\s+CONTACT(?:\s+MANDATORY)?\s+WITH\s*:?\s*/i, '');

    const match = text.match(
        /^(.{1,70}?)\s+(APP|TWR|INFO|SIV|FIS|ACC|FIC|AFIS|ATIS|A\/A|CONTROL)\b/i
    );
    if (!match) return null;

    let operationalName = String(match[1] || '')
        .trim()
        .replace(/^[\s\-–—:;,.]+|[\s\-–—:;,.]+$/g, '')
        .replace(/^.*:\s*/i, '')
        .replace(/^.*\b(?:THROUGH|FOLLOW|BY|ON|UPON|WITH|OF|AFTER|AND|OR|FROM)\s+/i, '')
        .replace(/^(?:MANDATORY|CONTACT|WITH|CLEARANCE)\s+/i, '')
        .trim()
        .toUpperCase();

    if (!operationalName || /^(?:NIL|NONE|N\/A)$/.test(operationalName)) return null;

    return {
        operationalName,
        serviceType: String(match[2] || '').trim().toUpperCase(),
        rawService: String(match[0] || '').trim()
    };
}

function extractSiaAeronauticalFrequencyFromText(value) {
    const text = String(value || '');
    const regex = /\b((?:1[1-3]\d|2\d{2}|3\d{2})(?:[.,]\d{1,3}))\s*(?:MHZ)?\b/i;
    const match = text.match(regex);
    if (!match) return '';

    const numeric = Number(String(match[1] || '').replace(',', '.'));
    if (!Number.isFinite(numeric) || numeric < 118 || numeric >= 400) return '';
    return numeric.toFixed(3);
}

let siaRestrictedCrossReferenceNameIndex = null;

function normalizeSiaRestrictedReferenceCode(value) {
    return String(value || '')
        .trim()
        .toUpperCase()
        .replace(/^LF\s*-?\s*R\s*/i, '')
        .replace(/\s+/g, '');
}

function cleanSiaRestrictedCrossReferenceName(value) {
    let name = String(value || '')
        .trim()
        .replace(/^[\s\-–—:;,.()]+|[\s\-–—:;,.()]+$/g, '')
        .replace(/\s+/g, ' ')
        .toUpperCase();

    // Ces mots décrivent l'état ou la relation, pas un nom géographique.
    if (!name || /^(?:IS|ARE|ACTIVE|ACTIVATED|WHEN|IF|PART|AREA|AREAS|ZONE|ZONES)\b/i.test(name)) return '';
    if (/^(?:ACTIVITY|ACTIVATION)\b/i.test(name)) return '';
    if (/\bLF\s*-\s*[PRD]\b/i.test(name)) return '';
    if (/^\d+(?:[./]\d+)*$/.test(name)) return '';

    /*
     * v15.64 — garde-fou contre les faux noms issus de conditions opérationnelles.
     * Exemple R8 : « VISI > or = 5 km : ATIS GARONS » ne doit jamais produire
     * « = 5 KM » comme nom de zone.
     */
    if (/(?:^|\b)(?:VISI|VISIBILITY|METEO|WEATHER)\b/i.test(name)) return '';
    if (/(?:>=|<=|>|<|=)\s*\d/i.test(name)) return '';
    if (/^=?\s*\d+(?:[.,]\d+)?\s*(?:KM|NM|FT|M|FL\d*)\b/i.test(name)) return '';
    return name;
}

function buildSiaRestrictedCrossReferenceNameIndex(dataset = siaDataset) {
    if (siaRestrictedCrossReferenceNameIndex) return siaRestrictedCrossReferenceNameIndex;

    const counts = new Map();
    const referenceRegex = /\bLF\s*-\s*R\s*([0-9A-Z./]+)\s+(.+?)(?=\s+(?:OR|AND)\s+LF\s*-\s*R\s*[0-9]|\s+(?:WHEN|INTERFERING|EXCEPT|EXCLUDING|WHICH|ACTIVITY|ACTIVATION|IS\s+ACTIVE|ARE\s+ACTIVE)\b|[#;,\n.]|$)/gi;

    (dataset?.airspaces || []).forEach(sourceItem => {
        const remark = String(sourceItem?.r || '');
        if (!remark) return;

        referenceRegex.lastIndex = 0;
        for (const match of remark.matchAll(referenceRegex)) {
            const code = normalizeSiaRestrictedReferenceCode(match?.[1]);
            const name = cleanSiaRestrictedCrossReferenceName(match?.[2]);
            if (!code || !name) continue;

            if (!counts.has(code)) counts.set(code, new Map());
            const nameCounts = counts.get(code);
            nameCounts.set(name, (nameCounts.get(name) || 0) + 1);
        }
    });

    const index = new Map();
    counts.forEach((nameCounts, code) => {
        const ordered = [...nameCounts.entries()].sort((a, b) => {
            if (a[1] !== b[1]) return b[1] - a[1];
            if (a[0].length !== b[0].length) return b[0].length - a[0].length;
            return a[0].localeCompare(b[0], 'fr');
        });
        if (ordered[0]?.[0]) index.set(code, ordered[0][0]);
    });

    siaRestrictedCrossReferenceNameIndex = index;
    return index;
}

function getSiaRestrictedCrossReferenceName(item) {
    if (String(item?.t || '').trim().toUpperCase() !== 'R') return '';
    const code = normalizeSiaRestrictedReferenceCode(item?.c);
    if (!code) return '';
    return buildSiaRestrictedCrossReferenceNameIndex().get(code) || '';
}


/*
 * v15.65 — même principe pour les zones P : leur propre fiche contient
 * souvent seulement le numéro alors que d'autres espaces publient explicitement
 * "LF-P xx NOM" (P62 TOULON, P48 FORT DE BRÉGANÇON, P63 ILE DU LEVANT...).
 */
let siaProhibitedCrossReferenceNameIndex = null;

function normalizeSiaProhibitedReferenceCode(value) {
    return String(value || '')
        .trim()
        .toUpperCase()
        .replace(/^LF\s*-?\s*P\s*/i, '')
        .replace(/\s+/g, '');
}

function buildSiaProhibitedCrossReferenceNameIndex(dataset = siaDataset) {
    if (siaProhibitedCrossReferenceNameIndex) return siaProhibitedCrossReferenceNameIndex;

    const counts = new Map();
    const referenceRegex = /\bLF\s*-\s*P\s*([0-9A-Z./]+)\s+(.+?)(?=\s+(?:OR|AND)\s+LF\s*-\s*[PRD]\s*[0-9]|,\s*LF\s*-\s*[PRD]\s*[0-9]|\s+(?:WHEN|INTERFERING|EXCEPT|EXCLUDING|WHICH|ACTIVITY|ACTIVATION|IS\s+ACTIVE|ARE\s+ACTIVE)\b|[#;\n.]|$)/gi;

    (dataset?.airspaces || []).forEach(sourceItem => {
        const remark = String(sourceItem?.r || '');
        if (!remark) return;

        referenceRegex.lastIndex = 0;
        for (const match of remark.matchAll(referenceRegex)) {
            const code = normalizeSiaProhibitedReferenceCode(match?.[1]);
            const name = cleanSiaRestrictedCrossReferenceName(match?.[2]);
            if (!code || !name) continue;

            if (!counts.has(code)) counts.set(code, new Map());
            const nameCounts = counts.get(code);
            nameCounts.set(name, (nameCounts.get(name) || 0) + 1);
        }
    });

    const index = new Map();
    counts.forEach((nameCounts, code) => {
        const ordered = [...nameCounts.entries()].sort((a, b) => {
            if (a[1] !== b[1]) return b[1] - a[1];
            if (a[0].length !== b[0].length) return b[0].length - a[0].length;
            return a[0].localeCompare(b[0], 'fr');
        });
        if (ordered[0]?.[0]) index.set(code, ordered[0][0]);
    });

    siaProhibitedCrossReferenceNameIndex = index;
    return index;
}

function getSiaProhibitedCrossReferenceName(item) {
    if (String(item?.t || '').trim().toUpperCase() !== 'P') return '';
    const code = normalizeSiaProhibitedReferenceCode(item?.c);
    if (!code) return '';
    return buildSiaProhibitedCrossReferenceNameIndex().get(code) || '';
}

/*
 * v15.68 — les zones P utilisent désormais le NomUsuel de leur propre Partie
 * dans XML_SIA, embarqué dans item.pn. Les phrases réglementaires rencontrées
 * dans les remarques d'autres espaces ne sont plus admises comme nom de carte.
 * Si le SIA ne fournit pas de NomUsuel, le libellé reste volontairement P + numéro.
 */
function getSiaProhibitedOfficialName(item) {
    if (String(item?.t || '').trim().toUpperCase() !== 'P') return '';
    return String(item?.pn || '').trim();
}

function getSiaRestrictedAdministratorFallback(administratorChunk) {
    const chunk = String(administratorChunk || '').trim();
    if (!chunk) return null;

    const atsService = extractSiaOperationalServiceFromChunk(chunk);
    if (atsService) return atsService;

    /*
     * v15.64 — lorsqu'un gestionnaire publie lui-même un lieu géographique
     * explicite, celui-ci est plus fiable que le nom rencontré seulement dans
     * une référence croisée. Ex. « 2ème REI, camp des Garrigues » -> GARRIGUES.
     */
    const placePatterns = [
        /\bCAMP\s+(?:DES|DU|DE|D['’])\s*([A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ'’.\- ]{1,45}?)(?=[.;,]|$)/i,
        /\bBASE(?:\s+A[ÉE]RIENNE)?\s+(?:DES|DU|DE|D['’])\s*([A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ'’.\- ]{1,45}?)(?=[.;,]|$)/i,
        /\bCENTRE\s+(?:DES|DU|DE|D['’])\s*([A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ'’.\- ]{1,45}?)(?=[.;,]|$)/i
    ];

    for (const pattern of placePatterns) {
        const match = chunk.match(pattern);
        if (!match) continue;
        const operationalName = String(match[1] || '')
            .trim()
            .replace(/\s+/g, ' ')
            .toUpperCase();
        if (!operationalName) continue;
        return {
            operationalName,
            serviceType: '',
            rawService: String(match[0] || '').trim(),
            administratorGeographic: true
        };
    }

    /*
     * Gestionnaires militaires : le lieu est conservé, l'acronyme organique
     * n'est pas utilisé comme nom de zone. Ex. "CCER Istres or CMC Istres"
     * -> ISTRES.
     */
    const organizationMatch = chunk.match(
        /\b(?:CCER|CMC|CMCI|CDC|CLA|ESCA|CDPGE)\s+([A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ'’.\- ]{1,30}?)(?=\s+(?:OR|AND)\b|[.;,]|$)/i
    );
    const airForceBaseMatch = chunk.match(
        /^(.{2,30}?)\s+AIR\s+FORCE\s+BASE\b/i
    );
    const fallbackMatch = organizationMatch || airForceBaseMatch;
    if (!fallbackMatch) return null;

    const operationalName = String(fallbackMatch[1] || '')
        .split(/[.;,]/)[0]
        .trim()
        .toUpperCase();

    if (!operationalName) return null;
    return {
        operationalName,
        serviceType: '',
        rawService: String(fallbackMatch[0] || '').trim(),
        administratorGeographic: true
    };
}

function getSiaRestrictedRemarkInfo(item) {
    if (String(item?.t || '').trim().toUpperCase() !== 'R') return null;

    if (item && typeof item === 'object' && siaRestrictedRemarkInfoCache.has(item)) {
        return siaRestrictedRemarkInfoCache.get(item);
    }

    const lines = normalizeSiaAirspaceRemarkLines(item);
    let service = null;
    let frequency = '';
    let sourceKind = '';
    let administratorChunk = '';

    /*
     * 1) Priorité absolue aux instructions opérationnelles explicites.
     * Ex. R108B :
     * "entry with clearance from CAMARGUE Control 127.925 MHz"
     * -> CAMARGUE / 127.925.
     */
    const explicitOperationalRegex =
        /(?:entry(?:\s+\w+){0,4}\s+with\s+clearance\s+from|clearance\s+(?:from|by)|radio\s+contact(?:\s+mandatory)?\s+with|contact\s+with|with\s+authori[sz]ation\s+of|upon\s+.*authori[sz]ation|authori[sz]ation\s+(?:of|from|by)|authori[sz]ed\s+by)\s+(.+)/i;

    for (const line of lines) {
        const explicitMatch = line.match(explicitOperationalRegex);
        if (!explicitMatch) continue;

        const explicitService = extractSiaOperationalServiceFromChunk(explicitMatch[1]);
        if (!explicitService) continue;

        service = explicitService;
        frequency = extractSiaAeronauticalFrequencyFromText(line);
        sourceKind = 'explicit';
        break;
    }

    // 2) À défaut seulement : gestionnaire/autorité explicitement publié.
    if (!service) {
        for (const line of lines) {
            const administratorMatch = line.match(
                /(?:Admin(?:istrator|itrator)s?|Managing\s+authority)\s*:?\s*(.+)/i
            );
            if (!administratorMatch) continue;

            administratorChunk = String(administratorMatch[1] || '').trim();
            service = getSiaRestrictedAdministratorFallback(administratorChunk);
            if (service) {
                frequency = extractSiaAeronauticalFrequencyFromText(line);
                sourceKind = 'administrator';
                break;
            }
        }
    } else {
        // On mémorise quand même le gestionnaire pour la fiche, sans lui donner priorité.
        for (const line of lines) {
            const administratorMatch = line.match(
                /(?:Admin(?:istrator|itrator)s?|Managing\s+authority)\s*:?\s*(.+)/i
            );
            if (administratorMatch) {
                administratorChunk = String(administratorMatch[1] || '').trim();
                break;
            }
        }
    }

    /*
     * 3) Repli très conservateur : service ATS présent directement dans les
     * premières lignes, mais jamais une ligne "activity known".
     */
    if (!service) {
        for (const line of lines.slice(0, 4)) {
            if (/(?:actual\s+)?activity\s+known|activation\s+(?:known|provided|announced)/i.test(line)) continue;
            const directService = extractSiaOperationalServiceFromChunk(line);
            if (!directService) continue;
            service = directService;
            frequency = extractSiaAeronauticalFrequencyFromText(line);
            sourceKind = 'direct';
            break;
        }
    }

    const serviceOperationalName = String(service?.operationalName || '').trim();
    const crossReferenceName = getSiaRestrictedCrossReferenceName(item);

    /*
     * v15.63 — un vrai nom géographique publié ailleurs dans le même jeu SIA
     * devient le nom principal, sauf si une instruction explicite de clairance/
     * contact a fourni un service directement opérationnel (ex. R108B/CAMARGUE).
     */
    const operationalName = sourceKind === 'explicit'
        ? serviceOperationalName
        : (
            sourceKind === 'administrator' && service?.administratorGeographic
                ? serviceOperationalName
                : (crossReferenceName || serviceOperationalName)
        );

    /*
     * Fréquence de repli :
     * - si l'instruction opérationnelle retenue donne une fréquence, elle gagne ;
     * - sinon priorité à une ligne citant le SERVICE retenu ;
     * - les lignes "activity known" peuvent fournir la fréquence, mais jamais
     *   le NOM de la zone ;
     * - RAI n'est jamais affiché.
     */
    if (!frequency && serviceOperationalName) {
        const candidates = [];
        lines.forEach((line, lineIndex) => {
            const value = extractSiaAeronauticalFrequencyFromText(line);
            if (!value) return;

            const upperLine = line.toUpperCase();
            let score = 0;

            if (upperLine.includes(serviceOperationalName.toUpperCase())) score += 12;
            if (explicitOperationalRegex.test(line)) score += 10;
            if (/(?:Admin(?:istrator|itrator)s?|Managing\s+authority)/i.test(line)) score += 7;
            if (/(?:actual\s+)?activity\s+known|activation\s+(?:known|provided|announced)/i.test(line)) score += 3;
            if (/\bRAI\b/i.test(line)) score += 1;

            if (score <= 0) return;
            candidates.push({ score, lineIndex, value });
        });

        candidates.sort((a, b) => {
            if (a.score !== b.score) return b.score - a.score;
            return a.lineIndex - b.lineIndex;
        });

        frequency = candidates[0]?.value || '';
    }

    const result = {
        operationalName,
        serviceName: serviceOperationalName,
        crossReferenceName,
        serviceType: service?.serviceType || '',
        frequency,
        sourceKind: crossReferenceName && sourceKind !== 'explicit' ? 'cross-reference' : sourceKind,
        administrator: administratorChunk
    };

    if (item && typeof item === 'object') {
        try { siaRestrictedRemarkInfoCache.set(item, result); } catch (_) {}
    }
    return result;
}

function formatSiaCtrFrequencyRows(item) {
    const effectiveServices = getSiaEffectiveServices(item);
    const services = effectiveServices.services;

    if (!services.length) {
        const restrictedInfo = getSiaRestrictedRemarkInfo(item);
        if (!restrictedInfo?.frequency) return '';

        const frequencyDetailName = restrictedInfo.serviceName || restrictedInfo.operationalName || '';
        const detail = frequencyDetailName
            ? `<div class="sia-airspace-frequency-detail">${escapeHtml(frequencyDetailName)}</div>`
            : '';

        return `
            <div class="sia-airspace-frequency-block">
                <div class="sia-ctr-frequency-row">Fréquence : ${escapeHtml(restrictedInfo.frequency)}</div>
                ${detail}
            </div>
        `;
    }

    const grouped = new Map();

    services.forEach(service => {
        const type = normalizeSiaFrequencyServiceLabel(service?.[0]);
        const unitName = String(service?.[1] || '').trim();
        const frequencies = Array.isArray(service?.[2]) ? service[2] : [];

        if (!grouped.has(type)) {
            grouped.set(type, {
                unitNames: [],
                frequencies: []
            });
        }

        const group = grouped.get(type);
        if (unitName && !group.unitNames.includes(unitName)) {
            group.unitNames.push(unitName);
        }

        frequencies.forEach(freq => {
            const formatted = formatSiaCtrFrequencyValue(freq?.[0], freq?.[1]);
            if (!formatted) return;

            const supplementary = Number(freq?.[4] || 0) === 1;
            const hours = String(freq?.[2] || '').trim();
            const callsign = String(freq?.[3] || '').trim();
            const key = [
                formatted,
                supplementary ? 1 : 0,
                hours,
                callsign
            ].join('|');

            if (!group.frequencies.some(entry => entry.key === key)) {
                group.frequencies.push({
                    key,
                    value: formatted,
                    supplementary,
                    hours,
                    callsign
                });
            }
        });
    });

    return [...grouped.entries()]
        .filter(([, group]) => group.frequencies.length)
        .map(([type, group]) => {
            const ordered = [
                ...group.frequencies.filter(v => !v.supplementary),
                ...group.frequencies.filter(v => v.supplementary)
            ];

            const frequencyText = ordered
                .map(v => `${v.value}${v.supplementary ? ' (s)' : ''}`)
                .join(' / ');

            const detailPairs = ordered.map(v => ({
                frequency: `${v.value}${v.supplementary ? ' (s)' : ''}`,
                hours: v.hours,
                callsign: v.callsign
            }));

            const uniqueDetails = new Map();
            detailPairs.forEach(detail => {
                const key = `${detail.hours}|${detail.callsign}`;
                if (!uniqueDetails.has(key)) uniqueDetails.set(key, detail);
            });

            let detailsHtml = '';
            if (uniqueDetails.size === 1) {
                const detail = [...uniqueDetails.values()][0];
                const detailText = [detail.hours, detail.callsign].filter(Boolean).join(' — ');
                if (detailText) {
                    detailsHtml += `<div class="sia-airspace-frequency-detail">${escapeHtml(detailText)}</div>`;
                }
            } else {
                detailPairs.forEach(detail => {
                    const detailText = [
                        detail.frequency,
                        detail.hours,
                        detail.callsign
                    ].filter(Boolean).join(' — ');
                    if (detailText) {
                        detailsHtml += `<div class="sia-airspace-frequency-detail">${escapeHtml(detailText)}</div>`;
                    }
                });
            }

            const zoneCode = String(item?.c || '').trim().toUpperCase();
            const zoneName = String(item?.n || '').trim().toUpperCase();
            const redundantUnit = group.unitNames.length === 1
                && String(group.unitNames[0]).trim().toUpperCase() === `${zoneCode} ${zoneName}`.trim();

            if (group.unitNames.length && !redundantUnit) {
                detailsHtml += `<div class="sia-airspace-frequency-detail">${escapeHtml(group.unitNames.join(' / '))}</div>`;
            }

            return `
                <div class="sia-airspace-frequency-block">
                    <div class="sia-ctr-frequency-row">${escapeHtml(type)} : ${escapeHtml(frequencyText)}</div>
                    ${detailsHtml}
                </div>
            `;
        })
        .join('');
}

let siaTmaFamilyServicesIndex = null;

function getSiaTmaServiceSignature(services) {
    if (!Array.isArray(services) || !services.length) return '';
    try {
        return JSON.stringify(services);
    } catch (_) {
        return '';
    }
}

function buildSiaTmaFamilyServicesIndex(dataset = siaDataset) {
    if (siaTmaFamilyServicesIndex) return siaTmaFamilyServicesIndex;

    const families = new Map();

    (dataset?.airspaces || []).forEach(item => {
        if (String(item?.t || '').trim().toUpperCase() !== 'TMA') return;

        const services = Array.isArray(item?.sv) ? item.sv : [];
        if (!services.length) return;

        const family = getSiaTmaFamilyBaseFromSectorName(item?.n);
        if (!family) return;

        const signature = getSiaTmaServiceSignature(services);
        if (!signature) return;

        if (!families.has(family)) families.set(family, new Map());
        const signatures = families.get(family);
        if (!signatures.has(signature)) signatures.set(signature, services);
    });

    const index = new Map();
    families.forEach((signatures, family) => {
        /*
         * Héritage uniquement si tous les secteurs renseignés de la famille
         * convergent vers un unique bloc de services. Aucune fréquence n'est
         * déduite en cas d'ambiguïté.
         */
        if (signatures.size === 1) {
            index.set(family, [...signatures.values()][0]);
        }
    });

    siaTmaFamilyServicesIndex = index;
    return index;
}

function getSiaEffectiveServices(item) {
    const direct = Array.isArray(item?.sv) ? item.sv : [];
    if (direct.length) {
        return { services: direct, inheritedFromFamily: false };
    }

    if (String(item?.t || '').trim().toUpperCase() !== 'TMA') {
        return { services: [], inheritedFromFamily: false };
    }

    const family = getSiaTmaFamilyBaseFromSectorName(item?.n);
    if (!family) return { services: [], inheritedFromFamily: false };

    const inherited = buildSiaTmaFamilyServicesIndex().get(family);
    if (!Array.isArray(inherited) || !inherited.length) {
        return { services: [], inheritedFromFamily: false };
    }

    return {
        services: inherited,
        inheritedFromFamily: true,
        inheritedFamily: family
    };
}

function getSiaFirstAssignedFrequency(item) {
    /*
     * v15.67 — pour un SIV, la fréquence affichée sur la carte n'est choisie
     * que lorsque XML_SIA la rattache sans ambiguïté au secteur (sfp).
     * Les autres fréquences FIS restent visibles dans la fiche détaillée via sv.
     */
    if (isSiaFlightInformationSector(item)) {
        const volumeAssigned = getSiaVolumeAssignedFrequencies(item);
        if (volumeAssigned.length) {
            return {
                serviceType: 'FIS',
                value: volumeAssigned.join(' / '),
                supplementary: false,
                sourceDesignatedSiv: true,
                sourceSivVolumeActivity: true
            };
        }

        const preferred = Array.isArray(item?.sfp)
            ? item.sfp.map(value => String(value || '').trim()).filter(Boolean)
            : [];
        if (preferred.length) {
            return {
                serviceType: 'FIS',
                value: preferred.join(' / '),
                supplementary: false,
                sourceDesignatedSiv: true
            };
        }
        if (Number(item?.sfa || 0) === 1) return null;
    }

    const effectiveServices = getSiaEffectiveServices(item);
    const services = effectiveServices.services;
    const candidates = [];

    services.forEach((service, serviceIndex) => {
        const serviceType = normalizeSiaFrequencyServiceLabel(service?.[0]);
        const frequencies = Array.isArray(service?.[2]) ? service[2] : [];

        frequencies.forEach((freq, freqIndex) => {
            const value = formatSiaCtrFrequencyValue(freq?.[0], freq?.[1]);
            if (!value) return;

            candidates.push({
                serviceType,
                value,
                supplementary: Number(freq?.[4] || 0) === 1,
                serviceIndex,
                freqIndex,
                inheritedFromFamily: effectiveServices.inheritedFromFamily === true,
                inheritedFamily: effectiveServices.inheritedFamily || ''
            });
        });
    });

    if (!candidates.length) {
        const restrictedInfo = getSiaRestrictedRemarkInfo(item);
        if (!restrictedInfo?.frequency) return null;

        return {
            serviceType: restrictedInfo.serviceType || '',
            value: restrictedInfo.frequency,
            supplementary: false,
            inferredFromRemark: true
        };
    }

    // Première fréquence normale dans l'ordre SIA ; supplétive seulement à défaut.
    candidates.sort((a, b) => {
        if (a.supplementary !== b.supplementary) return a.supplementary ? 1 : -1;
        if (a.serviceIndex !== b.serviceIndex) return a.serviceIndex - b.serviceIndex;
        return a.freqIndex - b.freqIndex;
    });

    return candidates[0];
}

function getSiaAirspaceBoundaryLabelText(item) {
    const displayType = getSiaAirspaceDisplayType(item);
    const type = String(item?.t || '').trim().toUpperCase();
    const name = String(item?.n || '').trim();
    const code = String(item?.c || '').trim();
    const primaryName = name || code;
    const base = [displayType, primaryName].filter(Boolean).join(' ');

    /* v16.63 — ligne 1 = nom uniquement. */
    if (type === 'R') {
        const restrictedInfo = getSiaRestrictedRemarkInfo(item);
        return [base, String(restrictedInfo?.operationalName || '').trim()]
            .filter(Boolean).join(' / ');
    }
    if (type === 'P') {
        return [base, getSiaProhibitedOfficialName(item)].filter(Boolean).join(' / ');
    }
    return base;
}

function getSiaAirspaceBoundaryFrequencyText(item) {
    const type = String(item?.t || '').trim().toUpperCase();
    if (type === 'P') return '';

    if (type === 'R') {
        const restrictedInfo = getSiaRestrictedRemarkInfo(item);
        const value = String(restrictedInfo?.frequency || '').trim();
        if (!value) return '';
        const serviceType = String(restrictedInfo?.serviceType || '').trim();
        return [serviceType, value].filter(Boolean).join(' ');
    }

    const firstFrequency = getSiaFirstAssignedFrequency(item);
    if (!firstFrequency) return '';
    const frequencyPrefix = firstFrequency.inferredFromRemark
        ? String(firstFrequency.serviceType || '').trim()
        : String(firstFrequency.serviceType || '').trim();
    const frequencyText = [frequencyPrefix, firstFrequency.value].filter(Boolean).join(' ');
    return `${frequencyText}${firstFrequency.supplementary ? ' (s)' : ''}`;
}

function getSiaAirspaceBoundaryVerticalText(item) {
    const hasLower = hasSiaVerticalValue(item?.lo);
    const hasUpper = hasSiaVerticalValue(item?.up);
    if (!hasLower && !hasUpper) return '';

    const lower = hasLower ? formatSiaVertical(item.lo) : '—';
    const upper = hasUpper ? formatSiaVertical(item.up) : '—';
    return `${lower} – ${upper}`;
}

function getSiaAirspaceDisplayType(item) {
    const type = String(item?.t || '').trim().toUpperCase();
    const local = String(item?.l || '').trim().toUpperCase();

    // v15.65 — les RAS "FLIGHT INFORMATION SECTOR" sont présentés comme SIV.
    if (isSiaFlightInformationSector(item)) return 'SIV';

    // Pour les D-OTHER, le type local est plus utile opérationnellement.
    if (type === 'D-OTHER' && local) return local;
    return type || 'ESPACE';
}

function getSiaAirspaceDisplayTitle(item) {
    const displayType = getSiaAirspaceDisplayType(item);
    const type = String(item?.t || '').trim().toUpperCase();
    const name = String(item?.n || '').trim();
    const code = String(item?.c || '').trim();

    // v15.57 — une TMA est présentée par son nom opérationnel, sans doublon
    // du code technique de secteur (LFML1, LFMN2, etc.).
    if (type === 'TMA') {
        return [displayType, name].filter(Boolean).join(' / ');
    }

    // v15.61 — les zones R gardent leur numéro lisible et ajoutent, lorsqu'il
    // est explicitement disponible, le gestionnaire/service opérationnel.
    if (type === 'R') {
        const restrictedInfo = getSiaRestrictedRemarkInfo(item);
        return [
            displayType,
            name || code,
            restrictedInfo?.operationalName || ''
        ].filter(Boolean).join(' / ');
    }

    if (type === 'P') {
        return [
            displayType,
            name || code,
            getSiaProhibitedOfficialName(item)
        ].filter(Boolean).join(' / ');
    }

    return [displayType, code, name].filter(Boolean).join(' / ');
}

function isSiaTechnicalTmaUnionParent(item) {
    return String(item?.t || '').toUpperCase() === 'TMA'
        && Number(item?.tp || 0) === 1;
}

function normalizeSiaTmaFamilyName(value) {
    return String(value || '')
        .trim()
        .toUpperCase()
        .replace(/\s+/g, ' ');
}

function getSiaTmaFamilyBaseFromSectorName(value) {
    const normalized = normalizeSiaTmaFamilyName(value);
    if (!normalized) return '';
    return normalized.replace(/\s+\d+(?:\.\d+)*$/, '').trim();
}

function hasSiaTmaVerticalLimits(item) {
    return hasSiaVerticalValue(item?.lo) || hasSiaVerticalValue(item?.up);
}

function buildSiaTmaOperationalFamilySet(dataset) {
    const families = new Set();

    for (const item of dataset?.airspaces || []) {
        if (String(item?.t || '').toUpperCase() !== 'TMA') continue;
        if (!hasSiaTmaVerticalLimits(item)) continue;

        const name = normalizeSiaTmaFamilyName(item?.n);
        const family = getSiaTmaFamilyBaseFromSectorName(name);

        if (family && family !== name) {
            families.add(family);
        }
    }
    return families;
}

function isSiaGenericTmaWithoutAltitude(item, operationalFamilies) {
    if (String(item?.t || '').toUpperCase() !== 'TMA') return false;
    if (hasSiaTmaVerticalLimits(item)) return false;

    const name = normalizeSiaTmaFamilyName(item?.n);
    return !!name
        && operationalFamilies instanceof Set
        && operationalFamilies.has(name);
}

function hasSiaVerticalValue(raw) {
    return Array.isArray(raw) && String(raw?.[1] || '').trim() !== '';
}

function formatSiaAirspaceRemark(value) {
    return escapeHtml(String(value || '').trim()).replace(/#|\n/g, '<br>');
}

function buildSiaAirspacePopup(item) {
    const displayType = getSiaAirspaceDisplayType(item);
    const title = getSiaAirspaceDisplayTitle(item);
    const typeClass = [displayType, item?.cl].filter(Boolean).join(' / ');
    const vertical = `${formatSiaVertical(item?.lo)} / ${formatSiaVertical(item?.up)}`;
    const frequencyRows = formatSiaCtrFrequencyRows(item);

    const minVertical = hasSiaVerticalValue(item?.mi)
        ? formatSiaVertical(item.mi)
        : '';
    const maxVertical = hasSiaVerticalValue(item?.ma)
        ? formatSiaVertical(item.ma)
        : '';

    const activity = String(item?.a || '').trim();
    const identifier = String(item?.i || '').trim();
    const code = String(item?.c || '').trim();
    const remark = String(item?.r || '').trim();

    /*
     * v15.55 — présentation identique pour toutes les zones :
     * - les 3 lignes principales restent sans libellés ;
     * - toutes les autres données opérationnelles réellement présentes dans
     *   le payload SIA sont ajoutées ;
     * - aucune information n'est déduite par proximité.
     */
    return `
        <div class="sia-popup sia-ctr-popup sia-ctr-popup-compact sia-airspace-popup-compact">
            <div class="sia-popup-title">${escapeHtml(title || displayType)}</div>

            <div class="sia-ctr-info-row">${escapeHtml(typeClass || displayType)}</div>
            <div class="sia-ctr-info-row">${escapeHtml(vertical)}</div>

            ${minVertical ? `<div class="sia-airspace-extra-row">MIN : ${escapeHtml(minVertical)}</div>` : ''}
            ${maxVertical ? `<div class="sia-airspace-extra-row">MAX : ${escapeHtml(maxVertical)}</div>` : ''}

            ${frequencyRows}

            ${activity ? `
                <div class="sia-airspace-section">
                    <div class="sia-airspace-section-title">ACTIVITÉ</div>
                    <div class="sia-airspace-extra-row">${formatSiaAirspaceRemark(activity)}</div>
                </div>
            ` : ''}

            ${identifier && identifier !== code ? `
                <div class="sia-airspace-section">
                    <div class="sia-airspace-section-title">IDENTIFIANT</div>
                    <div class="sia-airspace-extra-row">${escapeHtml(identifier)}</div>
                </div>
            ` : ''}

            ${remark ? `
                <div class="sia-airspace-section">
                    <div class="sia-airspace-section-title">REMARQUES</div>
                    <div class="sia-airspace-extra-row sia-airspace-remark">${formatSiaAirspaceRemark(remark)}</div>
                </div>
            ` : ''}
        </div>
    `;
}

function getSiaAirspaceStyle(item) {
    const type = String(item?.t || '');
    const local = String(item?.l || '');

    let color = '#3559e0';
    let dashArray = null;
    let fillOpacity = 0;
    let weight = 2.2;
    let opacity = 0.95;

    if (isSiaFlightInformationSector(item)) {
        color = '#ffea00';
        weight = 3.2;
        opacity = 1;
        dashArray = null;
        fillOpacity = 0;
    }
    else if (type === 'P') color = '#d50000';
    else if (type === 'R') color = '#ff6d00';
    else if (type === 'D') color = '#e91e63';
    else if (type === 'TRA') { color = '#ff6d00'; dashArray = '7 5'; }
    else if (type === 'CTR') {
        color = '#0066ff';
        weight = Number(item?.co || 0) === 1 ? 1.7 : 2.4;
        opacity = Number(item?.co || 0) === 1 ? 0.65 : 1;
        fillOpacity = 0;

    }
    else if (type === 'TMA') color = '#673ab7';
    else if (type === 'CTA') color = '#3f51b5';
    else if (type === 'FIR' || type === 'UIR' || type === 'UIR-P' || type === 'UTA' || type === 'OCA') {
        color = '#455a64';
        dashArray = '9 6';
        fillOpacity = 0;
    } else if (type === 'SECTOR' || type === 'SECTOR-C' || type === 'RAS') {
        color = '#607d8b';
        dashArray = '6 5';
        fillOpacity = 0;
    } else if (type === 'D-OTHER') {
        color = '#8e24aa';
        dashArray = '5 4';
        if (local === 'PJE') color = '#d81b60';
        else if (local === 'AER') color = '#00897b';
        else if (local === 'VOL') color = '#3949ab';
        else if (local === 'SUR') color = '#6d4c41';
        else if (local === 'PRN') color = '#f4511e';
        else if (local === 'BAL') color = '#7b1fa2';
    }

    /*
     * v15.54 — sur le fond OACI, TOUS les espaces SIA restent actifs/tactiles
     * mais leur dessin normal est masqué. Seule la zone sélectionnée se colore.
     */
    if (isCurrentOfflineOaciMap()) {
        opacity = 0;
        fillOpacity = 0;
    }

    return {
        color,
        weight,
        opacity,
        fillColor: color,
        fillOpacity,
        dashArray,
        lineCap: 'round',
        lineJoin: 'round'
    };
}

function getSiaCtrOuterRings(geometry) {
    if (!geometry || !Array.isArray(geometry.coordinates)) return [];
    if (geometry.type === 'Polygon') {
        return geometry.coordinates.length ? [geometry.coordinates[0]] : [];
    }
    if (geometry.type === 'MultiPolygon') {
        return geometry.coordinates
            .map(polygon => Array.isArray(polygon) && polygon.length ? polygon[0] : null)
            .filter(Boolean);
    }
    return [];
}

function buildSiaCtrInsetSegmentsLatLngs(ring, geometry, insetPixels = 7) {
    if (!map || !geometry || !Array.isArray(ring) || ring.length < 3) return [];

    const raw = ring.slice();
    const first = raw[0];
    const last = raw[raw.length - 1];
    const isClosed = Array.isArray(first) && Array.isArray(last)
        && Number(first[0]) === Number(last[0])
        && Number(first[1]) === Number(last[1]);

    if (!isClosed && raw.length >= 3) raw.push(raw[0]);

    const segments = [];
    const preferredInset = Math.max(7, Number(insetPixels) || 7);
    const insetCandidates = [preferredInset, 6, 5, 4, 3, 2]
        .filter((value, index, values) => value > 0 && values.indexOf(value) === index)
        .sort((a, b) => b - a);
    const MAX_SUBDIVISION_DEPTH = 7;
    const MIN_SOURCE_PIECE_PX = 3;

    const isLayerPointInsideGeometry = point => {
        try {
            return siaGeometryContainsLatLng(geometry, map.layerPointToLatLng(point));
        } catch (_) {
            return false;
        }
    };

    const movePointToward = (from, to, distancePx) => {
        const dx = to.x - from.x;
        const dy = to.y - from.y;
        const length = Math.hypot(dx, dy);
        if (!Number.isFinite(length) || length <= 0 || distancePx <= 0) return from;
        const ratio = Math.min(1, distancePx / length);
        return L.point(
            from.x + dx * ratio,
            from.y + dy * ratio
        );
    };

    const findFirstInsideTowardMid = (endpoint, midpoint) => {
        if (isLayerPointInsideGeometry(endpoint)) return endpoint;
        if (!isLayerPointInsideGeometry(midpoint)) return null;

        let outside = endpoint;
        let inside = midpoint;
        for (let step = 0; step < 9; step += 1) {
            const candidate = L.point(
                (outside.x + inside.x) / 2,
                (outside.y + inside.y) / 2
            );
            if (isLayerPointInsideGeometry(candidate)) inside = candidate;
            else outside = candidate;
        }

        // 2 px suffisent : l'axe reste déjà décalé de 7 px pour un trait de 12 px.
        return movePointToward(inside, midpoint, 2);
    };

    const tryInsetPiece = (pa, pb, trimStart, trimEnd) => {
        const dx = pb.x - pa.x;
        const dy = pb.y - pa.y;
        const length = Math.hypot(dx, dy);
        if (!Number.isFinite(length) || length < 2) return null;

        const tx = dx / length;
        const ty = dy / length;
        const endpointTrim = Math.min(5, length * 0.16);
        const startTrim = trimStart ? endpointTrim : 0;
        const endTrim = trimEnd ? endpointTrim : 0;
        if (startTrim + endTrim >= length - 1) return null;

        const baseA = L.point(pa.x + tx * startTrim, pa.y + ty * startTrim);
        const baseB = L.point(pb.x - tx * endTrim, pb.y - ty * endTrim);
        const normals = [
            { x: -ty, y: tx },
            { x: ty, y: -tx }
        ];

        /*
         * v15.80 — 7 px reste la cible. Si la géométrie locale devient trop
         * étroite à un niveau de zoom donné, on rapproche progressivement l'axe
         * de la limite au lieu de faire disparaître toute la bande.
         */
        for (const inset of insetCandidates) {
            let best = null;
            for (const normal of normals) {
                const shiftedA = L.point(
                    baseA.x + normal.x * inset,
                    baseA.y + normal.y * inset
                );
                const shiftedB = L.point(
                    baseB.x + normal.x * inset,
                    baseB.y + normal.y * inset
                );
                const shiftedMid = L.point(
                    (shiftedA.x + shiftedB.x) / 2,
                    (shiftedA.y + shiftedB.y) / 2
                );

                if (!isLayerPointInsideGeometry(shiftedMid)) continue;

                const safeA = findFirstInsideTowardMid(shiftedA, shiftedMid);
                const safeB = findFirstInsideTowardMid(shiftedB, shiftedMid);
                if (!safeA || !safeB) continue;

                const safeLength = Math.hypot(safeB.x - safeA.x, safeB.y - safeA.y);
                if (!Number.isFinite(safeLength) || safeLength < 2) continue;

                const testRatios = safeLength < 12 ? [0.35, 0.50, 0.65] : [0.20, 0.35, 0.50, 0.65, 0.80];
                const allInside = testRatios.every(ratio => isLayerPointInsideGeometry(L.point(
                    safeA.x + (safeB.x - safeA.x) * ratio,
                    safeA.y + (safeB.y - safeA.y) * ratio
                )));
                if (!allInside) continue;

                if (!best || safeLength > best.safeLength) {
                    best = { safeA, safeB, safeLength };
                }
            }
            if (best) return [best.safeA, best.safeB];
        }

        return null;
    };

    const buildPieceRecursively = (pa, pb, depth, trimStart, trimEnd) => {
        const direct = tryInsetPiece(pa, pb, trimStart, trimEnd);
        if (direct) return [direct];

        const length = Math.hypot(pb.x - pa.x, pb.y - pa.y);
        if (
            depth >= MAX_SUBDIVISION_DEPTH
            || !Number.isFinite(length)
            || length < MIN_SOURCE_PIECE_PX
        ) {
            return [];
        }

        /*
         * v15.80 — subdivision de dernier recours. Les petites portions ne sont
         * plus abandonnées au seuil fixe de 10 px de v15.79 ; le décalage local
         * adaptatif est essayé avant chaque nouvelle subdivision.
         */
        const midpoint = L.point((pa.x + pb.x) / 2, (pa.y + pb.y) / 2);
        return [
            ...buildPieceRecursively(pa, midpoint, depth + 1, trimStart, false),
            ...buildPieceRecursively(midpoint, pb, depth + 1, false, trimEnd)
        ];
    };

    for (let i = 1; i < raw.length; i += 1) {
        const a = raw[i - 1];
        const b = raw[i];
        if (!Array.isArray(a) || !Array.isArray(b) || a.length < 2 || b.length < 2) continue;

        const pa = map.latLngToLayerPoint(L.latLng(Number(a[1]), Number(a[0])));
        const pb = map.latLngToLayerPoint(L.latLng(Number(b[1]), Number(b[0])));
        const pieces = buildPieceRecursively(pa, pb, 0, true, true);

        pieces.forEach(piece => {
            if (!Array.isArray(piece) || piece.length !== 2) return;
            segments.push([
                map.layerPointToLatLng(piece[0]),
                map.layerPointToLatLng(piece[1])
            ]);
        });
    }

    return segments;
}

function addSiaCtrInnerBand(geometry, color = '#0066ff') {
    if (!siaLayerGroup || !geometry || isCurrentOfflineOaciMap()) return [];
    const createdLayers = [];
    const rings = getSiaCtrOuterRings(geometry);
    rings.forEach(ring => {
        const segments = buildSiaCtrInsetSegmentsLatLngs(ring, geometry, 7);
        if (!segments.length) return;

        const layer = L.polyline(segments, {
            pane: 'siaAirspacePane',
            renderer: siaAirspaceRenderer,
            color,
            weight: 12,
            opacity: 0.22,
            lineCap: 'round',
            lineJoin: 'round',
            interactive: false
        }).addTo(siaLayerGroup);
        createdLayers.push(layer);
    });
    return createdLayers;
}

function normalizeSiaBoundaryLabelAngle(angleDeg) {
    let angle = Number(angleDeg) || 0;
    while (angle > 180) angle -= 360;
    while (angle < -180) angle += 360;
    if (angle > 90) angle -= 180;
    if (angle < -90) angle += 180;
    return angle;
}

function getSiaBoundaryLabelPriority(item) {
    const type = String(item?.t || '').trim().toUpperCase();
    if (type === 'CTR') return 10;
    if (type === 'R' || type === 'P' || type === 'D') return 20;
    if (type === 'TRA') return 25;
    if (type === 'TMA') return 30;
    if (type === 'CTA') return 40;
    if (isSiaFlightInformationSector(item)) return 45;
    if (type === 'D-OTHER') return 50;
    return 60;
}

function getSiaBoundaryLabelMinimumSegmentPx(item) {
    const priority = getSiaBoundaryLabelPriority(item);
    if (priority <= 10) return 34; // CTR : priorité maximale, notamment SALON.
    if (priority <= 20) return 38; // R / P / D.
    if (priority <= 30) return 44;
    return 50;
}

/*
 * v15.68 — les zones P petites/circulaires ne doivent pas dépendre de la longueur
 * d'un segment issu de la discrétisation du contour. On construit plusieurs points
 * intérieurs autour du centroïde/barycentre écran et on les essaie avant les
 * placements le long des segments. Le texte reste horizontal.
 */
function buildSiaProhibitedInteriorLabelPlacements(geometry, bounds) {
    if (!map || !geometry) return [];
    const rings = getSiaCtrOuterRings(geometry);
    const placements = [];
    const seen = new Set();

    const polygonCentroid = points => {
        let twiceArea = 0;
        let cx = 0;
        let cy = 0;
        for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
            const a = points[j];
            const b = points[i];
            const cross = a.x * b.y - b.x * a.y;
            twiceArea += cross;
            cx += (a.x + b.x) * cross;
            cy += (a.y + b.y) * cross;
        }
        if (Math.abs(twiceArea) < 0.001) return null;
        return L.point(cx / (3 * twiceArea), cy / (3 * twiceArea));
    };

    rings.forEach(ring => {
        if (!Array.isArray(ring) || ring.length < 3) return;
        const points = ring.map(coord =>
            map.latLngToContainerPoint(L.latLng(Number(coord[1]), Number(coord[0])))
        ).filter(point => Number.isFinite(point.x) && Number.isFinite(point.y));
        if (points.length < 3) return;

        const xs = points.map(point => point.x);
        const ys = points.map(point => point.y);
        const bboxCenter = L.point((Math.min(...xs) + Math.max(...xs)) / 2, (Math.min(...ys) + Math.max(...ys)) / 2);
        const mean = L.point(
            points.reduce((sum, point) => sum + point.x, 0) / points.length,
            points.reduce((sum, point) => sum + point.y, 0) / points.length
        );
        const centroid = polygonCentroid(points);
        const bases = [centroid, bboxCenter, mean].filter(Boolean);
        const offsets = [
            [0, 0], [0, -18], [0, 18], [-24, 0], [24, 0],
            [-20, -16], [20, -16], [-20, 16], [20, 16],
            [0, -30], [0, 30], [-36, 0], [36, 0]
        ];

        bases.forEach((base, baseIndex) => {
            offsets.forEach((offset, offsetIndex) => {
                const point = L.point(base.x + offset[0], base.y + offset[1]);
                const key = `${Math.round(point.x / 3)}:${Math.round(point.y / 3)}`;
                if (seen.has(key)) return;
                const latlng = map.containerPointToLatLng(point);
                if (bounds && !bounds.contains(latlng)) return;
                if (!siaGeometryContainsLatLng(geometry, latlng)) return;
                seen.add(key);
                placements.push({
                    latlng,
                    point,
                    angle: 0,
                    lengthPx: 100000 - baseIndex * 1000 - offsetIndex,
                    insetPx: 0,
                    interior: true
                });
            });
        });
    });

    return placements;
}

function findSiaBoundaryLabelPlacements(item, geometry) {
    if (!map || !geometry) return [];

    const rings = getSiaCtrOuterRings(geometry);
    if (!rings.length) return [];

    const bounds = map.getBounds().pad(-0.01);
    const minimumLengthPx = getSiaBoundaryLabelMinimumSegmentPx(item);
    const placements = [];

    if (String(item?.t || '').trim().toUpperCase() === 'P') {
        placements.push(...buildSiaProhibitedInteriorLabelPlacements(geometry, bounds));
    }

    rings.forEach(ring => {
        if (!Array.isArray(ring) || ring.length < 2) return;

        for (let i = 1; i < ring.length; i += 1) {
            const a = ring[i - 1];
            const b = ring[i];
            if (!Array.isArray(a) || !Array.isArray(b) || a.length < 2 || b.length < 2) continue;

            const aLatLng = L.latLng(Number(a[1]), Number(a[0]));
            const bLatLng = L.latLng(Number(b[1]), Number(b[0]));
            const pa = map.latLngToContainerPoint(aLatLng);
            const pb = map.latLngToContainerPoint(bLatLng);
            const lengthPx = pa.distanceTo(pb);
            if (!Number.isFinite(lengthPx) || lengthPx < minimumLengthPx) continue;

            const midpoint = L.point((pa.x + pb.x) / 2, (pa.y + pb.y) / 2);
            const dx = pb.x - pa.x;
            const dy = pb.y - pa.y;
            const segmentLength = Math.hypot(dx, dy);
            if (!Number.isFinite(segmentLength) || segmentLength < 1) continue;

            const angle = normalizeSiaBoundaryLabelAngle(
                Math.atan2(dy, dx) * 180 / Math.PI
            );

            /*
             * Le texte ne doit plus être posé sur le trait plein.
             * On teste les deux normales au segment et plusieurs retraits.
             * Seul un point réellement contenu dans le polygone est retenu.
             */
            const normals = [
                { x: -dy / segmentLength, y: dx / segmentLength },
                { x: dy / segmentLength, y: -dx / segmentLength }
            ];
            const insetDistances = [22, 30, 38];
            let insidePlacement = null;

            for (const insetPx of insetDistances) {
                for (const normal of normals) {
                    const point = L.point(
                        midpoint.x + normal.x * insetPx,
                        midpoint.y + normal.y * insetPx
                    );
                    const latlng = map.containerPointToLatLng(point);
                    if (!bounds.contains(latlng)) continue;
                    if (!siaGeometryContainsLatLng(geometry, latlng)) continue;

                    insidePlacement = {
                        latlng,
                        point,
                        angle,
                        lengthPx,
                        insetPx
                    };
                    break;
                }
                if (insidePlacement) break;
            }

            if (insidePlacement) placements.push(insidePlacement);
        }
    });

    /*
     * Les segments les plus longs sont essayés d'abord. En cas de collision,
     * addSiaAirspaceBoundaryLabel() essaie les suivants au lieu d'abandonner.
     */
    placements.sort((a, b) => {
        if (!!a.interior !== !!b.interior) return a.interior ? -1 : 1;
        if (a.lengthPx !== b.lengthPx) return b.lengthPx - a.lengthPx;
        return b.insetPx - a.insetPx;
    });

    return placements;
}

function addSiaAirspaceBoundaryLabel(item, geometry, labelState) {
    if (!siaLayerGroup || !map || !item || !geometry) return null;
    if (isCurrentOfflineOaciMap()) return null;
    if (Number(item?.co || 0) === 1) return null;

    /* v15.81 — à partir de l'échelle 10 NM en dézoomant, conserver les zones
     * mais supprimer leurs noms/fréquences/altitudes pour alléger la carte. */
    if (getCurrentNpfScaleNm() >= 10) return null;

    const type = String(geometry.type || '');
    if (type !== 'Polygon' && type !== 'MultiPolygon') return null;

    const state = labelState || { points: [], count: 0 };
    if (state.count >= 70) return null;

    const text = getSiaAirspaceBoundaryLabelText(item);
    if (!text) return null;
    const frequencyText = getSiaAirspaceBoundaryFrequencyText(item);
    const verticalText = getSiaAirspaceBoundaryVerticalText(item);

    const placements = findSiaBoundaryLabelPlacements(item, geometry);
    if (!placements.length) return null;

    const priority = getSiaBoundaryLabelPriority(item);
    const nearFiveNm = getCurrentNpfScaleNm() <= 5.000001;
    const isSiv = isSiaFlightInformationSector(item);
    const collisionDistance = (priority <= 20 ? 92 : 105) + (nearFiveNm ? 18 : 0) + (isSiv ? 12 : 0);
    const placement = placements.find(candidate =>
        !state.points.some(point => point.distanceTo(candidate.point) < collisionDistance)
    );
    if (!placement) return null;

    const marker = L.marker(placement.latlng, {
        pane: 'siaAirspacePane',
        interactive: false,
        keyboard: false,
        icon: L.divIcon({
            className: 'sia-boundary-label-icon',
            html: `<div class="sia-boundary-label-text${String(item?.t || '').trim().toUpperCase() === 'P' ? ' sia-prohibited-label' : ''}${isSiv ? ' sia-siv-label' : ''}${nearFiveNm ? ' sia-zone-label-near' : ''}" style="transform:translate(-50%,-50%) rotate(${placement.angle.toFixed(1)}deg)"><div class="sia-boundary-label-main">${escapeHtml(text)}</div>${frequencyText ? `<div class="sia-boundary-label-frequency">${escapeHtml(frequencyText)}</div>` : ''}${verticalText ? `<div class="sia-boundary-label-altitude">${escapeHtml(verticalText)}</div>` : ''}</div>`,
            iconSize: [1, 1],
            iconAnchor: [0, 0]
        })
    });

    marker.addTo(siaLayerGroup);
    state.points.push(placement.point);
    state.count += 1;
    return marker;
}

function getCurrentNpfScaleNm() {
    if (!map || !map.getSize || !map.containerPointToLatLng || !map.distance) return Infinity;
    const size = map.getSize();
    if (!size || !size.x || !size.y) return Infinity;

    const samplePixels = Math.min(160, Math.max(80, Math.floor(size.x * 0.16)));
    const y = Math.max(10, Math.floor(size.y / 2));
    const x1 = Math.max(5, Math.floor((size.x - samplePixels) / 2));
    const x2 = x1 + samplePixels;

    const ll1 = map.containerPointToLatLng(L.point(x1, y));
    const ll2 = map.containerPointToLatLng(L.point(x2, y));
    const meters = map.distance(ll1, ll2);
    const metersPerPixel = meters / samplePixels;
    if (!Number.isFinite(metersPerPixel) || metersPerPixel <= 0) return Infinity;

    return chooseNiceNauticalScale((metersPerPixel * 110) / 1852);
}

function shouldDisplaySiaDesignatedPoints() {
    return getCurrentNpfScaleNm() <= 5.000001;
}

function getSiaCtrSelectionKey(item) {
    return [
        String(item?.t || ''),
        String(item?.l || ''),
        String(item?.c || ''),
        String(item?.n || ''),
        JSON.stringify(item?.lo || null),
        JSON.stringify(item?.up || null)
    ].join('|');
}

function getSiaAirspaceSelectionColor(item) {
    try {
        return String(getSiaAirspaceStyle(item)?.color || '#0066ff');
    } catch (_) {
        return '#0066ff';
    }
}

function ensureSiaSelectionLayer() {
    if (!map) return null;
    ensureSiaMapPanes();

    if (!siaSelectionLayer) {
        siaSelectionLayer = L.layerGroup().addTo(map);
    }
    return siaSelectionLayer;
}

function clearSiaSelectionHighlight() {
    if (siaSelectionLayer) {
        try { siaSelectionLayer.clearLayers(); } catch (_) {}
    }
}

function drawSiaSelectionHighlight(item, geometry) {
    if (!map || !item || !geometry) return;

    const targetLayer = ensureSiaSelectionLayer();
    if (!targetLayer) return;

    clearSiaSelectionHighlight();

    const selectionColor = getSiaAirspaceSelectionColor(item);
    const feature = {
        type: 'Feature',
        properties: {},
        geometry
    };

    const highlight = L.geoJSON(feature, {
        pane: 'siaSelectionPane',
        renderer: siaSelectionRenderer || undefined,
        interactive: false,
        style: {
            color: selectionColor,
            weight: 2.6,
            opacity: 1,
            fillColor: selectionColor,
            fillOpacity: 0.30,
            lineCap: 'round',
            lineJoin: 'round',
            interactive: false
        },
        pointToLayer: (_feature, latlng) => L.circleMarker(latlng, {
            pane: 'siaSelectionPane',
            renderer: siaSelectionRenderer || undefined,
            radius: 11,
            color: selectionColor,
            weight: 3,
            opacity: 1,
            fillColor: selectionColor,
            fillOpacity: 0.30,
            interactive: false
        })
    });

    highlight.addTo(targetLayer);
}

function resetSelectedSiaCtrTouchLayer(clearKey = true) {
    clearSiaSelectionHighlight();
    siaSelectedCtrTouchLayer = null;
    siaSelectedAirspaceItem = null;
    siaSelectedAirspaceGeometry = null;
    if (clearKey) siaSelectedCtrKey = null;
}

function selectSiaCtrTouchLayer(layer, item, latlng, geometry = null, options = {}) {
    if (!map || !item) return;

    const selectionKey = getSiaCtrSelectionKey(item);

    if (siaSelectedCtrKey && siaSelectedCtrKey !== selectionKey) {
        resetSelectedSiaCtrTouchLayer(false);
    }

    /*
     * v15.59 — la coloration ne dépend plus de la couche tactile.
     * Une popup Leaflet avec autoPan peut déclencher moveend puis reconstruire
     * les couches SIA. La géométrie sélectionnée est donc surlignée dans une
     * couche indépendante qui survit au rafraîchissement.
     */
    let selectedGeometry = geometry;
    if (!selectedGeometry) {
        const currentEntry = siaAirspaceTouchEntries.find(entry =>
            entry?.layer === layer
            || getSiaCtrSelectionKey(entry?.item) === selectionKey
        );
        selectedGeometry = currentEntry?.geometry || null;
        if (currentEntry?.layer) layer = currentEntry.layer;
    }

    siaSelectedCtrTouchLayer = layer || null;
    siaSelectedCtrKey = selectionKey;
    siaSelectedAirspaceItem = item;
    siaSelectedAirspaceGeometry = selectedGeometry;

    if (selectedGeometry) {
        drawSiaSelectionHighlight(item, selectedGeometry);
    }

    const popupLatLng = latlng;
    if (!popupLatLng) return;

    const choiceOrigin = options?.choiceOrigin
        ? L.latLng(Number(options.choiceOrigin.lat), Number(options.choiceOrigin.lng))
        : null;

    let popupContent = buildSiaAirspacePopup(item);
    if (choiceOrigin && Number.isFinite(choiceOrigin.lat) && Number.isFinite(choiceOrigin.lng)) {
        const wrapper = document.createElement('div');
        wrapper.className = 'sia-airspace-detail-with-return';

        const backButton = document.createElement('button');
        backButton.type = 'button';
        backButton.className = 'sia-airspace-choice-return';
        backButton.textContent = '← RETOUR';
        backButton.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();

            resetSelectedSiaCtrTouchLayer(true);
            try { map.closePopup(popup); } catch (_) {}

            setTimeout(() => {
                const freshCandidates = getSiaAirspaceTouchCandidates(choiceOrigin);
                const returnCandidates = freshCandidates.length
                    ? freshCandidates
                    : (Array.isArray(options?.choiceCandidates) ? options.choiceCandidates : []);
                if (returnCandidates.length) {
                    openSiaAirspaceChoicePopup(choiceOrigin, returnCandidates);
                }
            }, 0);
        });

        const details = document.createElement('div');
        details.innerHTML = popupContent;
        wrapper.appendChild(backButton);
        wrapper.appendChild(details);
        popupContent = wrapper;
    }

    const popup = L.popup({
        maxWidth: 400,
        /*
         * v15.77 — en Suivi, la position/trajectoire de l'avion est prioritaire.
         * La popup reste ancrée à la zone et peut sortir de l'écran ; Leaflet ne
         * déplace plus la carte en sens inverse pour la garder visible.
         */
        autoPan: !centerGpsFollowActive,
        keepInView: !centerGpsFollowActive,
        className: 'sia-airspace-dialog-popup sia-airspace-detail-popup'
    })
        .setLatLng(popupLatLng)
        .setContent(popupContent)
        .openOn(map);

    const onPopupClose = event => {
        if (event?.popup !== popup) return;
        map.off('popupclose', onPopupClose);

        /*
         * La couche tactile a pu être reconstruite pendant l'autoPan.
         * On compare donc la clé métier, pas la référence Leaflet du layer.
         */
        if (siaSelectedCtrKey === selectionKey) {
            resetSelectedSiaCtrTouchLayer(true);
        }
    };
    map.on('popupclose', onPopupClose);
}

function siaPointInRing(lng, lat, ring) {
    if (!Array.isArray(ring) || ring.length < 3) return false;
    let inside = false;

    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const a = ring[i];
        const b = ring[j];
        if (!Array.isArray(a) || !Array.isArray(b) || a.length < 2 || b.length < 2) continue;

        const xi = Number(a[0]);
        const yi = Number(a[1]);
        const xj = Number(b[0]);
        const yj = Number(b[1]);
        if (![xi, yi, xj, yj].every(Number.isFinite)) continue;

        const intersects = ((yi > lat) !== (yj > lat))
            && (lng < (xj - xi) * (lat - yi) / ((yj - yi) || 1e-12) + xi);
        if (intersects) inside = !inside;
    }

    return inside;
}

function siaPointInPolygonCoordinates(lng, lat, polygonCoordinates) {
    if (!Array.isArray(polygonCoordinates) || !polygonCoordinates.length) return false;
    if (!siaPointInRing(lng, lat, polygonCoordinates[0])) return false;

    // Trous éventuels du polygone.
    for (let i = 1; i < polygonCoordinates.length; i += 1) {
        if (siaPointInRing(lng, lat, polygonCoordinates[i])) return false;
    }
    return true;
}

function siaDistancePointToSegmentPx(point, a, b) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    if (!Number.isFinite(dx) || !Number.isFinite(dy)) return Infinity;

    const lengthSq = dx * dx + dy * dy;
    if (lengthSq <= 1e-9) return point.distanceTo(a);

    let t = ((point.x - a.x) * dx + (point.y - a.y) * dy) / lengthSq;
    t = Math.max(0, Math.min(1, t));

    return point.distanceTo(L.point(
        a.x + t * dx,
        a.y + t * dy
    ));
}

function siaPointGeometryDistancePx(latlng, coordinate) {
    if (!map || !latlng || !Array.isArray(coordinate) || coordinate.length < 2) return Infinity;
    const lng = Number(coordinate[0]);
    const lat = Number(coordinate[1]);
    if (!Number.isFinite(lng) || !Number.isFinite(lat)) return Infinity;

    const a = map.latLngToLayerPoint(latlng);
    const b = map.latLngToLayerPoint(L.latLng(lat, lng));
    return a.distanceTo(b);
}

function siaLineGeometryDistancePx(latlng, coordinates) {
    if (!map || !latlng || !Array.isArray(coordinates) || coordinates.length < 2) return Infinity;

    const point = map.latLngToLayerPoint(latlng);
    let best = Infinity;

    for (let i = 1; i < coordinates.length; i += 1) {
        const c1 = coordinates[i - 1];
        const c2 = coordinates[i];
        if (!Array.isArray(c1) || !Array.isArray(c2) || c1.length < 2 || c2.length < 2) continue;

        const a = map.latLngToLayerPoint(L.latLng(Number(c1[1]), Number(c1[0])));
        const b = map.latLngToLayerPoint(L.latLng(Number(c2[1]), Number(c2[0])));
        best = Math.min(best, siaDistancePointToSegmentPx(point, a, b));
    }

    return best;
}

function siaGeometryContainsLatLng(geometry, latlng) {
    if (!geometry || !latlng) return false;
    const lng = Number(latlng.lng);
    const lat = Number(latlng.lat);
    if (!Number.isFinite(lng) || !Number.isFinite(lat)) return false;

    if (geometry.type === 'Polygon') {
        return siaPointInPolygonCoordinates(lng, lat, geometry.coordinates);
    }

    if (geometry.type === 'MultiPolygon') {
        return (geometry.coordinates || []).some(poly =>
            siaPointInPolygonCoordinates(lng, lat, poly)
        );
    }

    /*
     * v15.59 — une grande partie des D-OTHER SIA (AER, VOL, SUR, PJE,
     * PRN, TRVL, TRPLA, AP, BAL...) est publiée comme un point AIXM.
     * La sélection est donc faite avec une tolérance tactile en pixels.
     */
    if (geometry.type === 'Point') {
        return siaPointGeometryDistancePx(latlng, geometry.coordinates) <= 30;
    }

    if (geometry.type === 'MultiPoint') {
        return (geometry.coordinates || []).some(coord =>
            siaPointGeometryDistancePx(latlng, coord) <= 30
        );
    }

    // Prévu également pour d'éventuelles géométries linéaires futures.
    if (geometry.type === 'LineString') {
        return siaLineGeometryDistancePx(latlng, geometry.coordinates) <= 18;
    }

    if (geometry.type === 'MultiLineString') {
        return (geometry.coordinates || []).some(line =>
            siaLineGeometryDistancePx(latlng, line) <= 18
        );
    }

    return false;
}

function getSiaAirspaceChoicePriority(item) {
    /* v15.81 — Sélection Zone : les SIV sont toujours présentés en premier. */
    if (isSiaFlightInformationSector(item)) return 0;

    const type = String(item?.t || '').toUpperCase();
    if (type === 'CTR') return 10;
    if (type === 'P' || type === 'R' || type === 'D' || type === 'TRA') return 20;
    if (type === 'TMA') return 30;
    if (type === 'CTA') return 40;
    if (type === 'D-OTHER') return 50;
    if (type === 'RAS' || type === 'SECTOR' || type === 'SECTOR-C') return 60;
    if (type === 'OCA' || type === 'UTA') return 70;
    if (type === 'FIR' || type === 'UIR' || type === 'UIR-P') return 80;
    return 90;
}

function getSiaAlwaysSelectableSivCandidates(latlng, existingEntries = []) {
    const dataset = siaDataset;
    if (!dataset || !Array.isArray(dataset.airspaces) || !latlng) return [];

    const lat = Number(latlng.lat);
    const lng = Number(latlng.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return [];

    const existingKeys = new Set(
        (Array.isArray(existingEntries) ? existingEntries : [])
            .map(entry => getSiaCtrSelectionKey(entry?.item))
            .filter(Boolean)
    );

    const matches = [];
    for (const item of dataset.airspaces) {
        if (!isSiaFlightInformationSector(item)) continue;
        if (isSiaTechnicalSivParent(item, dataset)) continue;
        if (!item?.g) continue;

        const bounds = Array.isArray(item?.b) ? item.b : null;
        if (bounds && bounds.length >= 4) {
            const minLng = Number(bounds[0]);
            const minLat = Number(bounds[1]);
            const maxLng = Number(bounds[2]);
            const maxLat = Number(bounds[3]);
            if ([minLng, minLat, maxLng, maxLat].every(Number.isFinite)) {
                if (lng < minLng || lng > maxLng || lat < minLat || lat > maxLat) continue;
            }
        }

        const key = getSiaCtrSelectionKey(item);
        if (key && existingKeys.has(key)) continue;

        const geometry = getSiaCachedGeometry(item);
        if (!geometry || !siaGeometryContainsLatLng(geometry, latlng)) continue;

        matches.push({
            item,
            geometry,
            layer: null,
            hiddenSivCandidate: !isSiaFilterEnabled('ase:SIV')
        });
        if (key) existingKeys.add(key);
    }

    return matches;
}

function getSiaHiddenFilteredAirspaceCandidates(latlng, existingEntries = []) {
    if (siaMapAirspacesVisible) return [];
    const dataset = siaDataset;
    if (!dataset || !Array.isArray(dataset.airspaces) || !latlng) return [];

    const lat = Number(latlng.lat);
    const lng = Number(latlng.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return [];

    const operationalFamilies = buildSiaTmaOperationalFamilySet(dataset);
    const existingKeys = new Set(
        (Array.isArray(existingEntries) ? existingEntries : [])
            .map(entry => getSiaCtrSelectionKey(entry?.item))
            .filter(Boolean)
    );
    const matches = [];

    for (const item of dataset.airspaces) {
        if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
        if (shouldHideSiaAirspaceAboveFl115(item)) continue;
        if (isSiaTechnicalTmaUnionParent(item)) continue;
        if (isSiaTechnicalSivParent(item, dataset)) continue;
        if (isSiaGenericTmaWithoutAltitude(item, operationalFamilies)) continue;
        if (!item?.g) continue;

        const bounds = Array.isArray(item?.b) ? item.b : null;
        if (bounds && bounds.length >= 4) {
            const minLng = Number(bounds[0]);
            const minLat = Number(bounds[1]);
            const maxLng = Number(bounds[2]);
            const maxLat = Number(bounds[3]);
            if ([minLng, minLat, maxLng, maxLat].every(Number.isFinite)) {
                if (lng < minLng || lng > maxLng || lat < minLat || lat > maxLat) continue;
            }
        }

        const key = getSiaCtrSelectionKey(item);
        if (key && existingKeys.has(key)) continue;
        const geometry = getSiaCachedGeometry(item);
        if (!geometry || !siaGeometryContainsLatLng(geometry, latlng)) continue;

        matches.push({ item, geometry, layer: null, hiddenMapCandidate: true });
        if (key) existingKeys.add(key);
    }

    return matches;
}

function getSiaAirspaceTouchCandidates(latlng) {
    const operationalFamilies = buildSiaTmaOperationalFamilySet(siaDataset);

    const visibleCandidates = siaAirspaceTouchEntries
        .filter(entry => !isSiaTechnicalTmaUnionParent(entry.item))
        .filter(entry => !isSiaTechnicalSivParent(entry.item, siaDataset))
        .filter(entry => !isSiaGenericTmaWithoutAltitude(entry.item, operationalFamilies))
        .filter(entry => siaGeometryContainsLatLng(entry.geometry, latlng));

    const hiddenFilteredCandidates = getSiaHiddenFilteredAirspaceCandidates(latlng, visibleCandidates);
    const candidates = visibleCandidates
        .concat(hiddenFilteredCandidates)
        .concat(getSiaAlwaysSelectableSivCandidates(latlng, visibleCandidates.concat(hiddenFilteredCandidates)));

    return candidates.sort((a, b) => {
        const pa = getSiaAirspaceChoicePriority(a.item);
        const pb = getSiaAirspaceChoicePriority(b.item);
        if (pa !== pb) return pa - pb;

        const aa = Array.isArray(a.item?.b) && a.item.b.length >= 4
            ? Math.abs((Number(a.item.b[2]) - Number(a.item.b[0])) * (Number(a.item.b[3]) - Number(a.item.b[1])))
            : Infinity;
        const ab = Array.isArray(b.item?.b) && b.item.b.length >= 4
            ? Math.abs((Number(b.item.b[2]) - Number(b.item.b[0])) * (Number(b.item.b[3]) - Number(b.item.b[1])))
            : Infinity;
        return aa - ab;
    });
}

function getSiaAirspaceChoiceLabel(item) {
    return getSiaAirspaceDisplayTitle(item);
}

function getSiaAirspaceChoiceVerticalLabel(item) {
    const hasLower = hasSiaVerticalValue(item?.lo);
    const hasUpper = hasSiaVerticalValue(item?.up);
    if (!hasLower && !hasUpper) return '';

    const lower = hasLower ? formatSiaVertical(item.lo) : '—';
    const upper = hasUpper ? formatSiaVertical(item.up) : '—';
    return `${lower} / ${upper}`;
}

function openSiaAirspaceChoicePopup(latlng, candidates) {
    if (!map || !latlng || !Array.isArray(candidates) || !candidates.length) return;

    const container = document.createElement('div');
    container.className = 'sia-airspace-choice';

    const title = document.createElement('div');
    title.className = 'sia-airspace-choice-title';
    title.textContent = 'ESPACES À CET ENDROIT';
    container.appendChild(title);

    const list = document.createElement('div');
    list.className = 'sia-airspace-choice-list';

    candidates.forEach(entry => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'sia-airspace-choice-button';

        const nameLine = document.createElement('div');
        nameLine.className = 'sia-airspace-choice-name';
        nameLine.textContent = getSiaAirspaceChoiceLabel(entry.item);
        button.appendChild(nameLine);

        const verticalLabel = getSiaAirspaceChoiceVerticalLabel(entry.item);
        if (verticalLabel) {
            const verticalLine = document.createElement('div');
            verticalLine.className = 'sia-airspace-choice-vertical';
            verticalLine.textContent = verticalLabel;
            button.appendChild(verticalLine);
        }

        button.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            try { map.closePopup(); } catch (_) {}
            selectSiaCtrTouchLayer(
                entry.layer,
                entry.item,
                latlng,
                entry.geometry,
                { choiceOrigin: latlng, choiceCandidates: candidates }
            );
        });

        list.appendChild(button);
    });

    container.appendChild(list);

    L.popup({
        maxWidth: 390,
        closeButton: true,
        autoPan: !centerGpsFollowActive,
        keepInView: !centerGpsFollowActive,
        className: 'sia-airspace-dialog-popup sia-airspace-choice-popup'
    })
        .setLatLng(latlng)
        .setContent(container)
        .openOn(map);
}

function handleSiaAirspaceTouch(latlng) {
    const candidates = getSiaAirspaceTouchCandidates(latlng);

    if (!candidates.length) return;
    if (candidates.length === 1) {
        selectSiaCtrTouchLayer(
            candidates[0].layer,
            candidates[0].item,
            latlng,
            candidates[0].geometry
        );
        return;
    }

    /*
     * Plusieurs zones se superposent : le z-index ne choisit jamais à la place
     * de l'utilisateur. On propose toutes les zones actives contenant le point.
     */
    openSiaAirspaceChoicePopup(latlng, candidates);
}

function addSiaCtrTouchSurface(feature) {
    if (!siaLayerGroup || !feature?.geometry || !feature?.properties?.siaItem) return null;
    const item = feature.properties.siaItem;
    const selectionColor = getSiaAirspaceSelectionColor(item);
    const geometryType = String(feature?.geometry?.type || '');
    const isDirectDotherPoint = String(item?.t || '').trim().toUpperCase() === 'D-OTHER'
        && (geometryType === 'Point' || geometryType === 'MultiPoint');

    /*
     * v15.75 — optimisation iPad majeure : les volumes surfaciques ne créent
     * plus chacun un second GeoJSON invisible de 30 px uniquement pour le toucher.
     * Leur géométrie est conservée ici et testée à la demande lors de
     * « Sélection Zone ». Les D-OTHER ponctuels gardent seuls une hitbox afin
     * de conserver leur ouverture par appui court.
     */
    if (!isDirectDotherPoint) {
        siaAirspaceTouchEntries.push({
            item,
            geometry: feature.geometry,
            layer: null
        });
        return null;
    }

    const neutralizeShortClick = event => {
        /*
         * v15.75 — en mode CRÉER/MODIFIER GAAR, les grandes surfaces tactiles
         * SIA couvrent souvent toute la carte. Elles transfèrent alors le clic
         * au créateur GAAR au lieu de l'absorber.
         */
        if (isDrawingMode && event?.latlng) {
            handleGaarMapClick(event, { fromSiaSurface: true }).catch(() => {});
        }
        try {
            if (event?.originalEvent) {
                L.DomEvent.stopPropagation(event.originalEvent);
                L.DomEvent.preventDefault(event.originalEvent);
            }
        } catch (_) {}
    };

    const touchGeoJson = L.geoJSON(feature, {
        pane: 'siaCtrTouchPane',
        renderer: siaCtrTouchRenderer || undefined,

        /*
         * v15.59 — important pour les D-OTHER ponctuels :
         * sans pointToLayer, Leaflet crée son Marker PNG par défaut. Dans la
         * PWA, l'icône peut être absente et apparaître sous forme de « ? ».
         * On utilise maintenant un cercle SVG tactile quasi invisible.
         */
        pointToLayer: (_feature, latlng) => L.circleMarker(latlng, {
            pane: 'siaCtrTouchPane',
            renderer: siaCtrTouchRenderer || undefined,
            radius: 30,
            stroke: false,
            color: selectionColor,
            opacity: 0,
            fill: true,
            fillColor: selectionColor,
            fillOpacity: 0.002,
            interactive: true,
            bubblingMouseEvents: false,
            keyboard: false,
            className: 'sia-airspace-touch-surface'
        }),

        style: geoFeature => {
            const geometryType = String(geoFeature?.geometry?.type || '');

            if (geometryType === 'LineString' || geometryType === 'MultiLineString') {
                return {
                    color: selectionColor,
                    weight: 30,
                    opacity: 0.002,
                    fillOpacity: 0,
                    interactive: true,
                    className: 'sia-airspace-touch-surface'
                };
            }

            return {
                color: 'transparent',
                weight: 0,
                opacity: 0,
                fillColor: selectionColor,
                fillOpacity: 0.001,
                interactive: true,
                className: 'sia-airspace-touch-surface'
            };
        },

        onEachFeature: (geoFeature, layer) => {
            const geometryType = String(geoFeature?.geometry?.type || '');
            const isDirectDotherPoint = String(item?.t || '').trim().toUpperCase() === 'D-OTHER'
                && (geometryType === 'Point' || geometryType === 'MultiPoint');

            if (isDirectDotherPoint) {
                /*
                 * v15.69 — les activités D-OTHER ponctuelles sont de vrais
                 * symboles opérationnels : un appui court ouvre directement leur
                 * fiche. L'appui long carte reste disponible pour les volumes.
                 */
                layer.on('click', event => {
                    if (isDrawingMode && event?.latlng) {
                        handleGaarMapClick(event, { fromSiaSurface: true }).catch(() => {});
                        try {
                            if (event?.originalEvent) {
                                L.DomEvent.stopPropagation(event.originalEvent);
                                L.DomEvent.preventDefault(event.originalEvent);
                            }
                        } catch (_) {}
                        return;
                    }
                    try {
                        if (event?.originalEvent) {
                            L.DomEvent.stopPropagation(event.originalEvent);
                            L.DomEvent.preventDefault(event.originalEvent);
                        }
                    } catch (_) {}

                    const popupPoint = event?.latlng
                        || (geometryType === 'Point'
                            ? L.latLng(Number(geoFeature.geometry.coordinates[1]), Number(geoFeature.geometry.coordinates[0]))
                            : null);
                    if (!popupPoint) return;
                    selectSiaCtrTouchLayer(
                        touchGeoJson,
                        item,
                        popupPoint,
                        feature.geometry,
                        { directPoint: true }
                    );
                });
            } else {
                /*
                 * Les volumes restent sélectionnés par appui long puis
                 * « Sélection Zone » afin de gérer correctement les superpositions.
                 */
                layer.on('click', neutralizeShortClick);
            }
        }
    });

    touchGeoJson.addTo(siaLayerGroup);
    siaAirspaceTouchEntries.push({
        item,
        geometry: feature.geometry,
        layer: touchGeoJson
    });

    return touchGeoJson;
}

function clearSiaZoomDependentLayers() {
    if (!siaLayerGroup || !Array.isArray(siaZoomDependentLayers)) {
        siaZoomDependentLayers = [];
        return;
    }
    siaZoomDependentLayers.forEach(layer => {
        try { siaLayerGroup.removeLayer(layer); } catch (_) {}
    });
    siaZoomDependentLayers = [];
}

function getSiaDecorationFeaturesForCurrentView(features) {
    if (!map || !Array.isArray(features) || !features.length) return [];
    let viewportBounds = null;
    try {
        /* Petit débord seulement : ne pas décorer tout le tampon de rendu. */
        viewportBounds = map.getBounds().pad(SIA_DECORATION_VIEW_PAD_RATIO);
    } catch (_) {
        viewportBounds = map.getBounds?.() || null;
    }
    if (!viewportBounds) return features;

    return features.filter(feature => {
        const item = feature?.properties?.siaItem;
        if (!item) return false;
        return siaBoundsIntersects(item.b, viewportBounds);
    });
}

function renderSiaZoomDependentDecorations(features) {
    const npfDiagStartedAt = NPF_STARTUP_DIAGNOSTIC.now();
    clearSiaZoomDependentLayers();
    if (!siaMapAirspacesVisible || !Array.isArray(features) || !features.length) return;

    /*
     * v16.33 — à grande échelle, les contours principaux suffisent. Les bandes
     * intérieures et libellés impliquent des centaines de conversions écran et
     * n'apportent pas d'information supplémentaire lorsque l'échelle est >= 10 NM.
     * Les zones, leurs contours et la sélection restent intégralement disponibles.
     */
    const scaleNm = getCurrentNpfScaleNm();
    const combinedHeavyDecorationLoad = !!(siaMapAirspacesVisible && showRoadOverlayLayer && showHighVoltageLinesLayer);
    const combinedHeavyLightweight = combinedHeavyDecorationLoad && Number.isFinite(scaleNm) && scaleNm >= 5;
    if (scaleNm >= SIA_DECORATION_LIGHTWEIGHT_SCALE_NM || combinedHeavyLightweight) {
        npfDiagSiaInteraction(
            'SIA DÉCORATIONS',
            `zones=0/${features.length} · labels=0 · zoom=${map?.getZoom?.() ?? '—'} · allégées=oui · charge-combinée=${combinedHeavyLightweight ? 'oui' : 'non'} · echelle=${Number.isFinite(scaleNm) ? scaleNm.toFixed(1) : '—'}NM`,
            { dureeMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - npfDiagStartedAt) }
        );
        return;
    }

    /*
     * Les volumes sont chargés avec un tampon pour éviter les reconstructions
     * permanentes. En revanche, bandes intérieures et libellés ne sont utiles
     * qu'autour de la vue courante : ne pas les créer pour toutes les zones du tampon.
     */
    const decorationFeatures = getSiaDecorationFeaturesForCurrentView(features);
    const labelState = { points: [], count: 0 };
    decorationFeatures.forEach(feature => {
        const item = feature?.properties?.siaItem;
        if (!item || Number(item?.co || 0) === 1) return;
        const itemStyle = getSiaAirspaceStyle(item);
        const layers = addSiaCtrInnerBand(feature.geometry, itemStyle.color);
        if (Array.isArray(layers)) siaZoomDependentLayers.push(...layers);
    });

    decorationFeatures
        .filter(feature => Number(feature?.properties?.siaItem?.co || 0) !== 1)
        .sort((a, b) =>
            getSiaBoundaryLabelPriority(a.properties.siaItem)
            - getSiaBoundaryLabelPriority(b.properties.siaItem)
        )
        .forEach(feature => {
            const marker = addSiaAirspaceBoundaryLabel(
                feature.properties.siaItem,
                feature.geometry,
                labelState
            );
            if (marker) siaZoomDependentLayers.push(marker);
        });

    npfDiagSiaInteraction(
        'SIA DÉCORATIONS',
        `zones=${decorationFeatures.length}/${features.length} · labels=${labelState.count} · zoom=${map?.getZoom?.() ?? '—'}`,
        { dureeMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - npfDiagStartedAt) }
    );
}

async function renderSiaZoomDependentDecorationsProgressive(features, refreshGeneration) {
    const npfDiagStartedAt = NPF_STARTUP_DIAGNOSTIC.now();
    const runId = ++siaDecorationProgressiveRun;
    clearSiaZoomDependentLayers();
    if (!siaMapAirspacesVisible || !Array.isArray(features) || !features.length) return;

    /*
     * v16.33 — mode allégé à grande échelle. Le GeoJSON principal reste visible
     * et sélectionnable ; seules les décorations dépendantes des pixels écran
     * (bandes intérieures / libellés) sont omises. Cela évite les blocs de 1–2 s
     * observés au zoom 8/9 sur iPad, sans retirer aucune zone SIA.
     */
    const scaleNm = getCurrentNpfScaleNm();
    const combinedHeavyDecorationLoad = !!(siaMapAirspacesVisible && showRoadOverlayLayer && showHighVoltageLinesLayer);
    const combinedHeavyLightweight = combinedHeavyDecorationLoad && Number.isFinite(scaleNm) && scaleNm >= 5;
    if (scaleNm >= SIA_DECORATION_LIGHTWEIGHT_SCALE_NM || combinedHeavyLightweight) {
        throwIfSiaRefreshObsolete(refreshGeneration);
        npfDiagSiaInteraction(
            'SIA DÉCORATIONS',
            `zones=0/${features.length} · labels=0 · zoom=${map?.getZoom?.() ?? '—'} · progressif=oui · allégées=oui · charge-combinée=${combinedHeavyLightweight ? 'oui' : 'non'} · echelle=${Number.isFinite(scaleNm) ? scaleNm.toFixed(1) : '—'}NM`,
            { dureeMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - npfDiagStartedAt) }
        );
        return;
    }

    const decorationFeatures = getSiaDecorationFeaturesForCurrentView(features);
    const labelState = { points: [], count: 0 };

    for (let index = 0; index < decorationFeatures.length; index += 1) {
        throwIfSiaRefreshObsolete(refreshGeneration);
        if (runId !== siaDecorationProgressiveRun) {
            const error = new Error('Décorations SIA remplacées par une vue plus récente');
            error.name = SIA_REFRESH_ABORT_ERROR_NAME;
            throw error;
        }
        const feature = decorationFeatures[index];
        const item = feature?.properties?.siaItem;
        if (item && Number(item?.co || 0) !== 1) {
            const itemStyle = getSiaAirspaceStyle(item);
            const layers = addSiaCtrInnerBand(feature.geometry, itemStyle.color);
            if (Array.isArray(layers)) siaZoomDependentLayers.push(...layers);
        }
        if ((index + 1) % SIA_DECORATION_BATCH_SIZE === 0) {
            await yieldSiaRefreshToMap(refreshGeneration);
        }
    }

    const labelFeatures = decorationFeatures
        .filter(feature => Number(feature?.properties?.siaItem?.co || 0) !== 1)
        .sort((a, b) =>
            getSiaBoundaryLabelPriority(a.properties.siaItem)
            - getSiaBoundaryLabelPriority(b.properties.siaItem)
        );

    for (let index = 0; index < labelFeatures.length; index += 1) {
        throwIfSiaRefreshObsolete(refreshGeneration);
        if (runId !== siaDecorationProgressiveRun) {
            const error = new Error('Décorations SIA remplacées par une vue plus récente');
            error.name = SIA_REFRESH_ABORT_ERROR_NAME;
            throw error;
        }
        const feature = labelFeatures[index];
        const marker = addSiaAirspaceBoundaryLabel(
            feature.properties.siaItem,
            feature.geometry,
            labelState
        );
        if (marker) siaZoomDependentLayers.push(marker);
        if ((index + 1) % SIA_DECORATION_BATCH_SIZE === 0) {
            await yieldSiaRefreshToMap(refreshGeneration);
        }
    }

    npfDiagSiaInteraction(
        'SIA DÉCORATIONS',
        `zones=${decorationFeatures.length}/${features.length} · labels=${labelState.count} · zoom=${map?.getZoom?.() ?? '—'} · progressif=oui`,
        { dureeMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - npfDiagStartedAt) }
    );
}

function scheduleSiaMoveDecorationRefresh(reason = 'moveend-idle') {
    clearTimeout(siaMoveDecorationRefreshTimer);
    siaMoveDecorationRefreshTimer = setTimeout(async () => {
        siaMoveDecorationRefreshTimer = null;
        if (!map || !siaMapAirspacesVisible || !Array.isArray(siaRenderedAirspaceFeatures)) return;
        if (!siaRenderedAirspaceFeatures.length) return;

        const startedAt = NPF_STARTUP_DIAGNOSTIC.now();
        const refreshGeneration = getSiaRefreshGeneration();
        try {
            await renderSiaZoomDependentDecorationsProgressive(
                siaRenderedAirspaceFeatures,
                refreshGeneration
            );
            scheduleSiaProfileRefresh('sia-moveend-idle-decorations');
            npfDiagSiaInteraction(
                'SIA RAFRAÎCHISSEMENT',
                `raison=${reason} · décorations différées progressives · zones=${siaRenderedAirspaceFeatures.length} · zoom=${map.getZoom()}`,
                { totalMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - startedAt) }
            );
        } catch (error) {
            if (error?.name !== SIA_REFRESH_ABORT_ERROR_NAME) {
                console.warn('[SIA] Décorations différées impossibles:', error);
            }
        }
    }, SIA_MOVE_DECORATION_IDLE_MS);
}

const SIA_REFRESH_ABORT_ERROR_NAME = 'NpfSiaRefreshAborted';

function getSiaRefreshGeneration() {
    return Number(window.__npfSiaRefreshGeneration) || 0;
}

function throwIfSiaRefreshObsolete(refreshGeneration) {
    if (getSiaRefreshGeneration() === refreshGeneration) return;
    const error = new Error('Rendu SIA devenu obsolète');
    error.name = SIA_REFRESH_ABORT_ERROR_NAME;
    throw error;
}

async function yieldSiaRefreshToMap(refreshGeneration) {
    await new Promise(resolve => {
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => resolve());
        } else {
            setTimeout(resolve, 0);
        }
    });
    throwIfSiaRefreshObsolete(refreshGeneration);
}

async function addSiaDesignatedPointsToExistingCoverage(dataset, bounds, refreshGeneration) {
    if (!map || !siaLayerGroup || !dataset || !bounds) return 0;
    let rendered = 0;
    let scanIndex = 0;
    const zoom = map.getZoom();

    for (const item of dataset.points || []) {
        scanIndex += 1;
        if (scanIndex % 512 === 0) {
            await yieldSiaRefreshToMap(refreshGeneration);
        }
        if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
        if (item.k === 'dpn:VRP' && !siaMapVrpVisible) continue;
        const latlng = L.latLng(Number(item.x), Number(item.y));
        if (!bounds.contains(latlng)) continue;

        const popupHtml = buildSiaPointPopup(item);
        if (item.k === 'dpn:VRP') {
            const symbolText = getSiaVrpSymbolText(item);
            const size = getSiaVrpVisualSize(symbolText);
            const vrpVisual = getSiaVrpAirportVisual(item);
            const marker = L.marker(latlng, {
                pane: 'siaPointPane',
                interactive: true,
                bubblingMouseEvents: false,
                keyboard: false,
                icon: L.divIcon({
                    className: 'sia-vrp-div-icon',
                    html: `<span class="sia-vrp-symbol" style="--sia-vrp-bg:${vrpVisual.background};--sia-vrp-fg:${vrpVisual.foreground};width:${size}px;height:${size}px;font-size:${symbolText.length >= 5 ? 7 : symbolText.length === 4 ? 8 : symbolText.length === 3 ? 9 : 11}px">${escapeHtml(symbolText)}</span>`,
                    iconSize: [size, size],
                    iconAnchor: [size / 2, size / 2]
                })
            });
            marker.bindPopup(popupHtml, { maxWidth: 340 });
            marker.on('popupopen', () => marker.setPopupContent(buildSiaPointPopup(item)));
            marker.addTo(siaLayerGroup);
            addSiaTouchHitbox(latlng, popupHtml, () => buildSiaPointPopup(item));
            rendered += 1;
            continue;
        }

        const marker = L.circleMarker(latlng, {
            ...getSiaPointMarkerStyle(item),
            pane: 'siaPointPane',
            renderer: siaPointRenderer,
            interactive: true,
            bubblingMouseEvents: false
        });
        marker.bindPopup(popupHtml, { maxWidth: 340 });

        const label = String(item.d || item.c || '').trim();
        if (zoom >= 8 && label && item.k !== 'dpn:ADHP') {
            marker.bindTooltip(escapeHtml(label), {
                permanent: true,
                direction: 'right',
                offset: [5, 0],
                className: 'sia-point-label'
            });
        }
        marker.addTo(siaLayerGroup);
        addSiaTouchHitbox(latlng, popupHtml);
        rendered += 1;
    }
    return rendered;
}

async function refreshSiaLayers(reason = 'manual') {
    if (!map) return;
    ensureSiaMapPanes();

    const npfDiagRefreshStartedAt = NPF_STARTUP_DIAGNOSTIC.now();
    let npfDiagDatasetMs = 0;
    let npfDiagScanMs = 0;
    let npfDiagGeoJsonMs = 0;
    let npfDiagTouchDecorMs = 0;
    let npfDiagPointsMs = 0;
    let npfDiagCommitMs = 0;
    let npfDiagVisibleZones = 0;
    let npfDiagRenderedObjects = 0;

    const refreshGeneration = getSiaRefreshGeneration();
    let previousSiaLayerGroupForSwap = null;
    let replacementSiaLayerGroupForSwap = null;
    let replacementSiaLayerGroupCommitted = false;

    if (siaRefreshInProgress) {
        siaRefreshPendingReason = reason;
        return;
    }

    siaRefreshInProgress = true;
    siaRefreshCurrentReason = String(reason || 'manual');
    try {
        if (!hasAnyEnabledSiaFilter()) {
            clearSiaRenderedLayers();
            return;
        }

        const currentBounds = map.getBounds();
        const zoom = map.getZoom();
        const signature = getSiaRenderSignature();

        if (
            reason === 'gps-follow'
            && siaRenderedCoverageBounds
            && siaRenderedZoom === zoom
            && siaRenderedSignature === signature
            && siaBoundsFullyContains(siaRenderedCoverageBounds, currentBounds)
        ) {
            cancelObsoleteSiaMapMotionWork('gps-follow-contained-execution');
            return;
        }
        const showSiaDesignatedPointsNow = shouldDisplaySiaDesignatedPoints();
        const pointLabelsEnabledNow = zoom >= 8;

        /*
         * v16.37 — retour vers une vue rapprochée : ne plus réutiliser la
         * couverture très large d'un zoom 7/8/9 lorsque les points SIA
         * désignés doivent réapparaître. Le DIAG v16.34-v16.36 montre que
         * l'ajout de plusieurs centaines de points sur l'ancien grand tampon
         * (jusqu'à ~500 points) coûte davantage qu'une reconstruction normale
         * centrée sur le nouveau viewport. Dans ce cas, on laisse donc le
         * chemin de rendu complet ci-dessous reconstruire un tampon adapté au
         * zoom courant. Les autres réutilisations de zoom restent conservées.
         */

        /*
         * v15.80 — zoom dans une couverture déjà chargée : conserver volumes,
         * points et hitboxes. Seules les bandes intérieures et étiquettes de
         * zones, dépendantes des pixels écran, sont recalculées.
         */
        if (
            reason === 'zoomend'
            && siaRenderedCoverageBounds
            && siaRenderedSignature === signature
            && siaBoundsFullyContains(siaRenderedCoverageBounds, currentBounds)
            && siaRenderedShowDesignatedPoints === showSiaDesignatedPointsNow
            && siaRenderedPointLabelsEnabled === pointLabelsEnabledNow
            && Array.isArray(siaRenderedAirspaceFeatures)
        ) {
            const npfDiagDecorStart = NPF_STARTUP_DIAGNOSTIC.now();
            await renderSiaZoomDependentDecorationsProgressive(
                siaRenderedAirspaceFeatures,
                refreshGeneration
            );
            npfDiagTouchDecorMs += NPF_STARTUP_DIAGNOSTIC.now() - npfDiagDecorStart;
            siaRenderedZoom = zoom;
            scheduleSiaProfileRefresh('sia-zoomend-decorations');
            npfDiagSiaInteraction(
                'SIA RAFRAÎCHISSEMENT',
                `raison=${reason} · décorations seules · zones=${siaRenderedAirspaceFeatures.length} · zoom=${zoom}`,
                {
                    totalMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - npfDiagRefreshStartedAt),
                    decorationsMs: Math.round(npfDiagTouchDecorMs)
                }
            );
            return;
        }

        // Pan dans une couverture déjà dessinée : aucune reconstruction immédiate.
        // Les volumes/points suivent Leaflet ; les décorations sont recalculées après repos.
        if (
            reason === 'moveend'
            && siaRenderedCoverageBounds
            && siaRenderedZoom === zoom
            && siaRenderedSignature === signature
            && siaBoundsFullyContains(siaRenderedCoverageBounds, currentBounds)
        ) {
            scheduleSiaMoveDecorationRefresh('moveend-refresh-contained');
            scheduleSiaProfileRefresh('sia-moveend-contained');
            npfDiagSiaInteraction(
                'SIA RAFRAÎCHISSEMENT',
                `raison=${reason} · rendu conservé · décorations différées · zones=${Array.isArray(siaRenderedAirspaceFeatures) ? siaRenderedAirspaceFeatures.length : 0} · zoom=${zoom}`,
                { totalMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - npfDiagRefreshStartedAt) }
            );
            return;
        }

        clearTimeout(siaMoveDecorationRefreshTimer);
        siaMoveDecorationRefreshTimer = null;

        const npfDiagDatasetStart = NPF_STARTUP_DIAGNOSTIC.now();
        const dataset = await ensureSiaDatasetLoaded();
        npfDiagDatasetMs = NPF_STARTUP_DIAGNOSTIC.now() - npfDiagDatasetStart;
        throwIfSiaRefreshObsolete(refreshGeneration);
        // v15.83 — inutile de scanner les familles TMA lorsque les volumes sont masqués.
        const siaTmaOperationalFamilies = siaMapAirspacesVisible
            ? buildSiaTmaOperationalFamilySet(dataset)
            : null;

        /*
         * v15.82 — le double tampon n'est utile que lorsque les volumes SIA sont
         * visibles. Zones masquées : libérer immédiatement l'ancien groupe évite
         * de conserver deux jeux de marqueurs/points pendant la reconstruction.
         */
        const siaCombinedHeavyMapLoad = siaMapAirspacesVisible && showRoadOverlayLayer && showHighVoltageLinesLayer;
        /* v16.57 — sous charge combinée, jamais deux jeux SIA simultanés,
         * quel que soit le zoom : stabilité mémoire prioritaire sur iPad. */
        const preservePreviousSiaDuringRebuild = siaMapAirspacesVisible
            && !siaCombinedHeavyMapLoad;
        previousSiaLayerGroupForSwap = siaLayerGroup;
        replacementSiaLayerGroupForSwap = L.layerGroup();
        siaLayerGroup = replacementSiaLayerGroupForSwap;

        if (
            !preservePreviousSiaDuringRebuild
            && previousSiaLayerGroupForSwap
        ) {
            try {
                if (map.hasLayer(previousSiaLayerGroupForSwap)) {
                    map.removeLayer(previousSiaLayerGroupForSwap);
                }
                previousSiaLayerGroupForSwap.clearLayers();
            } catch (_) {}
            previousSiaLayerGroupForSwap = null;
            /* v16.57 — l'ancien groupe n'existe plus : sa couverture ne doit
             * jamais être réutilisée si le nouveau rendu est interrompu par un zoom. */
            siaRenderedCoverageBounds = null;
            siaRenderedZoom = null;
            siaRenderedSignature = '';
            siaRenderedAirspaceFeatures = [];
            siaRenderedShowDesignatedPoints = null;
            siaRenderedPointLabelsEnabled = null;
        }

        siaSelectedCtrTouchLayer = null;
        siaAirspaceTouchEntries = [];
        siaZoomDependentLayers = [];

        // Charger légèrement au-delà du viewport évite les reconstructions à
        // chaque mouvement du suivi GPS tout en bornant la mémoire Safari/iPad.
        const renderPadRatio = siaMapAirspacesVisible
            ? (siaCombinedHeavyMapLoad
                ? SIA_COMBINED_HEAVY_RENDER_PAD_RATIO
                : SIA_RENDER_BOUNDS_PAD_RATIO)
            : SIA_POINT_ONLY_RENDER_BOUNDS_PAD_RATIO;
        const renderBounds = currentBounds.pad(renderPadRatio);
        const pointBounds = renderBounds.pad(0.03);
        let rendered = 0;

        const visibleAirspaceFeatures = [];
        const npfDiagScanStart = NPF_STARTUP_DIAGNOSTIC.now();

        if (siaMapAirspacesVisible) {
            let siaAirspaceScanIndex = 0;
            for (const item of dataset.airspaces || []) {
                siaAirspaceScanIndex += 1;
                if (siaAirspaceScanIndex % 768 === 0) {
                    await yieldSiaRefreshToMap(refreshGeneration);
                }
                if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
                if (shouldHideSiaAirspaceAboveFl115(item)) continue;
                if (isSiaTechnicalTmaUnionParent(item)) continue;
                if (isSiaTechnicalSivParent(item, dataset)) continue;
                if (isSiaGenericTmaWithoutAltitude(item, siaTmaOperationalFamilies)) continue;
                if (!item.g) continue;
                if (!siaBoundsIntersects(item.b, renderBounds)) continue;

                const geometry = getSiaCachedGeometry(item);
                if (!geometry) continue;

                visibleAirspaceFeatures.push({
                    type: 'Feature',
                    properties: { siaItem: item },
                    geometry
                });
            }
        }
        npfDiagScanMs = NPF_STARTUP_DIAGNOSTIC.now() - npfDiagScanStart;
        npfDiagVisibleZones = visibleAirspaceFeatures.length;

        if (visibleAirspaceFeatures.length) {
            const npfDiagGeoStart = NPF_STARTUP_DIAGNOSTIC.now();
            const airspaceLayer = L.geoJSON(
                { type: 'FeatureCollection', features: visibleAirspaceFeatures },
                {
                    pane: 'siaAirspacePane',
                    renderer: siaAirspaceRenderer,
                    style: feature => getSiaAirspaceStyle(feature.properties.siaItem),
                    pointToLayer: (feature, latlng) => {
                        const itemStyle = getSiaAirspaceStyle(feature.properties.siaItem);
                        return L.circleMarker(latlng, {
                            pane: 'siaAirspacePane',
                            renderer: siaAirspaceRenderer,
                            radius: 5,
                            color: itemStyle.color,
                            weight: 2,
                            fillColor: itemStyle.color,
                            fillOpacity: 0.85
                        });
                    },
                    onEachFeature: (_feature, layer) => {
                        try { layer.options.interactive = false; } catch (_) {}
                    }
                }
            );
            airspaceLayer.addTo(siaLayerGroup);
            npfDiagGeoJsonMs = NPF_STARTUP_DIAGNOSTIC.now() - npfDiagGeoStart;

            const npfDiagTouchStart = NPF_STARTUP_DIAGNOSTIC.now();
            /*
             * v16.35 — zoom arrière / vue allégée : la très grande majorité des
             * volumes ne crée plus de calque tactile Leaflet depuis v15.75 ; elle
             * ajoute seulement une entrée géométrique dans siaAirspaceTouchEntries.
             * Rendre la main toutes les 24 zones imposait donc artificiellement
             * ~16 ms de délai par lot (jusqu'à ~0,8 s pour 1 100+ zones), alors
             * que le travail entre deux yields est minime. À >= 10 NM, on conserve
             * les mêmes données et la même sélection Zone mais on espace fortement
             * les yields. Les vues rapprochées gardent le lot prudent historique.
             */
            const siaTouchScaleNm = getCurrentNpfScaleNm();
            const siaTouchBatchSize = siaTouchScaleNm >= SIA_DECORATION_LIGHTWEIGHT_SCALE_NM
                ? SIA_TOUCH_SURFACE_LIGHTWEIGHT_BATCH_SIZE
                : SIA_TOUCH_SURFACE_BATCH_SIZE;

            for (let index = 0; index < visibleAirspaceFeatures.length; index += 1) {
                throwIfSiaRefreshObsolete(refreshGeneration);
                addSiaCtrTouchSurface(visibleAirspaceFeatures[index]);
                if ((index + 1) % siaTouchBatchSize === 0) {
                    await yieldSiaRefreshToMap(refreshGeneration);
                }
            }

            await renderSiaZoomDependentDecorationsProgressive(
                visibleAirspaceFeatures,
                refreshGeneration
            );
            npfDiagTouchDecorMs = NPF_STARTUP_DIAGNOSTIC.now() - npfDiagTouchStart;
            rendered += visibleAirspaceFeatures.length;
        }

        const showSiaDesignatedPoints = showSiaDesignatedPointsNow;
        const npfDiagPointsStart = NPF_STARTUP_DIAGNOSTIC.now();

        let siaTerrainScanIndex = 0;
        for (const item of dataset.terrain || []) {
            siaTerrainScanIndex += 1;
            if (siaTerrainScanIndex % 256 === 0) {
                await yieldSiaRefreshToMap(refreshGeneration);
            }
            if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
            const latlng = L.latLng(Number(item.x), Number(item.y));
            if (!pointBounds.contains(latlng)) continue;

            const terrainPopupHtml = buildSiaTerrainPopup(item);
            const marker = L.circleMarker(latlng, {
                ...getSiaTerrainMarkerStyle(item),
                pane: 'siaPointPane',
                renderer: siaPointRenderer,
                interactive: true,
                bubblingMouseEvents: false
            });
            marker.bindPopup(terrainPopupHtml, { maxWidth: 320 });
            if (zoom >= 8 && item.c) {
                marker.bindTooltip(escapeHtml(item.c), {
                    permanent: true,
                    direction: 'right',
                    offset: [5, 0],
                    className: 'sia-point-label sia-terrain-label'
                });
            }
            marker.addTo(siaLayerGroup);
            addSiaTouchHitbox(latlng, terrainPopupHtml);
            rendered += 1;
        }

        let siaPointScanIndex = 0;
        for (const item of dataset.points || []) {
            if (!showSiaDesignatedPoints) break;
            siaPointScanIndex += 1;
            if (siaPointScanIndex % 512 === 0) {
                await yieldSiaRefreshToMap(refreshGeneration);
            }
            if (!isSiaFilterEnabled(getSiaEffectiveFilterKey(item))) continue;
            if (item.k === 'dpn:VRP' && !siaMapVrpVisible) continue;
            const latlng = L.latLng(Number(item.x), Number(item.y));
            if (!pointBounds.contains(latlng)) continue;

            const popupHtml = buildSiaPointPopup(item);

            if (item.k === 'dpn:VRP') {
                const symbolText = getSiaVrpSymbolText(item);
                const size = getSiaVrpVisualSize(symbolText);
                const vrpVisual = getSiaVrpAirportVisual(item);
                const marker = L.marker(latlng, {
                    pane: 'siaPointPane',
                    interactive: true,
                    bubblingMouseEvents: false,
                    keyboard: false,
                    icon: L.divIcon({
                        className: 'sia-vrp-div-icon',
                        html: `<span class="sia-vrp-symbol" style="--sia-vrp-bg:${vrpVisual.background};--sia-vrp-fg:${vrpVisual.foreground};width:${size}px;height:${size}px;font-size:${symbolText.length >= 5 ? 7 : symbolText.length === 4 ? 8 : symbolText.length === 3 ? 9 : 11}px">${escapeHtml(symbolText)}</span>`,
                        iconSize: [size, size],
                        iconAnchor: [size / 2, size / 2]
                    })
                });
                marker.bindPopup(popupHtml, { maxWidth: 340 });
                marker.on('popupopen', () => marker.setPopupContent(buildSiaPointPopup(item)));
                marker.addTo(siaLayerGroup);
                addSiaTouchHitbox(latlng, popupHtml, () => buildSiaPointPopup(item));
                rendered += 1;
                continue;
            }

            const marker = L.circleMarker(latlng, {
                ...getSiaPointMarkerStyle(item),
                pane: 'siaPointPane',
                renderer: siaPointRenderer,
                interactive: true,
                bubblingMouseEvents: false
            });
            marker.bindPopup(popupHtml, { maxWidth: 340 });

            const label = String(item.d || item.c || '').trim();
            if (zoom >= 8 && label && item.k !== 'dpn:ADHP') {
                marker.bindTooltip(escapeHtml(label), {
                    permanent: true,
                    direction: 'right',
                    offset: [5, 0],
                    className: 'sia-point-label'
                });
            }
            marker.addTo(siaLayerGroup);
            addSiaTouchHitbox(latlng, popupHtml);
            rendered += 1;
        }
        npfDiagPointsMs = NPF_STARTUP_DIAGNOSTIC.now() - npfDiagPointsStart;

        throwIfSiaRefreshObsolete(refreshGeneration);

        /* Le nouveau groupe devient visible d'un bloc, puis l'ancien est retiré. */
        const npfDiagCommitStart = NPF_STARTUP_DIAGNOSTIC.now();
        replacementSiaLayerGroupForSwap.addTo(map);
        if (
            previousSiaLayerGroupForSwap
            && previousSiaLayerGroupForSwap !== replacementSiaLayerGroupForSwap
            && map.hasLayer(previousSiaLayerGroupForSwap)
        ) {
            map.removeLayer(previousSiaLayerGroupForSwap);
        }
        replacementSiaLayerGroupCommitted = true;
        npfDiagCommitMs = NPF_STARTUP_DIAGNOSTIC.now() - npfDiagCommitStart;
        npfDiagRenderedObjects = rendered;

        // Couverture et signature ne sont validées qu'après un rendu complet.
        siaRenderedCoverageBounds = renderBounds;
        siaRenderedZoom = zoom;
        siaRenderedSignature = signature;
        siaRenderedAirspaceFeatures = visibleAirspaceFeatures;
        siaRenderedShowDesignatedPoints = showSiaDesignatedPointsNow;
        siaRenderedPointLabelsEnabled = pointLabelsEnabledNow;
        if (reason === 'startup-prefs') {
            armSiaStartupPassiveMoveendGuard();
        }

        const footer = document.getElementById('sia-filter-footer-status');
        if (footer) {
            const scaleNote = showSiaDesignatedPoints
                ? ''
                : ' Points SIA masqués : ils apparaissent à partir de l’échelle 5 NM.';
            const zonesNote = siaMapAirspacesVisible
                ? ''
                : ' Zones carte masquées.';
            footer.textContent = `${rendered} objet${rendered > 1 ? 's' : ''} SIA affiché${rendered > 1 ? 's' : ''} dans la zone chargée.${zonesNote}${scaleNote}`;
        }

        npfDiagSiaInteraction(
            'SIA RAFRAÎCHISSEMENT',
            `raison=${reason} · zones=${npfDiagVisibleZones} · objets=${npfDiagRenderedObjects} · zoom=${zoom} · carteZones=${siaMapAirspacesVisible ? 'ON' : 'OFF'}`,
            {
                totalMs: Math.round(NPF_STARTUP_DIAGNOSTIC.now() - npfDiagRefreshStartedAt),
                datasetMs: Math.round(npfDiagDatasetMs),
                scanMs: Math.round(npfDiagScanMs),
                geoJsonMs: Math.round(npfDiagGeoJsonMs),
                touchDecorMs: Math.round(npfDiagTouchDecorMs),
                pointsMs: Math.round(npfDiagPointsMs),
                commitMs: Math.round(npfDiagCommitMs)
            }
        );

        scheduleSiaProfileRefresh(`sia-${reason}`);
    } catch (error) {
        /* En cas d'échec, conserver intégralement l'ancien rendu opérationnel. */
        if (replacementSiaLayerGroupForSwap && !replacementSiaLayerGroupCommitted) {
            try { replacementSiaLayerGroupForSwap.clearLayers(); } catch (_) {}
            siaLayerGroup = previousSiaLayerGroupForSwap;
        }
        if (error?.name === SIA_REFRESH_ABORT_ERROR_NAME) {
            return;
        }
        throw error;
    } finally {
        if (String(reason || '') === 'zoomend-after-routes-ht') {
            siaHeavyZoomFinalRefreshPending = false;
        }
        siaRefreshInProgress = false;
        siaRefreshCurrentReason = null;
        const pending = siaRefreshPendingReason;
        siaRefreshPendingReason = null;
        if (pending) scheduleSiaLayerRefresh(pending);
    }
}

